; h264rgb13.s - V13 quiet public-output build
; PiStorm / Emu68 H264 RGB player - V9 based on hardware-proven V9 192x144/max25
; H264 MMAL bounded-memory streaming: dynamic frame count until decoder OUTPUT EOS -> native HAM6 RGB
; V10P: V10G playback path + first-MMAL-ERRO payload/context diagnostic and immediate controlled stop
; Speed experiment: TEST49-identical adaptive HAM decisions through Fast-RAM LUTs.
; Amiga 500 + PiStorm + Raspberry Pi 3A+
;
; Based on the working TEST09 firmware-init path plus the VCHIQ connect
; sequence used by Linux/RusPiRo:
;   local slot 34, CONNECT header, tx_pos=8, trigger VC, poll remote tx_pos.
;
; V10P target: keep V10G playback/restart semantics unchanged and turn 1.mkv's ERRO flood
; into one useful diagnostic. The first MMAL ERROR event is decoded (4-byte MMAL_STATUS_T),
; the last submitted MKV/MMAL input context is printed, then streaming stops immediately.
; No codec, demux, frame-flag, buffer-size or restart policy is changed in this test.

        section code,code

; ---- AmigaOS LVOs ----
AllocMem        equ -198
FreeMem         equ -210
AvailMem        equ -216
AddResource     equ -486
OpenResource    equ -498
OldOpenLibrary  equ -408
CloseLibrary    equ -414
CachePreDMA     equ -762
CachePostDMA    equ -768
AddIntServer    equ -168
RemIntServer    equ -174
SetSignal       equ -306

SIGBREAKF_CTRL_C equ $00001000      ; AmigaDOS Ctrl-C break signal (bit 12)

Open            equ -30
Close           equ -36
Read            equ -42
Write           equ -48
Seek            equ -66
Output          equ -60
Delay           equ -198

MODE_OLDFILE    equ 1005
MODE_NEWFILE    equ 1006
OFFSET_BEGINNING equ -1
OFFSET_CURRENT   equ 0
OFFSET_END       equ 1

V12E_MAX_MOOV    equ $00800000      ; bounded metadata allocation, movie payload stays on disk

; ---- Memory ----
MEMF_FASTCLEAR  equ $00010004
MEMF_CHIPCLEAR  equ $00010002
MEMF_PUBLICFASTCLEAR equ $00010005
MEMF_CHIP       equ $00000002
MEMF_FAST       equ $00000004

; ---- V10 external speed LUTs ----
V10_HAM_LUT_SIZE    equ $01000000      ; 16 MiB ham.bin
V10_EDGE_LUT_SIZE   equ $00200000      ;  2 MiB edge.bin
V10_STATE_LUT_SIZE  equ $00080000      ; 512 KiB state.bin
V10_LUT_TOTAL_SIZE  equ $01280000      ; 18.5 MiB total
V10_MKV_PROBE_SIZE  equ $00200000      ; first 2 MiB are enough for the initial MKV structure/PTS probe
V10P_IO_SIZE       equ $00010000      ; 64 KiB bounded MKV input window
V10P_MAX_ELEM_SIZE equ $7FFFFFFF      ; first streaming version uses 32-bit file offsets/sizes

; ---- V10 guarded HAM6 Chip allocation ----
; Keep the Exec allocation base immutable and place 64-byte canaries on both
; sides of the actual two-frame HAM6 area. This makes a small overrun visible
; without immediately damaging the Exec memory-list header.
V10_CHIP_GUARD       equ 64
V10_CHIP_ALLOC_BYTES equ T30_CHIP_BYTES+(V10_CHIP_GUARD*2)
V10_GUARD_PRE        equ $A55AA55A
V10_GUARD_POST       equ $5AA55AA5

; ---- TEST61 compact native HAM6 playback ----
; Agnus now fetches exactly the same 192x144x6 planar layout produced in Fast RAM.
T30_PLANE_BYTES equ 3456             ; 24 bytes/row * 144
T30_FRAME_BYTES equ 20736            ; six compact 192x144 1-bit planes (HAM6)
T30_FAST_BYTES  equ 20736            ; legacy helper constant; live scratch is identical
T30_CHIP_BYTES  equ 41472            ; two 20736-byte Chip-RAM HAM6 display buffers
T56_SHADOW_BYTES equ 41472           ; Fast mirrors of both Chip display buffers for 8x-unrolled dirty-copy
T30_GROUPS      equ 3456             ; legacy helper constant
T30_PLANE2_OFF  equ 6912
T30_PLANE3_OFF  equ 10368
T30_PLANE4_OFF  equ 13824
T30_PLANE5_OFF  equ 17280

; ---- TEST61 compact Fast-RAM HAM6 image: centered 192x144 crop ----
T37_FAST_PLANE_BYTES equ 3456          ; 24 bytes/row * 144
T37_FAST_FRAME_BYTES equ 20736         ; six compact 192x144 planes
T37_FAST_PLANE2_OFF  equ 6912
T37_FAST_PLANE3_OFF  equ 10368
T37_FAST_PLANE4_OFF  equ 13824
T44_FAST_PLANE5_OFF  equ 17280

CUSTOM_BASE     equ $00DFF000
VPOSR           equ $004
VHPOSR          equ $006
COPJMP1         equ $088
DIWSTRT         equ $08E
DIWSTOP         equ $090
DDFSTRT         equ $092
DDFSTOP         equ $094
DMACON          equ $096
BPL1PTH         equ $0E0
BPL1PTL         equ $0E2
BPLCON0         equ $100
BPLCON1         equ $102
BPLCON2         equ $104
BPL1MOD         equ $108
BPL2MOD         equ $10A
COLOR00         equ $180

SLOT_SIZE       equ $00001000
SLOT_MEM_SIZE   equ $00041000        ; 65 * 4096
FRAG_MEM_SIZE   equ $00002000
DMA_MEM_SIZE    equ $00043000
ALLOC_SIZE      equ $00044000

; ---- V10 persistent VCHIQ rendezvous resource ----
; A tiny Exec resource survives the CLI process and remembers the global
; VCHIQ slot allocation. Second invocation can therefore find the exact
; shared-memory block without calling the one-shot firmware VCHIQ_INIT again.
V10_RES_SIZE       equ 96
V10_RES_MAGIC      equ $48325643        ; 'H2VC'
V10_RES_VERSION    equ 1
V10_RES_MAGIC_OFS  equ 16
V10_RES_VER_OFS    equ 20
V10_RES_ALLOC_OFS  equ 24
V10_RES_PTR_OFS    equ 28
V10_RES_BUS_OFS    equ 32
V10_RES_PHYS_OFS   equ 36
V10_RES_NAME_OFS   equ 48
NT_RESOURCE        equ 8

; ---- VCHIQ ----
VCHIQ_MAGIC     equ $56434849
VCHIQ_VERSION   equ 8
VCHIQ_VER_MIN   equ 3
SLOTZERO_SIZE   equ 1288
MAX_SLOTS       equ 128
MAX_SIDE        equ 64

MASTER_BASE     equ 32
SLAVE_BASE      equ 404

MASTER_INIT     equ MASTER_BASE+0
MASTER_FIRST    equ MASTER_BASE+4
MASTER_LAST     equ MASTER_BASE+8
MASTER_SYNC     equ MASTER_BASE+12
MASTER_TRIG_ARM equ MASTER_BASE+16
MASTER_TRIG_FIR equ MASTER_BASE+20
MASTER_TXPOS    equ MASTER_BASE+28
MASTER_RECYCLE_ARM equ MASTER_BASE+32
MASTER_RECYCLE_FIR equ MASTER_BASE+36
MASTER_RECYCLEQ equ MASTER_BASE+44
MASTER_QUEUE    equ MASTER_BASE+72

SLAVE_INIT      equ SLAVE_BASE+0
SLAVE_FIRST     equ SLAVE_BASE+4
SLAVE_LAST      equ SLAVE_BASE+8
SLAVE_SYNC      equ SLAVE_BASE+12
SLAVE_TRIG_ARM  equ SLAVE_BASE+16
SLAVE_TRIG_FIR  equ SLAVE_BASE+20
SLAVE_TXPOS     equ SLAVE_BASE+28
SLAVE_RECYCLEQ  equ SLAVE_BASE+44
SLAVE_SYNCREL_F equ SLAVE_BASE+64
SLAVE_QUEUE     equ SLAVE_BASE+72
SLAVE_DEBUG0    equ SLAVE_BASE+328

VCHIQ_MSG_CONNECT equ $01000000
VCHIQ_MSG_OPEN    equ $02000000
VCHIQ_MSG_OPENACK equ $03000000
VCHIQ_MSG_CLOSE   equ $04000000
VCHIQ_MSG_DATA    equ $05000000
VCHIQ_MSG_BULK_RX equ $06000000
VCHIQ_MSG_BULK_TX equ $07000000
VCHIQ_MSG_BULK_RX_DONE equ $08000000
VCHIQ_MSG_BULK_TX_DONE equ $09000000

; MMAL control service (official Raspberry Pi userland values)
MMAL_FOURCC       equ $6D6D616C        ; VCHIQ_MAKE_FOURCC('m','m','a','l')
MMAL_VER          equ 16
MMAL_VER_MIN      equ 10

; MMAL worker protocol. MMAL_MAGIC uses MMAL_FOURCC('m','m','a','l')
; from the MMAL worker message protocol (different numeric convention
; from the VCHIQ service FOURCC above).
MMAL_MAGIC        equ $6C616D6D
MMAL_GET_VERSION     equ 3
MMAL_COMPONENT_CREATE equ 4
MMAL_COMPONENT_DESTROY equ 5
MMAL_PORT_INFO_GET    equ 8
MMAL_PORT_INFO_SET    equ 9
MMAL_PORT_ACTION      equ 10
MMAL_COMPONENT_ENABLE equ 6
MMAL_COMPONENT_DISABLE equ 7
MMAL_BUFFER_FROM_HOST  equ 11
MMAL_BUFFER_TO_HOST    equ 12
MMAL_EVENT_TO_HOST     equ 16
MMAL_EVENT_ERROR       equ $4F525245      ; MMAL_EVENT_ERROR / 'ERRO' as printed little-endian

; Official MMAL_STATUS_T values (raspberrypi/userland mmal_types.h).
MMAL_SUCCESS           equ 0
MMAL_ENOMEM            equ 1
MMAL_ENOSPC            equ 2
MMAL_EINVAL            equ 3
MMAL_ENOSYS            equ 4
MMAL_ENOENT            equ 5
MMAL_ENXIO             equ 6
MMAL_EIO               equ 7
MMAL_ESPIPE             equ 8
MMAL_ECORRUPT          equ 9
MMAL_ENOTREADY         equ 10
MMAL_ECONFIG           equ 11
MMAL_EISCONN           equ 12
MMAL_ENOTCONN          equ 13
MMAL_EAGAIN            equ 14
MMAL_EFAULT            equ 15
MMAL_BUFFER_FROM_HOST_ZEROLEN equ 24
MMAL_PORT_ACTION_ENABLE equ 1
MMAL_PORT_ACTION_DISABLE equ 2
MMAL_PORT_ACTION_FLUSH  equ 3
MMAL_PORT_ACTION_CONNECT equ 4
MMAL_PORT_ACTION_SET_REQUIREMENTS equ 6

; TEST17: stable host-side cookies. These are opaque to VideoCore.
; TEST33: each input pool slot gets its own opaque context cookie.
MMAL_BUFFER_CONTEXT_BASE equ $18001000
INPUT_POOL_COUNT         equ 1
; V10P single-axis framing test:
; Keep one reusable MMAL input slot, but enlarge its payload capacity to
; 0x40000 (256 KiB).  1.mkv's largest compressed access unit is ~149 KiB,
; therefore every frame in that test file fits in ONE MMAL buffer and can be
; published atomically with FRAME_START|FRAME_END instead of being split at
; the old 64-KiB boundary.  The Matroska FILE reader window stays 64 KiB.
INPUT_DATA_SIZE          equ $00040000
INPUT_DATA_PAGES         equ 64
INPUT_PAGELIST_OFFSET    equ $00040000
INPUT_DMA_SPAN           equ $00041000
INPUT_SLOT_STRIDE        equ $00042000
EOS_SLOT_INDEX           equ INPUT_POOL_COUNT
INPUT_POOL_ALLOC_SIZE    equ $00085000   ; 2*0x42000 (1 data + 1 EOS) + alignment headroom

; Raw H264 keeps the proven 64-KiB read cadence.  The MMAL port itself has
; 256-KiB capacity in V10P; MKV uses that full capacity per access unit.
H264_FILE_LEN         equ 0       ; TEST33: Dateilaenge wird dynamisch per EOF bestimmt
H264_STREAM_CHUNK     equ $00010000
V10P_MKV_CHUNK        equ INPUT_DATA_SIZE
H264_MAX_DATA_LEN     equ INPUT_DATA_SIZE
TEST26_INPUT_TARGET   equ 0       ; TEST33: Anzahl Inputbloecke wird dynamisch gezaehlt
BULK_ALLOC_SIZE       equ INPUT_POOL_ALLOC_SIZE
BULK_DMA_SIZE         equ INPUT_DMA_SPAN
PAGELIST_WRITE      equ 0
PAGELIST_READ       equ 1

; Amiga Exec CachePreDMA/PostDMA flag:
; DMA device reads FROM RAM (used for pagelist/control memory).
DMA_ReadFromRAM     equ 8

; TEST19 output buffer
MMAL_OUTPUT_BUFFER_CONTEXT0 equ $19000002
MMAL_OUTPUT_BUFFER_CONTEXT1 equ $19000003
MMAL_OUTPUT_BUFFER_CONTEXT  equ MMAL_OUTPUT_BUFFER_CONTEXT0
MMAL_EOS_BUFFER_CONTEXT    equ $19E00001
MMAL_BUFFER_FLAG_EOS       equ 1
MMAL_BUFFER_FLAG_FRAME_START equ 2
MMAL_BUFFER_FLAG_FRAME_END   equ 4
MMAL_BUFFER_FLAG_CONFIG      equ 32
MMAL_BUFFER_FLAG_FRAME       equ 6
MMAL_ES_FORMAT_FLAG_FRAMED     equ 1
H264_CODEC_CONFIG_MAX          equ 128
H264_PROBE_SIZE                equ 4096
EOS_BULK_LEN               equ 8
OUTPUT_SLOT_STRIDE         equ $00071000 ; one max 640x480 I420 slot, 4-KiB rounded
OUTPUT_POOL_MAX            equ 20        ; V10P: host output pool cap
OUTPUT_ALLOC_EXTRA         equ $00003000 ; alignment + one serialized pagelist + guard slack
OUTPUT_MAX_DMA             equ $00070800 ; V6 max source 640x480 I420
V6_MAX_SRC_W               equ 1920
V6_MAX_SRC_H               equ 1080
V12_MAX_ALIGNED_H           equ 1088
MMAL_ENCODING_I420         equ $30323449
MMAL_ENCODING_OPAQUE       equ $5651504F        ; 'OPQV' - VideoCore opaque/zero-copy frame handle

MMAL_BUFFER_DATA_COOKIE equ $1700DA7A

MMAL_PORT_CONTROL     equ 1
MMAL_PORT_INPUT       equ 2
MMAL_PORT_OUTPUT      equ 3
MMAL_PORT_CLOCK       equ 4
MMAL_ES_VIDEO         equ 3
MMAL_ENCODING_H264    equ $34363248
MMAL_INPUT_USERDATA   equ $24681357
MMAL_TEST_CONTEXT    equ $12345678
MMAL_COMP_CONTEXT    equ $87654321
MMAL_CLIENT_COMPONENT equ $13572468

; ---- Pi3 MMIO mapped by Emu68 /soc/ranges ----
MBOX_READ       equ $F200B880
MBOX_STATUS     equ $F200B898
MBOX_WRITE      equ $F200B8A0

; VCHIQ node is bus 7e00b840 -> Emu68 f200b840.
; RusPiRo rings VC BELL2 at physical b848 => Emu68 f200b848.
VCHIQ_BELL2     equ $F200B848

MBOX_TX_FULL    equ $80000000
MBOX_RX_EMPTY   equ $40000000
MBOX_PROPERTY   equ 8

TIMEOUT         equ $00400000
POLL_COUNT      equ 100
V10_CLEANUP_POLL_COUNT equ 4096
POLL_DELAY      equ $00020000
V5_SPIN_TIMEOUT equ $04000000   ; watchdog only for formerly unbounded RGB/VBlank waits
INTB_VERTB      equ 5
NT_INTERRUPT    equ 2

start:
        bra.w   h264rgb_main

; --------------------------------------------------------------------
; h264rgb V1 command-line parser
;
; AmigaDOS CLI entry: D0 = command line length, A0 = command line bytes.
; Copies the first argument into t23_file_name. Quoted paths are accepted.
; Return D0=0 on success, D0=1 if no usable filename was supplied.
; --------------------------------------------------------------------
h264rgb_parse_arg:
        movem.l d1-d3/a0-a1,-(sp)

        move.l  h264rgb_cli_ptr,a0
        move.l  h264rgb_cli_len,d0
        tst.l   d0
        beq.w   h264rgb_parse_fail

h264rgb_skip_ws:
        tst.l   d0
        beq.w   h264rgb_parse_fail
        move.b  (a0),d1
        cmpi.b  #$20,d1
        beq.s   h264rgb_skip_one
        cmpi.b  #9,d1
        bne.s   h264rgb_arg_begin
h264rgb_skip_one:
        addq.l  #1,a0
        subq.l  #1,d0
        bra.s   h264rgb_skip_ws

h264rgb_arg_begin:
        lea     t23_file_name,a1
        clr.l   d3
        moveq   #0,d2
        cmpi.b  #$22,d1
        bne.s   h264rgb_copy_loop
        moveq   #1,d2
        addq.l  #1,a0
        subq.l  #1,d0

h264rgb_copy_loop:
        tst.l   d0
        beq.s   h264rgb_copy_done
        move.b  (a0)+,d1
        subq.l  #1,d0

        tst.b   d2
        beq.s   h264rgb_check_plain_end
        cmpi.b  #$22,d1
        beq.s   h264rgb_copy_done
        bra.s   h264rgb_store_char

h264rgb_check_plain_end:
        cmpi.b  #$20,d1
        beq.s   h264rgb_copy_done
        cmpi.b  #9,d1
        beq.s   h264rgb_copy_done
        cmpi.b  #10,d1
        beq.s   h264rgb_copy_done
        cmpi.b  #13,d1
        beq.s   h264rgb_copy_done

h264rgb_store_char:
        cmpi.l  #255,d3
        bcc.s   h264rgb_parse_fail
        move.b  d1,(a1)+
        addq.l  #1,d3
        bra.s   h264rgb_copy_loop

h264rgb_copy_done:
        tst.l   d3
        beq.s   h264rgb_parse_fail
        clr.b   (a1)
        moveq   #0,d0
        bra.s   h264rgb_parse_done

h264rgb_parse_fail:
        moveq   #1,d0
h264rgb_parse_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

; --------------------------------------------------------------------
; H264RGB4 - find SPS/PPS NAL units in the selected raw Annex-B H264 file.
;
; The probe reads the first 4096 bytes, recognises both 00 00 01 and
; 00 00 00 01 start codes, and extracts the first SPS (NAL type 7) and
; first PPS (NAL type 8), including their original Annex-B start codes.
; The two NAL units are concatenated into h264_file_extradata and the
; actual combined length is sent as MMAL extradata_size (max 128 bytes).
;
; Playback later reopens the same file from byte 0, so the stable live
; streaming path is unchanged.
;
; h264_find_nal input: D0 = wanted NAL type (7=SPS, 8=PPS)
; output: D0=1 found / 0 not found, A0=start-code pointer, D1=NAL bytes
;         through (but excluding) the following Annex-B start code.
; --------------------------------------------------------------------
h264_find_nal:
        movem.l d2-d7/a1-a3,-(sp)
        move.l  d0,d7
        lea     h264_probe_buf,a1
        move.l  h264_probe_read,d6
        move.l  a1,a3
        add.l   d6,a3

h264_find_scan:
        move.l  a3,d0
        sub.l   a1,d0
        cmp.l   #5,d0
        bcs.w   h264_find_not_found

        tst.b   (a1)
        bne.s   h264_find_advance
        tst.b   1(a1)
        bne.s   h264_find_advance
        cmp.b   #1,2(a1)
        beq.s   h264_find_start3
        tst.b   2(a1)
        bne.s   h264_find_advance
        cmp.b   #1,3(a1)
        beq.s   h264_find_start4

h264_find_advance:
        addq.l  #1,a1
        bra.w   h264_find_scan

h264_find_start3:
        moveq   #3,d2
        moveq   #0,d0
        move.b  3(a1),d0
        bra.s   h264_find_check_type

h264_find_start4:
        moveq   #4,d2
        moveq   #0,d0
        move.b  4(a1),d0

h264_find_check_type:
        and.l   #$1F,d0
        cmp.l   d7,d0
        beq.s   h264_find_target

        ; Skip this complete start code and its NAL header so a 4-byte
        ; start code cannot be rediscovered one byte later as a 3-byte code.
        add.l   d2,a1
        addq.l  #1,a1
        bra.w   h264_find_scan

h264_find_target:
        move.l  a1,a0
        move.l  a1,a2
        add.l   d2,a2
        addq.l  #1,a2

        ; Find the next Annex-B start code, which defines the end of this NAL.
h264_find_next:
        move.l  a3,d0
        sub.l   a2,d0
        cmp.l   #3,d0
        bcs.w   h264_find_not_found

        tst.b   (a2)
        bne.s   h264_find_next_advance
        tst.b   1(a2)
        bne.s   h264_find_next_advance
        cmp.b   #1,2(a2)
        beq.s   h264_find_boundary
        cmp.l   #4,d0
        bcs.s   h264_find_next_advance
        tst.b   2(a2)
        bne.s   h264_find_next_advance
        cmp.b   #1,3(a2)
        beq.s   h264_find_boundary

h264_find_next_advance:
        addq.l  #1,a2
        bra.w   h264_find_next

h264_find_boundary:
        move.l  a2,d1
        sub.l   a0,d1
        moveq   #1,d0
        bra.s   h264_find_done

h264_find_not_found:
        moveq   #0,d0
        clr.l   d1

h264_find_done:
        movem.l (sp)+,d2-d7/a1-a3
        rts


h264rgb_load_file_extradata:
        movem.l d1-d7/a0-a3/a6,-(sp)

        clr.l   h264_probe_handle
        clr.l   h264_probe_read
        clr.l   h264_codec_config_len
        clr.l   h264_sps_len
        clr.l   h264_pps_len

        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   h264rgb_probe_open_fail
        move.l  d0,h264_probe_handle

        move.l  d0,d1
        lea     h264_probe_buf,a0
        move.l  a0,d2
        move.l  #H264_PROBE_SIZE,d3
        move.l  a5,a6
        jsr     Read(a6)
        move.l  d0,h264_probe_read

        move.l  h264_probe_handle,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   h264_probe_handle

        move.l  h264_probe_read,d0
        cmp.l   #8,d0
        bcs.w   h264rgb_probe_read_fail

        moveq   #7,d0
        bsr     h264_find_nal
        tst.l   d0
        beq.w   h264rgb_probe_no_sps
        move.l  a0,h264_sps_ptr
        move.l  d1,h264_sps_len

        moveq   #8,d0
        bsr     h264_find_nal
        tst.l   d0
        beq.w   h264rgb_probe_no_pps
        move.l  a0,h264_pps_ptr
        move.l  d1,h264_pps_len

        move.l  h264_sps_len,d0
        add.l   h264_pps_len,d0
        tst.l   d0
        beq.w   h264rgb_probe_no_sps
        move.l  d0,h264_codec_config_len
        cmp.l   #H264_CODEC_CONFIG_MAX,d0
        bhi.w   h264rgb_probe_too_large

        ; Clear max-sized destination then concatenate SPS followed by PPS.
        lea     h264_file_extradata,a0
        moveq   #31,d7
h264rgb_extra_clear:
        clr.l   (a0)+
        dbra    d7,h264rgb_extra_clear

        move.l  h264_sps_ptr,a0
        lea     h264_file_extradata,a1
        move.l  h264_sps_len,d7
        subq.l  #1,d7
h264rgb_copy_sps:
        move.b  (a0)+,(a1)+
        dbra    d7,h264rgb_copy_sps

        move.l  h264_pps_ptr,a0
        move.l  h264_pps_len,d7
        subq.l  #1,d7
h264rgb_copy_pps:
        move.b  (a0)+,(a1)+
        dbra    d7,h264rgb_copy_pps

        lea     msg_hr4_sps,a1
        move.l  #msg_hr4_sps_end-msg_hr4_sps,d3
        jsr     print
        move.l  h264_sps_len,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_hr4_pps,a1
        move.l  #msg_hr4_pps_end-msg_hr4_pps,d3
        jsr     print
        move.l  h264_pps_len,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_hr4_extra,a1
        move.l  #msg_hr4_extra_end-msg_hr4_extra,d3
        jsr     print
        move.l  h264_codec_config_len,d0
        jsr     print_hex32
        jsr     newline

        moveq   #0,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_open_fail:
        lea     e_hr4_probe_open,a1
        move.l  #e_hr4_probe_open_end-e_hr4_probe_open,d3
        jsr     print
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_read_fail:
        lea     e_hr4_probe_read,a1
        move.l  #e_hr4_probe_read_end-e_hr4_probe_read,d3
        jsr     print
        move.l  h264_probe_read,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_no_sps:
        lea     e_hr4_no_sps,a1
        move.l  #e_hr4_no_sps_end-e_hr4_no_sps,d3
        jsr     print
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_no_pps:
        lea     e_hr4_no_pps,a1
        move.l  #e_hr4_no_pps_end-e_hr4_no_pps,d3
        jsr     print
        moveq   #1,d0
        bra.w   h264rgb_probe_done

h264rgb_probe_too_large:
        lea     e_hr4_too_large,a1
        move.l  #e_hr4_too_large_end-e_hr4_too_large,d3
        jsr     print
        move.l  h264_codec_config_len,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0

h264rgb_probe_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts


; ====================================================================
; V10 EXTERNAL LUT LOADER
; Keeps the executable small while preserving the exact same Fast-RAM
; lookup access pattern during HAM6 conversion.
; ====================================================================
; Input: D0=size, A0=filename, A1=address of pointer variable
; Output: D0=0 success, D0=1 failure. On failure this allocation is freed.
v9m_load_one_lut:
        movem.l d1-d7/a0-a3/a6,-(sp)
        move.l  d0,d7
        move.l  a0,a2
        move.l  a1,a3
        clr.l   (a3)

        move.l  a4,a6
        move.l  d7,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.s   v9m_load_one_fail
        move.l  d0,(a3)

        move.l  a5,a6
        move.l  a2,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.s   v9m_load_one_free_fail
        move.l  d0,d6

        move.l  d6,d1
        move.l  (a3),d2
        move.l  d7,d3
        move.l  a5,a6
        jsr     Read(a6)
        move.l  d0,d5

        move.l  d6,d1
        move.l  a5,a6
        jsr     Close(a6)

        cmp.l   d7,d5
        bne.s   v9m_load_one_free_fail
        moveq   #0,d0
        bra.s   v9m_load_one_done

v9m_load_one_free_fail:
        move.l  (a3),d0
        beq.s   v9m_load_one_fail
        move.l  d0,a1
        move.l  d7,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   (a3)

v9m_load_one_fail:
        moveq   #1,d0
v9m_load_one_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

v9m_load_luts:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v9m_ham_lut_ptr
        clr.l   v9m_edge_lut_ptr
        clr.l   v9m_state_lut_ptr

        lea     msg_v9m_lut_start,a1
        move.l  #msg_v9m_lut_start_end-msg_v9m_lut_start,d3
        jsr     print

        lea     v9m_ham_name,a0
        move.l  #V10_HAM_LUT_SIZE,d0
        lea     v9m_ham_lut_ptr,a1
        jsr     v9m_load_one_lut
        tst.l   d0
        bne.s   v9m_load_ham_fail
        lea     msg_v9m_ham_ok,a1
        move.l  #msg_v9m_ham_ok_end-msg_v9m_ham_ok,d3
        jsr     print

        lea     v9m_edge_name,a0
        move.l  #V10_EDGE_LUT_SIZE,d0
        lea     v9m_edge_lut_ptr,a1
        jsr     v9m_load_one_lut
        tst.l   d0
        bne.s   v9m_load_edge_fail
        lea     msg_v9m_edge_ok,a1
        move.l  #msg_v9m_edge_ok_end-msg_v9m_edge_ok,d3
        jsr     print

        lea     v9m_state_name,a0
        move.l  #V10_STATE_LUT_SIZE,d0
        lea     v9m_state_lut_ptr,a1
        jsr     v9m_load_one_lut
        tst.l   d0
        bne.s   v9m_load_state_fail
        lea     msg_v9m_state_ok,a1
        move.l  #msg_v9m_state_ok_end-msg_v9m_state_ok,d3
        jsr     print

        lea     msg_v9m_lut_all_ok,a1
        move.l  #msg_v9m_lut_all_ok_end-msg_v9m_lut_all_ok,d3
        bsr     print
        moveq   #0,d0
        bra.s   v9m_load_luts_done

v9m_load_ham_fail:
        lea     e_v9m_ham,a1
        move.l  #e_v9m_ham_end-e_v9m_ham,d3
        bsr     print
        bra.s   v9m_load_luts_fail
v9m_load_edge_fail:
        lea     e_v9m_edge,a1
        move.l  #e_v9m_edge_end-e_v9m_edge,d3
        bsr     print
        bra.s   v9m_load_luts_fail
v9m_load_state_fail:
        lea     e_v9m_state,a1
        move.l  #e_v9m_state_end-e_v9m_state,d3
        bsr     print
v9m_load_luts_fail:
        jsr     v9m_free_luts
        moveq   #1,d0
v9m_load_luts_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

v9m_free_luts:
        movem.l d0-d7/a0-a3/a6,-(sp)
        move.l  v9m_ham_lut_ptr,d0
        or.l    v9m_edge_lut_ptr,d0
        or.l    v9m_state_lut_ptr,d0
        beq.w   v9m_free_luts_done

        lea     msg_v9m_lut_free,a1
        move.l  #msg_v9m_lut_free_end-msg_v9m_lut_free,d3
        bsr     print

        move.l  a4,a6
        move.l  v9m_ham_lut_ptr,d0
        beq.s   v9m_free_no_ham
        move.l  d0,a1
        move.l  #V10_HAM_LUT_SIZE,d0
        jsr     FreeMem(a6)
        clr.l   v9m_ham_lut_ptr
v9m_free_no_ham:
        move.l  v9m_edge_lut_ptr,d0
        beq.s   v9m_free_no_edge
        move.l  d0,a1
        move.l  #V10_EDGE_LUT_SIZE,d0
        jsr     FreeMem(a6)
        clr.l   v9m_edge_lut_ptr
v9m_free_no_edge:
        move.l  v9m_state_lut_ptr,d0
        beq.s   v9m_free_no_state
        move.l  d0,a1
        move.l  #V10_STATE_LUT_SIZE,d0
        jsr     FreeMem(a6)
        clr.l   v9m_state_lut_ptr
v9m_free_no_state:
        lea     msg_v9m_lut_free_ok,a1
        move.l  #msg_v9m_lut_free_ok_end-msg_v9m_lut_free_ok,d3
        bsr     print
v9m_free_luts_done:
        movem.l (sp)+,d0-d7/a0-a3/a6
        rts


; --------------------------------------------------------------------
; V10P - Raspberry Pi firmware memory split diagnostic, AFTER the
; already-proven VCHIQ_INIT property transaction.
;
; Reuses the exact property buffer/physical mapping that successfully
; completed VCHIQ_INIT.  Queries are deliberately sent one at a time:
;   0x00010005 GET_ARM_MEMORY -> base,size
;   0x00010006 GET_VC_MEMORY  -> base,size
; For each reply the complete mailbox response word (address+channel)
; must equal the request word.  Failure is non-fatal.
; --------------------------------------------------------------------
v10l_query_firmware_memory_after_init:
        movem.l d0-d7/a0-a3/a6,-(sp)
        clr.l   v10k_arm_base
        clr.l   v10k_arm_size
        clr.l   v10k_vc_base
        clr.l   v10k_vc_size
        clr.l   v10k_query_result

        lea     msg_v10k_mem_start,a1
        move.l  #msg_v10k_mem_start_end-msg_v10k_mem_start,d3
        jsr     print

        ; The normal VCHIQ_INIT path has already proven all three facts below.
        move.l  prop_alloc,d0
        beq.w   v10l_mem_fail_precondition
        move.l  prop_ptr,d0
        beq.w   v10l_mem_fail_precondition
        cmp.l   prop_phys,d0
        bne.w   v10l_mem_fail_precondition

        lea     msg_v10l_reuse,a1
        move.l  #msg_v10l_reuse_end-msg_v10l_reuse,d3
        jsr     print
        move.l  prop_phys,d0
        jsr     print_hex32
        jsr     newline

        ; Query ARM memory first.
        move.l  #$00010005,d0
        jsr     v10l_query_one_memory_tag
        tst.l   d0
        bne.w   v10l_mem_fail_arm
        move.l  d1,v10k_arm_base
        move.l  d2,v10k_arm_size

        ; Query VideoCore memory separately.
        move.l  #$00010006,d0
        jsr     v10l_query_one_memory_tag
        tst.l   d0
        bne.w   v10l_mem_fail_vc
        move.l  d1,v10k_vc_base
        move.l  d2,v10k_vc_size

        lea     msg_v10k_arm,a1
        move.l  #msg_v10k_arm_end-msg_v10k_arm,d3
        jsr     print
        move.l  v10k_arm_base,d0
        jsr     print_hex32
        lea     msg_v10k_sep,a1
        move.l  #msg_v10k_sep_end-msg_v10k_sep,d3
        jsr     print
        move.l  v10k_arm_size,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v10k_vc,a1
        move.l  #msg_v10k_vc_end-msg_v10k_vc,d3
        jsr     print
        move.l  v10k_vc_base,d0
        jsr     print_hex32
        lea     msg_v10k_sep,a1
        move.l  #msg_v10k_sep_end-msg_v10k_sep,d3
        jsr     print
        move.l  v10k_vc_size,d0
        jsr     print_hex32
        jsr     newline

        lea     msg_v10k_vc_mib,a1
        move.l  #msg_v10k_vc_mib_end-msg_v10k_vc_mib,d3
        jsr     print
        move.l  v10k_vc_size,d0
        lsr.l   #8,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        jsr     print_hex32
        lea     msg_v10k_mib_suffix,a1
        move.l  #msg_v10k_mib_suffix_end-msg_v10k_mib_suffix,d3
        jsr     print
        moveq   #0,d6
        bra.w   v10l_mem_done

v10l_mem_fail_precondition:
        lea     msg_v10l_mem_precond_fail,a1
        move.l  #msg_v10l_mem_precond_fail_end-msg_v10l_mem_precond_fail,d3
        jsr     print
        moveq   #1,d6
        bra.s   v10l_mem_done
v10l_mem_fail_arm:
        lea     msg_v10l_arm_fail,a1
        move.l  #msg_v10l_arm_fail_end-msg_v10l_arm_fail,d3
        jsr     print
        moveq   #1,d6
        bra.s   v10l_mem_done
v10l_mem_fail_vc:
        lea     msg_v10l_vc_fail,a1
        move.l  #msg_v10l_vc_fail_end-msg_v10l_vc_fail,d3
        jsr     print
        moveq   #1,d6

v10l_mem_done:
        move.l  d6,v10k_query_result
        movem.l (sp)+,d0-d7/a0-a3/a6
        rts

; D0 = property tag. Returns D0=0 success, D1=base, D2=size.
; Returns nonzero on failure. Uses only the already-proven prop_ptr buffer.
v10l_query_one_memory_tag:
        movem.l d3-d7/a0-a2/a6,-(sp)
        move.l  d0,d3                  ; requested tag
        clr.l   d1
        clr.l   d2

        move.l  prop_ptr,a2
        cmpa.l  #0,a2
        beq.w   v10l_q_fail

        ; 32-byte property message with one 8-byte memory tag.
        move.l  a2,a0
        move.l  #32,d0
        jsr     store_le32
        lea     4(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  d3,d0
        jsr     store_le32
        lea     12(a2),a0
        moveq   #8,d0
        jsr     store_le32
        lea     16(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     20(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     24(a2),a0
        moveq   #0,d0
        jsr     store_le32
        lea     28(a2),a0
        moveq   #0,d0
        jsr     store_le32

        ; Same CachePreDMA/physical identity convention as proven VCHIQ_INIT.
        move.l  #32,prop_len
        move.l  a2,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,d4                  ; returned physical address
        cmp.l   prop_ptr,d0
        bne.w   v10l_q_post_fail

        and.l   #$fffffff0,d0
        or.l    #MBOX_PROPERTY,d0
        move.l  d0,d6                  ; exact request word (phys+channel)

        move.l  #TIMEOUT,d7
v10l_q_tx_wait:
        move.l  MBOX_STATUS,d0
        jsr     bswap32
        and.l   #MBOX_TX_FULL,d0
        beq.s   v10l_q_tx_ready
        subq.l  #1,d7
        bne.s   v10l_q_tx_wait
        bra.w   v10l_q_post_fail
v10l_q_tx_ready:
        move.l  d6,d0
        jsr     bswap32
        move.l  d0,MBOX_WRITE

        move.l  #TIMEOUT,d7
v10l_q_rx_wait:
        move.l  MBOX_STATUS,d0
        jsr     bswap32
        and.l   #MBOX_RX_EMPTY,d0
        beq.s   v10l_q_rx_ready
        subq.l  #1,d7
        bne.s   v10l_q_rx_wait
        bra.w   v10l_q_post_fail
v10l_q_rx_ready:
        move.l  MBOX_READ,d0
        jsr     bswap32
        cmp.l   d6,d0                  ; V10P: exact address+channel match
        beq.s   v10l_q_got_exact
        subq.l  #1,d7
        bne.s   v10l_q_rx_wait
        bra.w   v10l_q_post_fail

v10l_q_got_exact:
        move.l  #32,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)

        move.l  prop_ptr,a2
        lea     4(a2),a0
        jsr     load_le32
        cmp.l   #$80000000,d0
        bne.s   v10l_q_fail_no_post
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   d3,d0
        bne.s   v10l_q_fail_no_post
        lea     16(a2),a0
        jsr     load_le32
        cmp.l   #$80000008,d0
        bne.s   v10l_q_fail_no_post
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,d1
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,d2
        moveq   #0,d0
        bra.s   v10l_q_done

v10l_q_post_fail:
        ; CachePreDMA has begun: always close the phase before returning.
        move.l  #32,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
v10l_q_fail_no_post:
v10l_q_fail:
        moveq   #1,d0
v10l_q_done:
        movem.l (sp)+,d3-d7/a0-a2/a6
        rts

; --------------------------------------------------------------------
; V13 - shell-local Ctrl-C stop support.
;
; AmigaDOS sends SIGBREAKF_CTRL_C to the running CLI process.  Poll it with
; Exec SetSignal(0,mask), which returns and clears only the selected break bit.
; No raw keyboard/ESC hook is installed, so Workbench applications keep normal
; keyboard ownership while the film is visible on RGB.
; --------------------------------------------------------------------
v13_clear_ctrl_c:
        movem.l d1/a6,-(sp)
        moveq   #0,d0
        move.l  #SIGBREAKF_CTRL_C,d1
        move.l  a4,a6
        jsr     SetSignal(a6)
        movem.l (sp)+,d1/a6
        rts

; Return D0=1 only when a fresh Ctrl-C was observed on this poll.
; The persistent flag remains set until the process finishes its controlled EOS.
v13_poll_ctrl_c:
        movem.l d1/a6,-(sp)
        moveq   #0,d0
        move.l  #SIGBREAKF_CTRL_C,d1
        move.l  a4,a6
        jsr     SetSignal(a6)
        and.l   #SIGBREAKF_CTRL_C,d0
        beq.s   v13_poll_ctrl_c_none
        ; V13Fix: a held/repeated Ctrl-C must not retrigger the stop path.
        ; SetSignal has consumed this occurrence; only the first request returns 1.
        tst.l   v13_stop_requested
        bne.s   v13_poll_ctrl_c_none
        move.l  #1,v13_stop_requested
        moveq   #1,d0
        bra.s   v13_poll_ctrl_c_done
v13_poll_ctrl_c_none:
        moveq   #0,d0
v13_poll_ctrl_c_done:
        movem.l (sp)+,d1/a6
        rts

h264rgb_main:
        movem.l d2-d7/a2-a6,-(sp)

        ; Preserve AmigaDOS command line before any library call clobbers D0/A0.
        move.l  d0,h264rgb_cli_len
        move.l  a0,h264rgb_cli_ptr

        move.l  4.w,a4
        move.l  a4,a6
        lea     dosname,a1
        jsr     OldOpenLibrary(a6)
        tst.l   d0
        beq.w   exit_prog
        move.l  d0,a5

        move.l  a5,a6
        jsr     Output(a6)
        move.l  d0,d4
        move.l  d0,h264rgb_output_handle
        beq.w   close_prog

        ; V1 change: filename comes from the AmigaDOS command line.
        bsr     h264rgb_parse_arg
        tst.l   d0
        beq.s   h264rgb_arg_ok

        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        bsr     print_force
        bra.s   h264rgb_early_help_exit

h264rgb_arg_ok:
        ; "h264rgb ?" is a real version/help query, not a filename.
        lea     t23_file_name,a0
        cmpi.b  #$3F,(a0)
        bne.s   h264rgb_normal_start
        tst.b   1(a0)
        bne.s   h264rgb_normal_start
        lea     msg_usage,a1
        move.l  #msg_usage_end-msg_usage,d3
        bsr     print_force

h264rgb_early_help_exit:
        ; Nothing has been allocated yet, so help can exit directly.
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

h264rgb_normal_start:
        clr.l   h264rgb_print_tail

        ; Small public UI; all later ordinary diagnostics are filtered.
        lea     msg_v13_banner,a1
        move.l  #msg_v13_banner_end-msg_v13_banner,d3
        bsr     print_force
        lea     msg_v13_try,a1
        move.l  #msg_v13_try_end-msg_v13_try,d3
        bsr     print_force
        lea     t23_file_name,a1
        bsr     print_cstr_force
        lea     msg_v13_ctrlc_hint,a1
        move.l  #msg_v13_ctrlc_hint_end-msg_v13_ctrlc_hint,d3
        bsr     print_force

        ; V13: discard a stale break from before program start. Any Ctrl-C
        ; received after this point remains pending until the streaming poll sees it.
        clr.l   v13_stop_requested
        bsr     v13_clear_ctrl_c

        ; V10P: bounded-memory live MKV demux.  The V10F metadata probe still
        ; reads only a fixed 2-MiB window to discover Tracks/avcC.  During actual
        ; playback h22_load_frame_data converts only the selected AVC blocks
        ; directly into the 256-KiB MMAL input slot.  No whole-file buffer and
        ; no temporary Annex-B file are created.
        clr.l   v10b_input_is_mkv
        clr.l   v12e_input_is_mp4
        jsr     v12e_is_mp4
        tst.l   d0
        beq.s   h264rgb_check_mkv
        move.l  #1,v12e_input_is_mp4
        jsr     v12e_mp4_probe
        tst.l   d0
        bne.w   h264rgb_mp4_prepare_fail
        lea     msg_v12e_mp4_ready,a1
        move.l  #msg_v12e_mp4_ready_end-msg_v12e_mp4_ready,d3
        jsr     print
        bra.w   h264rgb_have_extradata

h264rgb_check_mkv:
        jsr     v10_is_mkv
        tst.l   d0
        beq.w   h264rgb_raw_prepare
        move.l  #1,v10b_input_is_mkv
        jsr     v10_mkv_probe
        tst.l   v10_h264_found
        beq.w   h264rgb_mkv_prepare_fail
        tst.l   v10_avcc_ok
        beq.w   h264rgb_mkv_prepare_fail
        tst.l   v10_video_track_num
        beq.w   h264rgb_mkv_prepare_fail
        lea     msg_v10b_stream_ready,a1
        move.l  #msg_v10b_stream_ready_end-msg_v10b_stream_ready,d3
        jsr     print
        bra.w   h264rgb_have_extradata

h264rgb_mp4_prepare_fail:
        lea     msg_v12e_mp4_unsupported,a1
        move.l  #msg_v12e_mp4_unsupported_end-msg_v12e_mp4_unsupported,d3
        jsr     print
        jsr     v12e_free_mp4
        move.l  t23_file_handle,d0
        beq.s   h264rgb_mp4_fail_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
h264rgb_mp4_fail_closed:
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

h264rgb_mkv_prepare_fail:
        lea     msg_v10b_prepare_fail,a1
        move.l  #msg_v10b_prepare_fail_end-msg_v10b_prepare_fail,d3
        jsr     print
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

; V10P: early unsupported-stream exit. Nothing decoder-related has been
; allocated or started yet, therefore this is a normal shell return and does
; NOT require the persistent-VCHIQ/MMAL cleanup path or a reboot.
h264rgb_unsupported_exit:
        lea     msg_v10p_unsupported,a1
        move.l  #msg_v10p_unsupported_end-msg_v10p_unsupported,d3
        jsr     print
        ; V12E MP4 probing keeps the moov metadata and DOS file open until
        ; playback.  The old V10P unsupported-SPS exit had no such resources.
        ; Release them here as well so an unsupported MP4 returns cleanly.
        jsr     v12e_free_mp4
        move.l  t23_file_handle,d0
        beq.s   h264rgb_unsupported_file_closed
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
h264rgb_unsupported_file_closed:
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

h264rgb_raw_prepare:
        ; Raw Annex-B keeps the hardware-proven V9M/V10F probe unchanged.
        bsr     h264rgb_load_file_extradata
        tst.l   d0
        bne.w   close_prog

h264rgb_have_extradata:
        ; For MKV, v10_parse_avcc already copied SPS/PPS into the same
        ; h264_file_extradata buffer and set h264_sps_ptr/h264_pps_ptr.
        bsr     v6_parse_sps_geometry
        tst.l   d0
        bne.w   close_prog
        ; V10P compatibility guard.  The exact SPS used by the known failing
        ; stream has now been hardware-tested through CONFIG removal, full-frame
        ; START|END input, 19 real host output buffers and a DPB-15 experiment.
        ; VideoCore still returns MMAL_ENOSPC before producing frame 0.  Reject
        ; this exact SPS BEFORE LUT allocation, VCHIQ_INIT or MMAL creation so
        ; the CLI returns cleanly and no reboot is required.  The bitstream is
        ; never modified.
        jsr     v10p_check_unsupported_sps
        tst.l   d0
        bne.w   h264rgb_unsupported_exit
        jsr     v7_setup_timing
        tst.l   d0
        bne.w   close_prog

        ; V10: load the three external speed LUTs once for this CLI process.
        ; They remain ordinary Fast-RAM tables during playback and are freed
        ; before returning to the shell.
        jsr     v9m_load_luts
        tst.l   d0
        bne.w   v9d_attach_exit

        lea     msg_start,a1
        move.l  #msg_start_end-msg_start,d3
        bsr     print

        ; V12F: generic ISP worker helpers default to local VCHIQ port 0.
        clr.l   v12f_local_port
        clr.l   v12f_local_bits

        ; V10: on a second CLI invocation, attach to the persistent VCHIQ
        ; transport and probe a fresh MMAL service on local port 1.
        jsr     v9d_try_attach
        tst.l   d0
        beq.s   v9d_first_start
        cmpi.l  #1,d0
        bne.w   v9d_attach_exit
        jsr     v9d_second_start_probe
        bra.w   v9d_attach_exit
v9d_first_start:

        ; V9: two compact 192x144x6 Chip-RAM display buffers are reserved.
        ; Decoded frames are converted and displayed immediately; no movie preload.
        lea     msg30_store_alloc,a1
        move.l  #msg30_store_alloc_end-msg30_store_alloc,d3
        bsr     print
        jsr     v9i_print_chip_before_alloc
        jsr     v9i_alloc_chip_guarded
        tst.l   d0
        beq.w   fail30_store_alloc
        jsr     v9i_print_chip_after_alloc

        ; TEST61 HAM6 needs U and V until the last mapped pixel.
        ; Fast scratch and native Chip display now share the exact same compact
        ; 192x144x6 planar layout: six 3456-byte planes = 20736 bytes/frame.
        lea     msg33_fast_alloc,a1
        move.l  #msg33_fast_alloc_end-msg33_fast_alloc,d3
        bsr     print
        move.l  a4,a6
        move.l  #T37_FAST_FRAME_BYTES,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   fail33_fast_alloc
        move.l  d0,t33_fast_ptr
        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        bsr     print

        ; TEST61 keeps a Fast-RAM mirror for each compact Chip display buffer.
        ; Both mirrors and Chip buffers start cleared, therefore equality in the
        ; mirror always means the corresponding Chip longword already matches.
        lea     msg53_shadow_alloc,a1
        move.l  #msg53_shadow_alloc_end-msg53_shadow_alloc,d3
        bsr     print
        move.l  a4,a6
        move.l  #T56_SHADOW_BYTES,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   fail53_shadow_alloc
        move.l  d0,t56_shadow_ptr
        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        bsr     print

        clr.l   t31s_display_started
        clr.l   t31s_vblank_installed
        clr.l   t31s_vblank_counter
        clr.l   t31s_pending_ptr
        clr.l   t31s_switch_vblank
        clr.l   t31s_pending_valid
        clr.l   t31s_next_switch_vblank
        clr.l   t8a_isr_late_promote
        clr.l   v7_sched_accum
        clr.l   t31s_missed_deadlines
        clr.l   t31x_slack1
        clr.l   t31x_slack2
        clr.l   t31x_slack3plus
        clr.l   t31x_at_target
        clr.l   t31x_past_target
        move.l  #-1,t31x_miss1_frame
        clr.l   t31x_miss1_target
        clr.l   t31x_miss1_current
        clr.l   t31x_miss1_delta
        move.l  #-1,t31x_miss2_frame
        clr.l   t31x_miss2_target
        clr.l   t31x_miss2_current
        clr.l   t31x_miss2_delta
        clr.l   t31x_max_past_delta
        clr.l   t31u_last_stream_end_vblank
        clr.l   t31u_gap_total
        clr.l   t31u_gap_max
        clr.l   t31u_gap_nonzero
        clr.l   t31u_buffer_total
        clr.l   t31u_buffer_max
        clr.l   t31u_buffer_nonzero
        clr.l   t31u_convert_total
        clr.l   t31u_convert_max
        clr.l   t31u_convert_nonzero
        clr.l   t31w_copy_total
        clr.l   t31w_copy_max
        clr.l   t31w_copy_nonzero
        clr.l   t56_dirty_long_total
        clr.l   t56_dirty_long_max
        clr.l   t57_early_release_total
        clr.l   t61_deferred_total
        clr.l   t61_slot0_frames
        clr.l   t61_slot1_frames
        clr.l   t63_preroll_ptr
        clr.l   t63_preroll_frames
        clr.l   t65_same_vblank_total
        clr.l   t65_same_vblank_late
        clr.l   t65_catchup_debt
        clr.l   t65_debt_added_total
        clr.l   t65_catchup_total
        clr.l   t65_debt_max
        clr.l   t66_current_slack
        clr.l   t66_catchup_deferred
        clr.l   t31u_post_total
        clr.l   t31u_post_max
        clr.l   t31u_post_nonzero
        clr.l   t31u_stage_start_vblank
        clr.l   t31u_run_start_vblank
        clr.l   t30_active_ptr
        clr.l   t30_display_ptr
        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 1. Allocate and initialize shared VCHIQ memory
; --------------------------------------------------------------------
        lea     msg_alloc,a1
        move.l  #msg_alloc_end-msg_alloc,d3
        bsr     print

        move.l  a4,a6
        move.l  #ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   fail_alloc
        move.l  d0,slot_alloc

        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,slot_ptr
        move.l  d0,a3

        move.l  a3,d6
        cmp.l   #$3f000000,d6
        bcc.w   fail_range
        or.l    #$c0000000,d6
        move.l  d6,slot_bus

        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        bsr     print

        lea     msg_layout,a1
        move.l  #msg_layout_end-msg_layout,d3
        bsr     print

        ; SlotZero header
        move.l  a3,a0
        move.l  #VCHIQ_MAGIC,d0
        bsr     store_le32

        ; version/version_min are u16 fields in little endian.
        ; For v8/min3 this produces bytes 08 00 03 00.
        move.b  #8,4(a3)
        move.b  #0,5(a3)
        move.b  #3,6(a3)
        move.b  #0,7(a3)

        lea     8(a3),a0
        move.l  #SLOTZERO_SIZE,d0
        bsr     store_le32

        lea     12(a3),a0
        move.l  #SLOT_SIZE,d0
        bsr     store_le32

        lea     16(a3),a0
        move.l  #MAX_SLOTS,d0
        bsr     store_le32

        lea     20(a3),a0
        move.l  #MAX_SIDE,d0
        bsr     store_le32

        ; Pi3 fragment area starts directly after the 65 slots.
        move.l  d6,d0
        add.l   #SLOT_MEM_SIZE,d0
        lea     24(a3),a0
        bsr     store_le32

        lea     28(a3),a0
        move.l  #64,d0
        bsr     store_le32

        ; VideoCore/master side: sync 1, data 2..32
        lea     MASTER_FIRST(a3),a0
        move.l  #2,d0
        bsr     store_le32
        lea     MASTER_LAST(a3),a0
        move.l  #32,d0
        bsr     store_le32
        lea     MASTER_SYNC(a3),a0
        move.l  #1,d0
        bsr     store_le32

        ; Host/slave side: sync 33, data 34..64
        lea     SLAVE_FIRST(a3),a0
        move.l  #34,d0
        bsr     store_le32
        lea     SLAVE_LAST(a3),a0
        move.l  #64,d0
        bsr     store_le32
        lea     SLAVE_SYNC(a3),a0
        move.l  #33,d0
        bsr     store_le32

        ; Host slot queue: 34..64
        lea     SLAVE_QUEUE(a3),a2
        move.l  #34,d5
        move.l  #30,d7
queue_init_loop:
        move.l  d5,d0
        bsr     bswap32
        move.l  d0,(a2)+
        addq.l  #1,d5
        dbra    d7,queue_init_loop

        lea     SLAVE_RECYCLEQ(a3),a0
        move.l  #31,d0
        bsr     store_le32

        ; Linux initializes local sync_release.fired = 1.
        lea     SLAVE_SYNCREL_F(a3),a0
        move.l  #1,d0
        bsr     store_le32

        lea     SLAVE_DEBUG0(a3),a0
        move.l  #11,d0
        bsr     store_le32

        ; Local sync slot 33 starts with PADDING. AllocMem CLEAR already
        ; gives msgid=0,size=0, so no extra writes are needed.

        ; Set local initialized last.
        lea     SLAVE_INIT(a3),a0
        move.l  #1,d0
        bsr     store_le32

        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 2. Verify DMA mapping and hand initial shared region to VideoCore
; --------------------------------------------------------------------
        lea     msg_dma,a1
        move.l  #msg_dma_end-msg_dma,d3
        bsr     print

        move.l  #DMA_MEM_SIZE,dma_len
        move.l  a3,a0
        lea     dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,slot_phys

        move.l  dma_len,d1
        cmp.l   #DMA_MEM_SIZE,d1
        bcs.w   fail_dma_len

        cmp.l   slot_ptr,d0
        bne.w   fail_identity

        lea     msg_phys,a1
        move.l  #msg_phys_end-msg_phys,d3
        bsr     print
        move.l  slot_phys,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_bus,a1
        move.l  #msg_bus_end-msg_bus,d3
        bsr     print
        move.l  slot_bus,d0
        bsr     print_hex32
        bsr     newline

; --------------------------------------------------------------------
; 3. Build firmware property request
; --------------------------------------------------------------------
        lea     msg_prop,a1
        move.l  #msg_prop_end-msg_prop,d3
        bsr     print

        move.l  a4,a6
        move.l  #$200,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   fail_prop_alloc
        move.l  d0,prop_alloc

        add.l   #127,d0
        and.l   #$ffffff80,d0
        move.l  d0,prop_ptr
        move.l  d0,a2

        move.l  a2,a0
        move.l  #28,d0
        bsr     store_le32

        lea     4(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     8(a2),a0
        move.l  #$00048010,d0
        bsr     store_le32

        lea     12(a2),a0
        moveq   #4,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  slot_bus,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        move.l  #28,prop_len
        move.l  a2,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,prop_phys

        cmp.l   prop_ptr,d0
        bne.w   fail_prop_identity

        lea     msg_ok,a1
        move.l  #msg_ok_end-msg_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 4. VCHIQ_INIT via firmware property mailbox
; --------------------------------------------------------------------
        lea     msg_init,a1
        move.l  #msg_init_end-msg_init,d3
        bsr     print

        move.l  prop_phys,d0
        and.l   #$fffffff0,d0
        or.l    #MBOX_PROPERTY,d0
        move.l  d0,d5

        move.l  #TIMEOUT,d7
mbox_tx_wait:
        move.l  MBOX_STATUS,d0
        bsr     bswap32
        and.l   #MBOX_TX_FULL,d0
        beq.w   mbox_tx_ready
        subq.l  #1,d7
        bne.w   mbox_tx_wait
        bra.w   fail_tx_timeout

mbox_tx_ready:
        move.l  d5,d0
        bsr     bswap32
        move.l  d0,MBOX_WRITE

        move.l  #TIMEOUT,d7
mbox_rx_wait:
        move.l  MBOX_STATUS,d0
        bsr     bswap32
        and.l   #MBOX_RX_EMPTY,d0
        beq.w   mbox_rx_ready
        subq.l  #1,d7
        bne.w   mbox_rx_wait
        bra.w   fail_rx_timeout

mbox_rx_ready:
        move.l  MBOX_READ,d0
        bsr     bswap32
        move.l  d0,d5

        move.l  d5,d0
        and.l   #$f,d0
        cmp.l   #MBOX_PROPERTY,d0
        beq.w   mbox_got_prop
        subq.l  #1,d7
        bne.w   mbox_rx_wait
        bra.w   fail_rx_timeout

mbox_got_prop:
        move.l  #28,prop_len
        move.l  prop_ptr,a0
        lea     prop_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)

        move.l  prop_ptr,a0
        move.l  4(a0),d0
        bsr     bswap32
        cmp.l   #$80000000,d0
        bne.w   fail_fw_status

        move.l  20(a0),d0
        bsr     bswap32
        tst.l   d0
        bne.w   fail_channelbase

        lea     msg_init_ok,a1
        move.l  #msg_init_ok_end-msg_init_ok,d3
        bsr     print

        ; V10P: only now, after the exact same property-mailbox path has
        ; demonstrably succeeded, query ARM and VC memory one tag at a time.
        jsr     v10l_query_firmware_memory_after_init

; --------------------------------------------------------------------
; 5. Finish DMA phase, inspect VC/master shared state
; --------------------------------------------------------------------
        ; The shared block has been in a CachePreDMA phase since step 2.
        ; End it so CPU can safely observe VideoCore writes.
        bsr     dma_post_all

        ; Wait briefly for master.initialized if needed.
        move.l  #POLL_COUNT,d7
wait_master_init:
        move.l  slot_ptr,a0
        lea     MASTER_INIT(a0),a0
        bsr     load_le32
        tst.l   d0
        bne.w   master_is_ready

        bsr     dma_pre_all
        bsr     short_delay
        bsr     dma_post_all
        subq.l  #1,d7
        bne.w   wait_master_init
        bra.w   fail_master_init

master_is_ready:
        ; First invocation: publish the global VCHIQ slot block through a tiny
        ; persistent Exec resource. It is deliberately never removed/freed;
        ; firmware owns this transport until reboot.
        jsr     v9d_register_resource
        tst.l   d0
        bne.w   fail_v9d_resource

        lea     msg_master,a1
        move.l  #msg_master_end-msg_master,d3
        bsr     print

        lea     msg_master_init,a1
        move.l  #msg_master_init_end-msg_master_init,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_INIT(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        lea     msg_master_tx,a1
        move.l  #msg_master_tx_end-msg_master_tx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,remote_tx_before
        bsr     print_hex32
        bsr     newline

        lea     msg_master_arm,a1
        move.l  #msg_master_arm_end-msg_master_arm,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,vc_armed
        bsr     print_hex32
        bsr     newline

        lea     msg_master_q0,a1
        move.l  #msg_master_q0_end-msg_master_q0,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0
        bsr     print_hex32
        bsr     newline

; --------------------------------------------------------------------
; 5a. Stabilization window after firmware VCHIQ_INIT.
;
; The sporadic failed boots show that master.initialized=1 and armed=1
; do not always mean that the VideoCore VCHIQ side is fully ready to
; process our CONNECT immediately. Give firmware 25 DOS ticks = 0.5 s.
;
; IMPORTANT: return shared memory to DMA ownership during Delay(), then
; reacquire it and refresh tx_pos / armed / fired before CONNECT.
; --------------------------------------------------------------------
        lea     msg_stabil_start,a1
        move.l  #msg_stabil_start_end-msg_stabil_start,d3
        bsr     print

        bsr     dma_pre_all

        move.l  a5,a6
        move.l  #25,d1
        jsr     Delay(a6)

        bsr     dma_post_all

        lea     msg_stabil_tx,a1
        move.l  #msg_stabil_tx_end-msg_stabil_tx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,remote_tx_before
        bsr     print_hex32
        bsr     newline

        lea     msg_stabil_arm,a1
        move.l  #msg_stabil_arm_end-msg_stabil_arm,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,vc_armed
        bsr     print_hex32
        bsr     newline

        lea     msg_stabil_fired,a1
        move.l  #msg_stabil_fired_end-msg_stabil_fired,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        bsr     load_le32
        move.l  d0,stabil_fired
        bsr     print_hex32
        bsr     newline

; --------------------------------------------------------------------
; 6. Check whether VideoCore CONNECT is ALREADY present.
; --------------------------------------------------------------------
        clr.l   remote_seen

        lea     msg_precheck,a1
        move.l  #msg_precheck_end-msg_precheck,d3
        bsr     print

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        lea     msg_master_tx,a1
        move.l  #msg_master_tx_end-msg_master_tx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        cmp.l   #8,d5
        bcs.w   pre_no_remote_yet

        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0

        lea     msg_rxslot,a1
        move.l  #msg_rxslot_end-msg_rxslot,d3
        bsr     print
        move.l  remote_slot0,d0
        bsr     print_hex32
        bsr     newline

        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_rx_slot
        cmp.l   #32,d0
        bhi.w   fail_rx_slot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0

        move.l  a0,a2
        bsr     load_le32
        move.l  d0,rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,rx_size

        lea     msg_rxid,a1
        move.l  #msg_rxid_end-msg_rxid,d3
        bsr     print
        move.l  rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_rxsize,a1
        move.l  #msg_rxsize_end-msg_rxsize,d3
        bsr     print
        move.l  rx_size,d0
        bsr     print_hex32
        bsr     newline

        move.l  rx_msgid,d0
        cmp.l   #VCHIQ_MSG_CONNECT,d0
        bne.w   fail_wrong_msg

        move.l  rx_size,d0
        tst.l   d0
        bne.w   fail_wrong_size

        move.l  #1,remote_seen

        lea     msg_remote_ready,a1
        move.l  #msg_remote_ready_end-msg_remote_ready,d3
        bsr     print
        bra.w   queue_our_connect

pre_no_remote_yet:
        lea     msg_remote_later,a1
        move.l  #msg_remote_later_end-msg_remote_later,d3
        bsr     print

; --------------------------------------------------------------------
; 7. Queue OUR CONNECT in host slot 34.
; --------------------------------------------------------------------
queue_our_connect:
        ; One initial notification plus at most two re-notifications.
        ; IMPORTANT: the CONNECT message itself is written only once.
        move.l  #2,connect_retries

        lea     msg_connect,a1
        move.l  #msg_connect_end-msg_connect,d3
        bsr     print

        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0

        move.l  #VCHIQ_MSG_CONNECT,d0
        bsr     store_le32
        lea     4(a0),a0
        moveq   #0,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        moveq   #8,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        bsr     dma_pre_all

        move.l  vc_armed,d0
        tst.l   d0
        beq.w   connect_no_bell_a

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_bell,a1
        move.l  #msg_bell_end-msg_bell,d3
        bsr     print
        bra.w   after_notify_a

connect_no_bell_a:
        lea     msg_nobell,a1
        move.l  #msg_nobell_end-msg_nobell,d3
        bsr     print

after_notify_a:
        bsr     short_delay
        bsr     dma_post_all

        lea     msg_localtx,a1
        move.l  #msg_localtx_end-msg_localtx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        lea     msg_fired_after,a1
        move.l  #msg_fired_after_end-msg_fired_after,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        tst.l   remote_seen
        bne.w   connect_success_a

; --------------------------------------------------------------------
; 8. If VC CONNECT was not present before our send, wait for it.
; --------------------------------------------------------------------
        lea     msg_wait,a1
        move.l  #msg_wait_end-msg_wait,d3
        bsr     print

        bsr     dma_pre_all
        move.l  #POLL_COUNT,d7

connect_poll_loop_a:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        cmp.l   #8,d0
        bcc.w   connect_response_seen_a

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   connect_poll_loop_a
        bra.w   fail_connect_timeout

connect_response_seen_a:
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0

        lea     msg_rxslot,a1
        move.l  #msg_rxslot_end-msg_rxslot,d3
        bsr     print
        move.l  remote_slot0,d0
        bsr     print_hex32
        bsr     newline

        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_rx_slot
        cmp.l   #32,d0
        bhi.w   fail_rx_slot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0

        move.l  a0,a2
        bsr     load_le32
        move.l  d0,rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,rx_size

        lea     msg_rxid,a1
        move.l  #msg_rxid_end-msg_rxid,d3
        bsr     print
        move.l  rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_rxsize,a1
        move.l  #msg_rxsize_end-msg_rxsize,d3
        bsr     print
        move.l  rx_size,d0
        bsr     print_hex32
        bsr     newline

        move.l  rx_msgid,d0
        cmp.l   #VCHIQ_MSG_CONNECT,d0
        bne.w   fail_wrong_msg

        move.l  rx_size,d0
        tst.l   d0
        bne.w   fail_wrong_size

connect_success_a:
        lea     msg_connect_ok,a1
        move.l  #msg_connect_ok_end-msg_connect_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 9. Open the real MMAL control service.
;
; Linux VCHIQ open payload (12 bytes):
;   u32 fourcc, u32 client_id, u16 version, u16 version_min
; Official MMAL values: fourcc 'mmal', version 16, minimum 10.
;
; CONNECT consumed 8 bytes in host slot 34. OPEN stride is 24 bytes,
; so OPEN starts at slot 34 offset 8 and host tx_pos becomes 32.
; --------------------------------------------------------------------
        lea     msg_open,a1
        move.l  #msg_open_end-msg_open,d3
        bsr     print

        ; Slot 34 + offset 8.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #8,a0

        ; Header: OPEN from local port 0, payload size 12.
        move.l  #VCHIQ_MSG_OPEN,d0
        bsr     store_le32
        lea     4(a0),a0
        move.l  #12,d0
        bsr     store_le32

        ; Payload fourcc.
        lea     4(a0),a0              ; now slot+16 = payload start
        move.l  #MMAL_FOURCC,d0
        bsr     store_le32

        ; client_id = 0.
        lea     4(a0),a0
        moveq   #0,d0
        bsr     store_le32

        ; u16 version=16, u16 version_min=10, little endian.
        lea     4(a0),a0
        move.b  #MMAL_VER,(a0)
        clr.b   1(a0)
        move.b  #MMAL_VER_MIN,2(a0)
        clr.b   3(a0)

        ; Publish total host stream position: 8 + 24 = 32.
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  #32,d0
        bsr     store_le32

        ; Signal VideoCore master trigger.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        ; Read current armed state before giving DMA ownership back.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,open_armed

        lea     msg_open_arm,a1
        move.l  #msg_open_arm_end-msg_open_arm,d3
        bsr     print
        move.l  open_armed,d0
        bsr     print_hex32
        bsr     newline

        bsr     dma_pre_all

        move.l  open_armed,d0
        tst.l   d0
        beq.w   open_no_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_open_bell,a1
        move.l  #msg_open_bell_end-msg_open_bell,d3
        bsr     print
        bra.w   open_wait_start

open_no_bell:
        lea     msg_open_nobell,a1
        move.l  #msg_open_nobell_end-msg_open_nobell,d3
        bsr     print

; --------------------------------------------------------------------
; 10. Wait for next VC message after CONNECT.
; The CONNECT occupies remote stream bytes 0..7. An OPENACK normally
; appears at slot 2 offset 8. RusPiRo shows OPENACK size=2 and the
; resulting remote tx_pos=24. A rejected OPEN may instead return CLOSE.
; --------------------------------------------------------------------
open_wait_start:
        lea     msg_open_wait,a1
        move.l  #msg_open_wait_end-msg_open_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

open_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   #8,d5
        bhi.w   open_response_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   open_poll_loop
        bra.w   fail_open_timeout

open_response_seen:
        lea     msg_open_tx,a1
        move.l  #msg_open_tx_end-msg_open_tx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        ; Use first VC data slot, expected 2, and inspect offset 8.
        move.l  slot_ptr,a0
        lea     MASTER_QUEUE(a0),a0
        bsr     load_le32
        move.l  d0,remote_slot0

        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_open_rxslot
        cmp.l   #32,d0
        bhi.w   fail_open_rxslot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #8,a0

        move.l  a0,a2
        bsr     load_le32
        move.l  d0,open_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,open_size

        lea     msg_open_id,a1
        move.l  #msg_open_id_end-msg_open_id,d3
        bsr     print
        move.l  open_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_open_size,a1
        move.l  #msg_open_size_end-msg_open_size,d3
        bsr     print
        move.l  open_size,d0
        bsr     print_hex32
        bsr     newline

        ; Check message type first.
        move.l  open_msgid,d0
        and.l   #$FF000000,d0
        cmp.l   #VCHIQ_MSG_CLOSE,d0
        beq.w   fail_open_rejected
        cmp.l   #VCHIQ_MSG_OPENACK,d0
        bne.w   fail_open_wrongmsg

        ; OPENACK destination must be our local port 0.
        move.l  open_msgid,d0
        and.l   #$00000FFF,d0
        bne.w   fail_open_dstport

        ; Extract VideoCore remote source port.
        move.l  open_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000FFF,d0
        move.l  d0,mmal_remote_port

        lea     msg_open_port,a1
        move.l  #msg_open_port_end-msg_open_port,d3
        bsr     print
        move.l  mmal_remote_port,d0
        bsr     print_hex32
        bsr     newline

        ; OPENACK contains at least u16 peer version.
        move.l  open_size,d0
        cmp.l   #2,d0
        bcs.w   fail_open_short

        move.l  a2,a0
        adda.l  #8,a0
        bsr     load_le16
        move.l  d0,mmal_peer_ver

        lea     msg_open_ver,a1
        move.l  #msg_open_ver_end-msg_open_ver,d3
        bsr     print
        move.l  mmal_peer_ver,d0
        bsr     print_hex32
        bsr     newline

        ; We advertised compatibility down to worker version 10.
        move.l  mmal_peer_ver,d0
        cmp.l   #MMAL_VER_MIN,d0
        bcs.w   fail_open_version

        ; Save the current remote stream position. In the successful
        ; TEST11 run this was 0x18: CONNECT (8) + OPENACK (16).
        move.l  d5,mmal_rx_before

        lea     msg_open_success,a1
        move.l  #msg_open_success_end-msg_open_success,d3
        bsr     print

; --------------------------------------------------------------------
; 11. Send MMAL_WORKER_GET_VERSION as VCHIQ DATA.
;
; VCHIQ DATA msgid:
;   type DATA=5
;   source/local port = 0
;   destination/VC port = mmal_remote_port (TEST11 returned 0x55)
;
; MMAL payload is mmal_worker_version, 40 bytes:
;   0  magic          u32 = MMAL_MAGIC
;   4  msgid/type     u32 = GET_VERSION (3)
;   8  control_service u32 = 0
;  12  context/waiter u32 = test cookie
;  16  status         u32 = 0
;  20  dummy/padding  u32 = 0
;  24  flags          u32 = 0
;  28  major          u32 = 0 (reply field)
;  32  minor          u32 = 0 (reply field)
;  36  minimum        u32 = 0 (reply field)
;
; Local stream is currently at 32. DATA header 8 + payload 40 = 48,
; therefore new local tx_pos = 80 (0x50).
; --------------------------------------------------------------------
        lea     msg_getver,a1
        move.l  #msg_getver_end-msg_getver,d3
        bsr     print

        ; Host slot 34, stream offset 32.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #32,a0
        move.l  a0,a2

        ; VCHIQ DATA msgid = 0x05000000 | remote_port.
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        move.l  d0,data_tx_msgid
        bsr     store_le32

        lea     4(a2),a0
        move.l  #40,d0
        bsr     store_le32

        ; MMAL worker payload starts at VCHIQ header + 8.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_GET_VERSION,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; control_service

        lea     20(a2),a0
        move.l  #MMAL_TEST_CONTEXT,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; status

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; dummy/padding

        lea     32(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; flags

        lea     36(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; major

        lea     40(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; minor

        lea     44(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; minimum

        lea     msg_data_txid,a1
        move.l  #msg_data_txid_end-msg_data_txid,d3
        bsr     print
        move.l  data_tx_msgid,d0
        bsr     print_hex32
        bsr     newline

        ; Publish local tx_pos 0x50.
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  #80,d0
        bsr     store_le32

        ; Signal VC.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,data_armed

        lea     msg_data_arm,a1
        move.l  #msg_data_arm_end-msg_data_arm,d3
        bsr     print
        move.l  data_armed,d0
        bsr     print_hex32
        bsr     newline

        ; Flush our DATA message to shared memory.
        bsr     dma_pre_all

        move.l  data_armed,d0
        tst.l   d0
        beq.w   data_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_data_bell,a1
        move.l  #msg_data_bell_end-msg_data_bell,d3
        bsr     print
        bra.w   data_wait_start

data_no_bell:
        lea     msg_data_nobell,a1
        move.l  #msg_data_nobell_end-msg_data_nobell,d3
        bsr     print

; --------------------------------------------------------------------
; 12. Wait for MMAL GET_VERSION reply.
; --------------------------------------------------------------------
data_wait_start:
        lea     msg_data_wait,a1
        move.l  #msg_data_wait_end-msg_data_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

data_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5
        cmp.l   mmal_rx_before,d5
        bhi.w   data_response_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   data_poll_loop
        bra.w   fail_data_timeout

data_response_seen:
        ; This is the start position for the NEXT VideoCore reply.
        move.l  d5,comp_rx_before

        lea     msg_data_rxtx,a1
        move.l  #msg_data_rxtx_end-msg_data_rxtx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        ; Still in first VC data slot for this small test.
        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_data_rxslot
        cmp.l   #32,d0
        bhi.w   fail_data_rxslot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  mmal_rx_before,d0
        adda.l  d0,a0
        move.l  a0,a2

        ; VCHIQ DATA header.
        bsr     load_le32
        move.l  d0,data_rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,data_rx_size

        lea     msg_data_rxid,a1
        move.l  #msg_data_rxid_end-msg_data_rxid,d3
        bsr     print
        move.l  data_rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_data_rxsize,a1
        move.l  #msg_data_rxsize_end-msg_data_rxsize,d3
        bsr     print
        move.l  data_rx_size,d0
        bsr     print_hex32
        bsr     newline

        ; Must be DATA.
        move.l  data_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_data_wrongmsg

        ; Destination must be local port 0.
        move.l  data_rx_msgid,d0
        and.l   #$00000fff,d0
        bne.w   fail_data_dstport

        ; Source must be the VC MMAL service port from OPENACK.
        move.l  data_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_data_srcport

        move.l  data_rx_size,d0
        cmp.l   #40,d0
        bcs.w   fail_data_short

        ; Parse MMAL worker reply.
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,worker_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,worker_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,worker_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,worker_status

        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,worker_flags

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,worker_major

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,worker_minor

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,worker_minimum

        lea     msg_worker_magic,a1
        move.l  #msg_worker_magic_end-msg_worker_magic,d3
        bsr     print
        move.l  worker_magic,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_type,a1
        move.l  #msg_worker_type_end-msg_worker_type,d3
        bsr     print
        move.l  worker_type,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_ctx,a1
        move.l  #msg_worker_ctx_end-msg_worker_ctx,d3
        bsr     print
        move.l  worker_context,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_status,a1
        move.l  #msg_worker_status_end-msg_worker_status,d3
        bsr     print
        move.l  worker_status,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_flags,a1
        move.l  #msg_worker_flags_end-msg_worker_flags,d3
        bsr     print
        move.l  worker_flags,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_major,a1
        move.l  #msg_worker_major_end-msg_worker_major,d3
        bsr     print
        move.l  worker_major,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_minor,a1
        move.l  #msg_worker_minor_end-msg_worker_minor,d3
        bsr     print
        move.l  worker_minor,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_worker_min,a1
        move.l  #msg_worker_min_end-msg_worker_min,d3
        bsr     print
        move.l  worker_minimum,d0
        bsr     print_hex32
        bsr     newline

        ; Validate reply.
        move.l  worker_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_worker_magic

        move.l  worker_type,d0
        cmp.l   #MMAL_GET_VERSION,d0
        bne.w   fail_worker_type

        move.l  worker_context,d0
        cmp.l   #MMAL_TEST_CONTEXT,d0
        bne.w   fail_worker_context

        move.l  worker_status,d0
        tst.l   d0
        bne.w   fail_worker_status

        move.l  worker_major,d0
        cmp.l   #MMAL_VER_MIN,d0
        bcs.w   fail_worker_version

        lea     msg_getver_success,a1
        move.l  #msg_getver_success_end-msg_getver_success,d3
        bsr     print

; --------------------------------------------------------------------
; 13. COMPONENT_CREATE "ril.video_decode" (wire name)
;
; Official MMAL request payload:
;   u32 client_component
;   char name[128]
;   u32 pid
; = 136 bytes.
;
; MMAL header = 24 bytes, therefore MMAL DATA payload = 160 bytes.
; VCHIQ header = 8 bytes -> stream advance 168 bytes.
;
; Host stream before this request = 0x50 (80).
; New host tx_pos = 80 + 168 = 248 = 0xF8.
; --------------------------------------------------------------------
        lea     msg_comp_create,a1
        move.l  #msg_comp_create_end-msg_comp_create,d3
        bsr     print

        ; Host slot 34 + stream offset 0x50.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        adda.l  #80,a0
        move.l  a0,a2

        ; VCHIQ DATA header -> destination MMAL VC port.
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        move.l  d0,comp_tx_msgid
        bsr     store_le32

        lea     4(a2),a0
        move.l  #160,d0
        bsr     store_le32

        ; MMAL worker header (24 bytes).
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; control_service

        lea     20(a2),a0
        move.l  #MMAL_COMP_CONTEXT,d0
        bsr     store_le32              ; synchronous context cookie

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; header status

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32              ; padding

        ; Official host code sends its local MMAL_COMPONENT_T pointer here.
        ; For this bare-metal-style client we use a stable opaque cookie which
        ; VideoCore must only pass back to us in later events/callbacks.
        lea     32(a2),a0
        move.l  #MMAL_CLIENT_COMPONENT,d0
        bsr     store_le32

        ; Explicitly clear the 128-byte component name field.
        lea     36(a2),a0
        move.l  #31,d7
comp_name_clear_loop:
        clr.l   (a0)+
        dbra    d7,comp_name_clear_loop

        ; Copy NUL-terminated ASCII component name.
        lea     36(a2),a0
        lea     comp_name,a1
        move.l  #comp_name_end-comp_name-1,d7
comp_name_copy_loop:
        move.b  (a1)+,(a0)+
        dbra    d7,comp_name_copy_loop

        ; pid = 0
        lea     164(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     msg_comp_txid,a1
        move.l  #msg_comp_txid_end-msg_comp_txid,d3
        bsr     print
        move.l  comp_tx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_localpos,a1
        move.l  #msg_comp_localpos_end-msg_comp_localpos,d3
        bsr     print
        move.l  #$000000F8,d0
        bsr     print_hex32
        bsr     newline

        ; Publish local tx_pos = 0xF8.
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  #248,d0
        bsr     store_le32

        ; Signal VideoCore event.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,comp_armed

        lea     msg_comp_arm,a1
        move.l  #msg_comp_arm_end-msg_comp_arm,d3
        bsr     print
        move.l  comp_armed,d0
        bsr     print_hex32
        bsr     newline

        ; Flush complete shared-memory region before ringing VC.
        bsr     dma_pre_all

        move.l  comp_armed,d0
        tst.l   d0
        beq.w   comp_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_comp_bell,a1
        move.l  #msg_comp_bell_end-msg_comp_bell,d3
        bsr     print
        bra.w   comp_wait_start

comp_no_bell:
        lea     msg_comp_nobell,a1
        move.l  #msg_comp_nobell_end-msg_comp_nobell,d3
        bsr     print

; --------------------------------------------------------------------
; 14. Wait for COMPONENT_CREATE reply.
; --------------------------------------------------------------------
comp_wait_start:
        lea     msg_comp_wait,a1
        move.l  #msg_comp_wait_end-msg_comp_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

comp_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   comp_rx_before,d5
        bhi.w   comp_response_seen

        ; Return shared region to VC before next polling interval.
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   comp_poll_loop
        bra.w   fail_comp_timeout

comp_response_seen:
        ; Start position of the next VideoCore message.
        move.l  d5,port_rx_pos

        lea     msg_comp_rxtx,a1
        move.l  #msg_comp_rxtx_end-msg_comp_rxtx,d3
        bsr     print
        move.l  d5,d0
        bsr     print_hex32
        bsr     newline

        ; Response remains in the first VideoCore data slot.
        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   fail_comp_rxslot
        cmp.l   #32,d0
        bhi.w   fail_comp_rxslot

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  comp_rx_before,d0
        adda.l  d0,a0
        move.l  a0,a2

        ; VCHIQ header.
        bsr     load_le32
        move.l  d0,comp_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,comp_rx_size

        lea     msg_comp_rxid,a1
        move.l  #msg_comp_rxid_end-msg_comp_rxid,d3
        bsr     print
        move.l  comp_rx_msgid,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_rxsize,a1
        move.l  #msg_comp_rxsize_end-msg_comp_rxsize,d3
        bsr     print
        move.l  comp_rx_size,d0
        bsr     print_hex32
        bsr     newline

        ; Must be VCHIQ DATA.
        move.l  comp_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_comp_wrongmsg

        ; Destination local port must be 0.
        move.l  comp_rx_msgid,d0
        and.l   #$00000fff,d0
        bne.w   fail_comp_dstport

        ; Source must be our opened VideoCore MMAL port.
        move.l  comp_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_comp_srcport

        ; Reply MMAL body: 24-byte header + 20-byte create_reply.
        move.l  comp_rx_size,d0
        cmp.l   #44,d0
        bcs.w   fail_comp_short

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,comp_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,comp_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,comp_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,comp_hdr_status

        ; component_create_reply payload.
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,comp_reply_status

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,component_handle

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,component_inputs

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,component_outputs

        lea     48(a2),a0
        bsr     load_le32
        move.l  d0,component_clocks

        ; Diagnostic output.
        lea     msg_comp_magic,a1
        move.l  #msg_comp_magic_end-msg_comp_magic,d3
        bsr     print
        move.l  comp_magic,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_type,a1
        move.l  #msg_comp_type_end-msg_comp_type,d3
        bsr     print
        move.l  comp_type,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_ctx,a1
        move.l  #msg_comp_ctx_end-msg_comp_ctx,d3
        bsr     print
        move.l  comp_context,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_hstatus,a1
        move.l  #msg_comp_hstatus_end-msg_comp_hstatus,d3
        bsr     print
        move.l  comp_hdr_status,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_rstatus,a1
        move.l  #msg_comp_rstatus_end-msg_comp_rstatus,d3
        bsr     print
        move.l  comp_reply_status,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_handle,a1
        move.l  #msg_comp_handle_end-msg_comp_handle,d3
        bsr     print
        move.l  component_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_inputs,a1
        move.l  #msg_comp_inputs_end-msg_comp_inputs,d3
        bsr     print
        move.l  component_inputs,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_outputs,a1
        move.l  #msg_comp_outputs_end-msg_comp_outputs,d3
        bsr     print
        move.l  component_outputs,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_comp_clocks,a1
        move.l  #msg_comp_clocks_end-msg_comp_clocks,d3
        bsr     print
        move.l  component_clocks,d0
        bsr     print_hex32
        bsr     newline

        ; Validate synchronous MMAL reply.
        move.l  comp_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_comp_magic

        move.l  comp_type,d0
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        bne.w   fail_comp_type

        move.l  comp_context,d0
        cmp.l   #MMAL_COMP_CONTEXT,d0
        bne.w   fail_comp_context

        move.l  comp_hdr_status,d0
        tst.l   d0
        bne.w   fail_comp_hdr_status

        move.l  comp_reply_status,d0
        tst.l   d0
        bne.w   fail_comp_reply_status

        move.l  component_handle,d0
        tst.l   d0
        beq.w   fail_comp_handle

        lea     msg_comp_success,a1
        move.l  #msg_comp_success_end-msg_comp_success,d3
        bsr     print

        ; Host stream is at 0xF8 after COMPONENT_CREATE.
        move.l  #248,port_tx_pos

; --------------------------------------------------------------------
; 15. Query all four port classes which the official MMAL host code
;     queries after COMPONENT_CREATE.
; --------------------------------------------------------------------
        lea     msg_ports_start,a1
        move.l  #msg_ports_start_end-msg_ports_start,d3
        bsr     print

        lea     msg_port_control,a1
        move.l  #msg_port_control_end-msg_port_control,d3
        bsr     print
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,control_port_handle

        lea     msg19c_control_enable,a1
        move.l  #msg19c_control_enable_end-msg19c_control_enable,d3
        bsr     print

        bsr     port_enable_control_current
        tst.l   d0
        bne.w   fail_control_enable_main

        lea     msg19c_control_action_ok,a1
        move.l  #msg19c_control_action_ok_end-msg19c_control_action_ok,d3
        bsr     print

        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,control_port_handle
        move.l  port_enabled,d0
        cmp.l   #1,d0
        bne.w   fail_control_enable_verify

        lea     msg19c_control_verify_ok,a1
        move.l  #msg19c_control_verify_ok_end-msg19c_control_verify_ok,d3
        bsr     print

        lea     msg_port_input,a1
        move.l  #msg_port_input_end-msg_port_input,d3
        bsr     print
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,input_port_handle

        move.l  port_buf_num,input_before_buf_num
        move.l  port_buf_size,input_before_buf_size

        lea     msg19c_format_prepare,a1
        move.l  #msg19c_format_prepare_end-msg19c_format_prepare,d3
        bsr     print

        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_H264,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        tst.l   v10b_input_is_mkv
        beq.s   v10g_first_fmt_flags_done
        move.l  #MMAL_ES_FORMAT_FLAG_FRAMED,port_fmt_flags
v10g_first_fmt_flags_done:
        move.l  h264_codec_config_len,d0
        move.l  d0,port_fmt_extra

        move.l  v6_src_aligned_w,port_video_width
        move.l  v6_src_aligned_h,port_video_height
        move.l  v6_src_crop_x,port_crop_x
        move.l  v6_src_crop_y,port_crop_y
        move.l  v6_src_visible_w,port_crop_width
        move.l  v6_src_visible_h,port_crop_height
        move.l  v7_fps_num,port_fps_num
        move.l  v7_fps_den,port_fps_den
        move.l  #1,port_par_num
        move.l  #1,port_par_den
        clr.l   port_color_space

        lea     input_extradata,a1
        moveq   #31,d7
t19c_extra_clear:
        clr.l   (a1)+
        dbra    d7,t19c_extra_clear

        lea     input_extradata,a1
        lea     h264_file_extradata,a0
        move.l  h264_codec_config_len,d7
        subq.l  #1,d7
t19c_extra_copy:
        move.b  (a0)+,(a1)+
        dbra    d7,t19c_extra_copy

        lea     msg19c_format_values,a1
        move.l  #msg19c_format_values_end-msg19c_format_values,d3
        bsr     print

        ; H264RGB4: codec extradata above is parsed SPS+PPS from the selected file.
        ; TEST33: commit the decoder-recommended input geometry instead of
        ; the TEST31D/E minimum 1 x 2048.  VideoCore reported 1 x 0x14000.
        move.l  #INPUT_POOL_COUNT,port_buf_num
        move.l  #INPUT_DATA_SIZE,port_buf_size

        lea     msg_set_start,a1
        move.l  #msg_set_start_end-msg_set_start,d3
        bsr     print

        bsr     port_info_set_input

        lea     msg19c_verify_input,a1
        move.l  #msg19c_verify_input_end-msg19c_verify_input,d3
        bsr     print

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get

        move.l  port_last_handle,d0
        cmp.l   input_port_handle,d0
        bne.w   fail_verify_input

        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   fail_verify_h264
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_H264,d0
        bne.w   fail_verify_h264

        move.l  port_fmt_flags,d0
        and.l   #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        tst.l   v10b_input_is_mkv
        beq.s   v10g_first_verify_unframed
        cmpi.l  #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        bne.w   fail_verify_h264
        bra.s   v10g_first_verify_flags_ok
v10g_first_verify_unframed:
        tst.l   d0
        bne.w   fail_verify_h264
v10g_first_verify_flags_ok:

        move.l  port_video_width,d0
        cmp.l   v6_src_aligned_w,d0
        bne.w   fail_verify_h264
        move.l  port_video_height,d0
        cmp.l   v6_src_aligned_h,d0
        bne.w   fail_verify_h264
        move.l  port_crop_x,d0
        cmp.l   v6_src_crop_x,d0
        bne.w   fail_verify_h264
        move.l  port_crop_y,d0
        cmp.l   v6_src_crop_y,d0
        bne.w   fail_verify_h264
        move.l  port_crop_width,d0
        cmp.l   v6_src_visible_w,d0
        bne.w   fail_verify_h264
        move.l  port_crop_height,d0
        cmp.l   v6_src_visible_h,d0
        bne.w   fail_verify_h264

        move.l  port_par_num,d0
        cmp.l   #1,d0
        bne.w   fail_verify_h264
        move.l  port_par_den,d0
        cmp.l   #1,d0
        bne.w   fail_verify_h264

        move.l  port_fmt_extra,d0
        cmp.l   h264_codec_config_len,d0
        bne.w   fail_verify_h264

        lea     input_extradata,a0
        lea     h264_file_extradata,a1
        move.l  h264_codec_config_len,d7
        subq.l  #1,d7
t19c_extra_verify:
        moveq   #0,d0
        move.b  (a0)+,d0
        cmp.b   (a1)+,d0
        bne.w   fail_verify_h264
        dbra    d7,t19c_extra_verify

        move.l  port_buf_num,d0
        cmp.l   #INPUT_POOL_COUNT,d0
        bcs.w   fail_verify_input
        move.l  port_buf_size,d0
        cmp.l   #H264_MAX_DATA_LEN,d0
        bcs.w   fail_verify_input

        move.l  port_buf_num,input_before_buf_num
        move.l  port_buf_size,input_before_buf_size
        move.l  port_fmt_extra,input_before_extra

        lea     msg19c_format_verified,a1
        move.l  #msg19c_format_verified_end-msg19c_format_verified,d3
        bsr     print

        lea     msg_port_output,a1
        move.l  #msg_port_output_end-msg_port_output,d3
        bsr     print
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,output_port_handle

        lea     msg_port_clock,a1
        move.l  #msg_port_clock_end-msg_port_clock,d3
        bsr     print
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        bsr     port_info_get
        move.l  port_last_handle,clock_port_handle

        lea     msg_ports_summary,a1
        move.l  #msg_ports_summary_end-msg_ports_summary,d3
        bsr     print

        lea     msg_sum_control,a1
        move.l  #msg_sum_control_end-msg_sum_control,d3
        bsr     print
        move.l  control_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_sum_input,a1
        move.l  #msg_sum_input_end-msg_sum_input,d3
        bsr     print
        move.l  input_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_sum_output,a1
        move.l  #msg_sum_output_end-msg_sum_output,d3
        bsr     print
        move.l  output_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_sum_clock,a1
        move.l  #msg_sum_clock_end-msg_sum_clock,d3
        bsr     print
        move.l  clock_port_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_ports_success,a1
        move.l  #msg_ports_success_end-msg_ports_success,d3
        bsr     print

; --------------------------------------------------------------------
; 18. Re-read INPUT 0 so port_* globals describe exactly this port,
;     then enable it with MMAL PORT_ACTION / ENABLE.
; --------------------------------------------------------------------
        lea     msg_enable_start,a1
        move.l  #msg_enable_start_end-msg_enable_start,d3
        bsr     print

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get

        move.l  port_last_handle,d0
        cmp.l   input_port_handle,d0
        bne.w   fail_enable_main

        lea     msg_enable_before,a1
        move.l  #msg_enable_before_end-msg_enable_before,d3
        bsr     print
        move.l  port_enabled,d0
        bsr     print_hex32
        bsr     newline

        bsr     port_enable_current
        tst.l   d0
        bne.w   fail_enable_main

        lea     msg_enable_action_ok,a1
        move.l  #msg_enable_action_ok_end-msg_enable_action_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 19. Verify INPUT 0 reports enabled=1.
; --------------------------------------------------------------------
        lea     msg_enable_verify,a1
        move.l  #msg_enable_verify_end-msg_enable_verify,d3
        bsr     print

        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        bsr     port_info_get

        move.l  port_enabled,d0
        cmp.l   #1,d0
        bne.w   fail_enable_verify

        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   fail_enable_verify

        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_H264,d0
        bne.w   fail_enable_verify

        lea     msg_enable_verify_ok,a1
        move.l  #msg_enable_verify_ok_end-msg_enable_verify_ok,d3
        bsr     print

; --------------------------------------------------------------------
; V12A. Decoder OUTPUT is no longer copied to host memory at source size.
; Build a VideoCore-only tunnel:
;   ril.video_decode OUTPUT -> ril.isp INPUT -> 192xN I420 OUTPUT -> host
; The old HAM6 scaler still receives an ordinary small I420 frame.
; --------------------------------------------------------------------
        lea     msg_v12a_graph_start,a1
        move.l  #msg_v12a_graph_start_end-msg_v12a_graph_start,d3
        bsr     print
        jsr     v12a_setup_isp_graph
        tst.l   d0
        bne.w   fail_output_enable_main

        ; V6C: prepare aspect-correct nearest-neighbour maps from decoded I420
        ; crop into the fixed 192x144 HAM6 surface.
        bsr     v6_scale_prepare
        tst.l   d0
        bne.w   h19_bad_local

; --------------------------------------------------------------------
; 22. Enable decoder component.
; --------------------------------------------------------------------
        lea     msg_component_enable,a1
        move.l  #msg_component_enable_end-msg_component_enable,d3
        bsr     print

        bsr     component_enable_worker
        tst.l   d0
        bne.w   fail_component_enable_main

        lea     msg_component_enable_ok,a1
        move.l  #msg_component_enable_ok_end-msg_component_enable_ok,d3
        bsr     print

; --------------------------------------------------------------------
; 23..28. Queue one empty output buffer, read raw H264 in fixed 65536-byte
; unframed chunks with NO AU knowledge, recycle the same input buffer, and collect:
;   A) an OUTPUT EVENT_TO_HOST (typically format negotiation), or
;   B) an OUTPUT BUFFER_TO_HOST with real data, followed by BULK_RX.
; --------------------------------------------------------------------
        bsr     h264_output_test
        tst.l   d0
        bne.w   fail_buffer_main

        move.l  v13_stop_requested,d0
        tst.l   d0
        beq.s   v13_first_natural_success
        lea     msg_v13_stop_success,a1
        move.l  #msg_v13_stop_success_end-msg_v13_stop_success,d3
        bsr     print
        bra.s   v13_first_success_done
v13_first_natural_success:
        lea     msg_test19_success,a1
        move.l  #msg_test19_success_end-msg_test19_success,d3
        bsr     print
v13_first_success_done:

        ; V9: close_prog now performs ordered teardown instead of requiring reboot.
        bsr     dma_pre_all
        bra.w   close_prog

fail_control_enable_main:
        lea     e19c_control_enable,a1
        move.l  #e19c_control_enable_end-e19c_control_enable,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_control_enable_verify:
        lea     e19c_control_verify,a1
        move.l  #e19c_control_verify_end-e19c_control_verify,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_enable_main:
        lea     e_enable_main,a1
        move.l  #e_enable_main_end-e_enable_main,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_enable_verify:
        lea     e_enable_verify,a1
        move.l  #e_enable_verify_end-e_enable_verify,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_output_enable_main:
        lea     e19_output_enable,a1
        move.l  #e19_output_enable_end-e19_output_enable,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_output_enable_verify:
        lea     e19_output_verify,a1
        move.l  #e19_output_verify_end-e19_output_verify,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_component_enable_main:
        lea     e_component_enable,a1
        move.l  #e_component_enable_end-e_component_enable,d3
        bsr     print
        bsr     dma_pre_all
        bra.w   close_prog

fail_buffer_main:
        lea     e_buffer_main,a1
        move.l  #e_buffer_main_end-e_buffer_main,d3
        bsr     print
        ; h264_bulk_test returns with shared VCHIQ RAM CPU-owned.
        bsr     dma_pre_all
        bra.w   close_prog

; --------------------------------------------------------------------
; PORT_INFO_GET helper
;
; Inputs via globals:
;   port_query_type
;   port_query_index
;
; On success:
;   port_last_handle and diagnostic fields are updated.
;   Shared memory is CPU-owned on return.
;
; Request = MMAL header 24 + payload 12 = 36 bytes.
; VCHIQ stride = align8(8 + 36) = 48 bytes.
;
; Full firmware reply is normally:
;   MMAL header 24
;   port_info_get_reply 292
; = 316 VCHIQ payload bytes, stride 328.
; We calculate the actual returned stride from RX size.
; --------------------------------------------------------------------
port_info_get:
        ; V13 restart: the existing v9f local-1 PORT_INFO_GET helper has
        ; already been hardware-proven repeatedly during second-decoder setup.
        ; Reuse it for every ISP graph GET instead of the first-run polling path.
        tst.l   v12f_local_port
        beq.s   v12h_port_info_get_first
        jmp     v9f_port_info_get
v12h_port_info_get_first:
        movem.l d2-d7/a2-a3,-(sp)

        ; Unique synchronous context = 0x14000000 | port_type.
        move.l  #$14000000,d0
        move.l  port_query_type,d1
        or.l    d1,d0
        move.l  d0,port_query_context

        ; V12G restart: absolute TX position must be mapped through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_get_tx_legacy
        move.l  #48,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   fail_port_rxslot
        bra.s   v12g_get_tx_ready
v12g_get_tx_legacy:
        ; Original first-run mapping, intentionally unchanged.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_get_tx_ready:

        ; VCHIQ DATA header, destination = opened VC MMAL port.
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #36,d0
        bsr     store_le32

        ; MMAL header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_INFO_GET,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  port_query_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; port_info_get payload.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  port_query_type,d0
        bsr     store_le32

        lea     40(a2),a0
        move.l  port_query_index,d0
        bsr     store_le32

        ; Advance host stream by one 48-byte VCHIQ stride.
        move.l  port_tx_pos,d0
        add.l   #48,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        ; Signal VC event.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,port_armed

        bsr     dma_pre_all

        move.l  port_armed,d0
        tst.l   d0
        beq.w   port_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

port_no_bell:
        move.l  #POLL_COUNT,d7

port_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   port_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   port_poll_loop
        bra.w   fail_port_timeout

port_reply_seen:
        ; V12D: extra ISP setup replies may be in the next MASTER slot.
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   fail_port_rxslot
        move.l  a2,a0

        ; VCHIQ header.
        bsr     load_le32
        move.l  d0,port_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,port_rx_size

        ; DATA type?
        move.l  port_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_port_wrongmsg

        ; Destination local port 0?
        move.l  port_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   fail_port_wrongport

        ; Source is the opened MMAL VC port?
        move.l  port_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_port_wrongport

        ; Need enough bytes through video.color_space.
        move.l  port_rx_size,d0
        cmp.l   #188,d0
        bcs.w   fail_port_short

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,port_mmal_hstatus

        ; port_info_get_reply fixed prefix.
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_status

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_component

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_type

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,port_reply_index

        lea     52(a2),a0
        bsr     load_le32
        move.l  d0,port_last_handle

        ; struct mmal_port begins at message offset 56.
        lea     72(a2),a0
        bsr     load_le32
        move.l  d0,port_enabled

        lea     80(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_num_min

        lea     84(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_size_min

        lea     88(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_align

        lea     92(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_num_rec

        lea     96(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_size_rec

        lea     100(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_num

        lea     104(a2),a0
        bsr     load_le32
        move.l  d0,port_buf_size

        lea     116(a2),a0
        bsr     load_le32
        move.l  d0,port_caps

        ; struct mmal_es_format begins at message offset 120.
        lea     120(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_type

        lea     124(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_encoding

        lea     128(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_variant

        lea     136(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_bitrate

        lea     140(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_flags

        lea     144(a2),a0
        bsr     load_le32
        move.l  d0,port_fmt_extra

        ; union mmal_es_specific_format begins at offset 152.
        ; These fields are useful when format type is VIDEO.
        lea     152(a2),a0
        bsr     load_le32
        move.l  d0,port_video_width

        lea     156(a2),a0
        bsr     load_le32
        move.l  d0,port_video_height

        lea     160(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_x

        lea     164(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_y

        lea     168(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_width

        lea     172(a2),a0
        bsr     load_le32
        move.l  d0,port_crop_height

        lea     176(a2),a0
        bsr     load_le32
        move.l  d0,port_fps_num

        lea     180(a2),a0
        bsr     load_le32
        move.l  d0,port_fps_den

        lea     184(a2),a0
        bsr     load_le32
        move.l  d0,port_par_num

        lea     188(a2),a0
        bsr     load_le32
        move.l  d0,port_par_den

        lea     192(a2),a0
        bsr     load_le32
        move.l  d0,port_color_space

        ; Preserve codec extradata only when this reply is INPUT 0.
        move.l  port_query_type,d0
        cmp.l   #MMAL_PORT_INPUT,d0
        bne.w   port_extra_done
        move.l  port_query_index,d0
        tst.l   d0
        bne.w   port_extra_done

        move.l  port_fmt_extra,d0
        cmp.l   #128,d0
        bhi.w   fail_port_extradata

        lea     input_extradata,a0
        move.l  #31,d7
port_extra_clear_loop:
        clr.l   (a0)+
        dbra    d7,port_extra_clear_loop

        move.l  port_fmt_extra,d7
        tst.l   d7
        beq.w   port_extra_done
        subq.l  #1,d7
        lea     196(a2),a0
        lea     input_extradata,a1
port_extra_copy_loop:
        move.b  (a0)+,(a1)+
        dbra    d7,port_extra_copy_loop

port_extra_done:
        ; Validate reply identity.
        move.l  port_mmal_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_port_magic

        move.l  port_mmal_type,d0
        cmp.l   #MMAL_PORT_INFO_GET,d0
        bne.w   fail_port_type

        move.l  port_mmal_context,d0
        cmp.l   port_query_context,d0
        bne.w   fail_port_context

        move.l  port_mmal_hstatus,d0
        tst.l   d0
        bne.w   fail_port_status

        move.l  port_reply_status,d0
        tst.l   d0
        bne.w   fail_port_status

        move.l  port_reply_component,d0
        cmp.l   component_handle,d0
        bne.w   fail_port_component

        move.l  port_reply_type,d0
        cmp.l   port_query_type,d0
        bne.w   fail_port_identity

        move.l  port_reply_index,d0
        cmp.l   port_query_index,d0
        bne.w   fail_port_identity

        ; port_handle is opaque. Value 0 is VALID for the MMAL control
        ; port on real Raspberry Pi firmware, so do not reject it.

        ; Print compact but useful port information.
        lea     msg_p_handle,a1
        move.l  #msg_p_handle_end-msg_p_handle,d3
        bsr     print
        move.l  port_last_handle,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_enabled,a1
        move.l  #msg_p_enabled_end-msg_p_enabled,d3
        bsr     print
        move.l  port_enabled,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_min,a1
        move.l  #msg_p_min_end-msg_p_min,d3
        bsr     print
        move.l  port_buf_num_min,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size_min,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_rec,a1
        move.l  #msg_p_rec_end-msg_p_rec,d3
        bsr     print
        move.l  port_buf_num_rec,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size_rec,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_cur,a1
        move.l  #msg_p_cur_end-msg_p_cur,d3
        bsr     print
        move.l  port_buf_num,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_align,a1
        move.l  #msg_p_align_end-msg_p_align,d3
        bsr     print
        move.l  port_buf_align,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_caps,a1
        move.l  #msg_p_caps_end-msg_p_caps,d3
        bsr     print
        move.l  port_caps,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_format,a1
        move.l  #msg_p_format_end-msg_p_format,d3
        bsr     print
        move.l  port_fmt_type,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_encoding,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_variant,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_p_video,a1
        move.l  #msg_p_video_end-msg_p_video,d3
        bsr     print
        move.l  port_video_width,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  port_video_height,d0
        bsr     print_hex32
        lea     msg_crop,a1
        move.l  #msg_crop_end-msg_crop,d3
        bsr     print
        move.l  port_crop_width,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  port_crop_height,d0
        bsr     print_hex32
        bsr     newline

        ; Move to next VC stream message and recycle a crossed MASTER slot.
        move.l  port_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   fail_port_rxslot

        movem.l (sp)+,d2-d7/a2-a3
        rts


; --------------------------------------------------------------------
; PORT_INFO_SET current INPUT 0 state back to VideoCore.
;
; Request layout (wire, 32-bit pointers):
;   MMAL header                     24
;   component/type/index            12
;   mmal_port                       64
;   mmal_es_format                  32
;   mmal_es_specific_format         44
;   extradata                      128
; Total MMAL payload               304
; VCHIQ stride = align8(8+304)     312
;
; Per Linux/RPi implementation, only writable MMAL_PORT fields are sent:
;   buffer_num, buffer_size, userdata.
; Format + ES + extradata are copied from the preceding INPUT GET.
; --------------------------------------------------------------------
port_info_set_input:
        movem.l d2-d7/a2-a3,-(sp)

        ; Sanity before sending.
        move.l  port_query_type,d0
        cmp.l   #MMAL_PORT_INPUT,d0
        beq.s   v12_set_type_ok
        cmp.l   #MMAL_PORT_OUTPUT,d0
        bne.w   fail_set_identity
v12_set_type_ok:
        move.l  port_query_index,d0
        tst.l   d0
        bne.w   fail_set_identity
        move.l  port_fmt_extra,d0
        cmp.l   #128,d0
        bhi.w   fail_set_extradata

        move.l  #$15000002,set_context

        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_set_tx_legacy
        move.l  #312,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   fail_set_rxslot
        bra.s   v12g_set_tx_ready
v12g_set_tx_legacy:
        ; Original first-run mapping.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_set_tx_ready:

        ; Clear complete 312-byte VCHIQ message first.
        move.l  a2,a0
        move.l  #77,d7
set_clear_loop:
        clr.l   (a0)+
        dbra    d7,set_clear_loop

        ; VCHIQ DATA header.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #304,d0
        bsr     store_le32

        ; MMAL worker header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_INFO_SET,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  set_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; mmal_worker_port_info_set fixed prefix.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  port_query_type,d0
        bsr     store_le32

        lea     40(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; mmal_port starts at 44.
        ; Only client-writable fields are meaningful for SET:
        ; buffer_num @ +44, buffer_size @ +48, userdata @ +56
        ; relative to mmal_port, therefore message offsets 88,92,100.
        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32

        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32

        lea     100(a2),a0
        move.l  #MMAL_INPUT_USERDATA,d0
        bsr     store_le32

        ; mmal_es_format starts at 108.
        lea     108(a2),a0
        move.l  port_fmt_type,d0
        bsr     store_le32

        lea     112(a2),a0
        move.l  port_fmt_encoding,d0
        bsr     store_le32

        lea     116(a2),a0
        move.l  port_fmt_variant,d0
        bsr     store_le32

        ; es pointer @120 remains zero.

        lea     124(a2),a0
        move.l  port_fmt_bitrate,d0
        bsr     store_le32

        lea     128(a2),a0
        move.l  port_fmt_flags,d0
        bsr     store_le32

        lea     132(a2),a0
        move.l  port_fmt_extra,d0
        bsr     store_le32

        ; extradata pointer @136 remains zero.

        ; mmal_es_specific_format.video starts at 140.
        lea     140(a2),a0
        move.l  port_video_width,d0
        bsr     store_le32

        lea     144(a2),a0
        move.l  port_video_height,d0
        bsr     store_le32

        lea     148(a2),a0
        move.l  port_crop_x,d0
        bsr     store_le32

        lea     152(a2),a0
        move.l  port_crop_y,d0
        bsr     store_le32

        lea     156(a2),a0
        move.l  port_crop_width,d0
        bsr     store_le32

        lea     160(a2),a0
        move.l  port_crop_height,d0
        bsr     store_le32

        lea     164(a2),a0
        move.l  port_fps_num,d0
        bsr     store_le32

        lea     168(a2),a0
        move.l  port_fps_den,d0
        bsr     store_le32

        lea     172(a2),a0
        move.l  port_par_num,d0
        bsr     store_le32

        lea     176(a2),a0
        move.l  port_par_den,d0
        bsr     store_le32

        lea     180(a2),a0
        move.l  port_color_space,d0
        bsr     store_le32

        ; Extradata begins at 184 and is already zeroed.
        move.l  port_fmt_extra,d7
        tst.l   d7
        beq.w   set_extra_done
        subq.l  #1,d7
        lea     input_extradata,a0
        lea     184(a2),a1
set_extra_copy_loop:
        move.b  (a0)+,(a1)+
        dbra    d7,set_extra_copy_loop

set_extra_done:
        lea     msg_set_tx,a1
        move.l  #msg_set_tx_end-msg_set_tx,d3
        bsr     print
        move.l  port_buf_num,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_buf_size,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_set_fmt,a1
        move.l  #msg_set_fmt_end-msg_set_fmt,d3
        bsr     print
        move.l  port_fmt_type,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_encoding,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  port_fmt_variant,d0
        bsr     print_hex32
        bsr     newline

        ; Advance local stream by 312 bytes and notify VC.
        move.l  port_tx_pos,d0
        add.l   #312,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,set_armed

        bsr     dma_pre_all

        move.l  set_armed,d0
        tst.l   d0
        beq.w   set_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

set_no_bell:
        move.l  #POLL_COUNT,d7

set_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   set_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   set_poll_loop
        bra.w   fail_set_timeout

set_reply_seen:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   fail_set_rxslot
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,set_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,set_rx_size

        ; VCHIQ DATA and correct remote/local ports.
        move.l  set_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   fail_set_wrongmsg

        move.l  set_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   fail_set_wrongport

        move.l  set_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   fail_set_wrongport

        ; Need at least MMAL header + reply status/component/type/index.
        move.l  set_rx_size,d0
        cmp.l   #40,d0
        bcs.w   fail_set_short

        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,set_magic

        lea     12(a2),a0
        bsr     load_le32
        move.l  d0,set_type

        lea     20(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_context

        lea     24(a2),a0
        bsr     load_le32
        move.l  d0,set_header_status

        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_status

        lea     36(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_component

        lea     40(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_port_type

        lea     44(a2),a0
        bsr     load_le32
        move.l  d0,set_reply_index

        lea     msg_set_reply,a1
        move.l  #msg_set_reply_end-msg_set_reply,d3
        bsr     print
        move.l  set_rx_size,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_set_status,a1
        move.l  #msg_set_status_end-msg_set_status,d3
        bsr     print
        move.l  set_reply_status,d0
        bsr     print_hex32
        bsr     newline

        ; Validate MMAL reply.
        move.l  set_magic,d0
        cmp.l   #MMAL_MAGIC,d0
        bne.w   fail_set_magic

        move.l  set_type,d0
        cmp.l   #MMAL_PORT_INFO_SET,d0
        bne.w   fail_set_type

        move.l  set_reply_context,d0
        cmp.l   set_context,d0
        bne.w   fail_set_context

        move.l  set_header_status,d0
        tst.l   d0
        bne.w   fail_set_status

        move.l  set_reply_status,d0
        tst.l   d0
        bne.w   fail_set_status

        move.l  set_reply_component,d0
        cmp.l   component_handle,d0
        bne.w   fail_set_identity

        move.l  set_reply_port_type,d0
        cmp.l   port_query_type,d0
        bne.w   fail_set_identity

        move.l  set_reply_index,d0
        tst.l   d0
        bne.w   fail_set_identity

        ; Advance VC stream slot-safely.
        move.l  set_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   fail_set_rxslot

        lea     msg_set_ok,a1
        move.l  #msg_set_ok_end-msg_set_ok,d3
        bsr     print

        movem.l (sp)+,d2-d7/a2-a3
        rts


; --------------------------------------------------------------------
; PORT_ACTION ENABLE helper for the port currently described by port_*.
;
; Request:
;   MMAL header                 24
;   component_handle             4
;   port_handle                  4
;   action                       4
;   struct mmal_port            64
; = MMAL DATA payload          100
; VCHIQ header + payload = 108 -> stride 112.
;
; Reply:
;   MMAL header 24 + status 4 = 28 -> VCHIQ stride 40.
;
; Returns D0=0 success, D0=1 failure.
; Always returns with shared memory CPU-owned.
; --------------------------------------------------------------------
port_enable_current:
        movem.l d2-d7/a2-a3,-(sp)

        move.l  #$16000002,enable_context

        ; Host slot 34 + current tx position.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2

        ; Clear complete request area (112 bytes) first.
        move.l  a2,a0
        move.l  #27,d7
enable_clear_loop:
        clr.l   (a0)+
        dbra    d7,enable_clear_loop

        ; VCHIQ DATA header.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #100,d0
        bsr     store_le32

        ; MMAL header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  enable_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; PORT_ACTION payload.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  input_port_handle,d0
        bsr     store_le32

        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_ENABLE,d0
        bsr     store_le32

        ; struct mmal_port at offset 44.
        ; priv/name = 0
        lea     52(a2),a0               ; port.type
        move.l  #MMAL_PORT_INPUT,d0
        bsr     store_le32

        ; index/index_all both zero -> packed u16/u16 word remains zero.

        lea     60(a2),a0               ; is_enabled
        move.l  port_enabled,d0
        bsr     store_le32

        ; format pointer field at 64 remains zero.

        lea     68(a2),a0
        move.l  port_buf_num_min,d0
        bsr     store_le32

        lea     72(a2),a0
        move.l  port_buf_size_min,d0
        bsr     store_le32

        lea     76(a2),a0
        move.l  port_buf_align,d0
        bsr     store_le32

        lea     80(a2),a0
        move.l  port_buf_num_rec,d0
        bsr     store_le32

        lea     84(a2),a0
        move.l  port_buf_size_rec,d0
        bsr     store_le32

        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32

        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32

        ; component pointer field at 96 remains zero.
        lea     100(a2),a0              ; userdata opaque client cookie
        move.l  #$16000002,d0
        bsr     store_le32

        lea     104(a2),a0              ; capabilities (RO, but harmless)
        move.l  port_caps,d0
        bsr     store_le32

        ; Publish new host tx pos.
        move.l  port_tx_pos,d0
        add.l   #112,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        ; Signal VC.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,enable_armed

        bsr     dma_pre_all

        move.l  enable_armed,d0
        tst.l   d0
        beq.w   enable_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

enable_no_bell:
        move.l  #POLL_COUNT,d7

enable_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   enable_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   enable_poll_loop

        ; timeout: regain CPU ownership before returning
        bsr     dma_post_all
        lea     e_enable_timeout,a1
        move.l  #e_enable_timeout_end-e_enable_timeout,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

enable_reply_seen:
        ; Current tests are still within first VC data slot.
        move.l  remote_slot0,d0
        cmp.l   #2,d0
        bcs.w   enable_bad_reply
        cmp.l   #32,d0
        bhi.w   enable_bad_reply

        move.l  slot_ptr,a0
        move.l  remote_slot0,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_rx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2

        bsr     load_le32
        move.l  d0,enable_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,enable_rx_size

        ; VCHIQ DATA / local port 0 / source mmal VC port.
        move.l  enable_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   enable_bad_reply

        move.l  enable_rx_msgid,d0
        and.l   #$00000fff,d0
        bne.w   enable_bad_reply

        move.l  enable_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   enable_bad_reply

        move.l  enable_rx_size,d0
        cmp.l   #28,d0
        bcs.w   enable_bad_reply

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   enable_bad_reply

        lea     12(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   enable_bad_reply

        lea     20(a2),a0
        bsr     load_le32
        cmp.l   enable_context,d0
        bne.w   enable_bad_reply

        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   enable_bad_reply

        ; port_action_reply.status
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,enable_status

        lea     msg_enable_status,a1
        move.l  #msg_enable_status_end-msg_enable_status,d3
        bsr     print
        move.l  enable_status,d0
        bsr     print_hex32
        bsr     newline

        move.l  enable_status,d0
        tst.l   d0
        bne.w   enable_bad_reply

        ; Advance VC stream by actual VCHIQ stride.
        move.l  enable_rx_size,d0
        add.l   #15,d0
        and.l   #$fffffff8,d0
        add.l   port_rx_pos,d0
        move.l  d0,port_rx_pos

        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

enable_bad_reply:
        lea     e_enable_reply,a1
        move.l  #e_enable_reply_end-e_enable_reply,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

port_enable_control_current:
