        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2

        ; Clear complete request area (112 bytes) first.
        move.l  a2,a0
        move.l  #27,d7
ctrl_enable_clear_loop:
