        bsr     load_le32
        move.l  d0,ctrl_enable_rx_size

        ; VCHIQ DATA / local port 0 / source mmal VC port.
        move.l  ctrl_enable_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   ctrl_enable_bad_reply

        move.l  ctrl_enable_rx_msgid,d0
        and.l   #$00000fff,d0
        bne.w   ctrl_enable_bad_reply

        move.l  ctrl_enable_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   ctrl_enable_bad_reply

        move.l  ctrl_enable_rx_size,d0
        cmp.l   #28,d0
        bcs.w   ctrl_enable_bad_reply

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   ctrl_enable_bad_reply

        lea     12(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   ctrl_enable_bad_reply

        lea     20(a2),a0
        bsr     load_le32
        cmp.l   ctrl_enable_context,d0
        bne.w   ctrl_enable_bad_reply

        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   ctrl_enable_bad_reply

        ; port_action_reply.status
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,ctrl_enable_status

        lea     msg_enable_status,a1
        move.l  #msg_enable_status_end-msg_enable_status,d3
        bsr     print
        move.l  ctrl_enable_status,d0
        bsr     print_hex32
        bsr     newline

        move.l  ctrl_enable_status,d0
        tst.l   d0
        bne.w   ctrl_enable_bad_reply

        ; Advance VC stream by actual VCHIQ stride.
        move.l  ctrl_enable_rx_size,d0
        add.l   #15,d0
        and.l   #$fffffff8,d0
        add.l   port_rx_pos,d0
        move.l  d0,port_rx_pos

        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

ctrl_enable_bad_reply:
        lea     e_enable_reply,a1
        move.l  #e_enable_reply_end-e_enable_reply,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts


port_enable_output_current:
        movem.l d2-d7/a2-a3,-(sp)

        move.l  #$1900E002,out_enable_context

        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_outen_tx_legacy
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   out_enable_bad_reply
        bra.s   v12g_outen_tx_ready
v12g_outen_tx_legacy:
        ; Original first-run mapping.
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_outen_tx_ready:

        ; Clear complete request area (112 bytes) first.
        move.l  a2,a0
        move.l  #27,d7
out_enable_clear_loop:
        clr.l   (a0)+
        dbra    d7,out_enable_clear_loop

        ; VCHIQ DATA header.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #100,d0
        bsr     store_le32

        ; MMAL header.
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  out_enable_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; PORT_ACTION payload.
        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        lea     36(a2),a0
        move.l  output_port_handle,d0
        bsr     store_le32

        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_ENABLE,d0
        bsr     store_le32

        ; struct mmal_port at offset 44.
        ; priv/name = 0
        lea     52(a2),a0               ; port.type
        move.l  #MMAL_PORT_OUTPUT,d0
        bsr     store_le32

        ; index/index_all both zero -> packed u16/u16 word remains zero.

        lea     60(a2),a0               ; is_enabled
        move.l  port_enabled,d0
        bsr     store_le32

        ; format pointer field at 64 remains zero.

        lea     68(a2),a0
        move.l  port_buf_num_min,d0
        bsr     store_le32

        lea     72(a2),a0
        move.l  port_buf_size_min,d0
        bsr     store_le32

        lea     76(a2),a0
        move.l  port_buf_align,d0
        bsr     store_le32

        lea     80(a2),a0
        move.l  port_buf_num_rec,d0
        bsr     store_le32

        lea     84(a2),a0
        move.l  port_buf_size_rec,d0
        bsr     store_le32

        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32

        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32

        ; component pointer field at 96 remains zero.
        lea     100(a2),a0              ; userdata opaque client cookie
        move.l  #$1900E002,d0
        bsr     store_le32

        lea     104(a2),a0              ; capabilities (RO, but harmless)
        move.l  port_caps,d0
        bsr     store_le32

        ; Publish new host tx pos.
        move.l  port_tx_pos,d0
        add.l   #112,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        ; Signal VC.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,out_enable_armed

        bsr     dma_pre_all

        move.l  out_enable_armed,d0
        tst.l   d0
        beq.w   out_enable_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

out_enable_no_bell:
        move.l  #POLL_COUNT,d7

out_enable_poll_loop:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   out_enable_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   out_enable_poll_loop

        ; timeout: regain CPU ownership before returning
        bsr     dma_post_all
        lea     e_enable_timeout,a1
        move.l  #e_enable_timeout_end-e_enable_timeout,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

out_enable_reply_seen:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   out_enable_bad_reply
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,out_enable_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,out_enable_rx_size

        ; VCHIQ DATA / local port 0 / source mmal VC port.
        move.l  out_enable_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   out_enable_bad_reply

        move.l  out_enable_rx_msgid,d0
        and.l   #$00000fff,d0
        cmp.l   v12f_local_port,d0
        bne.w   out_enable_bad_reply

        move.l  out_enable_rx_msgid,d0
        lsr.l   #8,d0
        lsr.l   #4,d0
        and.l   #$00000fff,d0
        cmp.l   mmal_remote_port,d0
        bne.w   out_enable_bad_reply

        move.l  out_enable_rx_size,d0
        cmp.l   #28,d0
        bcs.w   out_enable_bad_reply

        ; MMAL header.
        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   out_enable_bad_reply

        lea     12(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   out_enable_bad_reply

        lea     20(a2),a0
        bsr     load_le32
        cmp.l   out_enable_context,d0
        bne.w   out_enable_bad_reply

        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   out_enable_bad_reply

        ; port_action_reply.status
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,out_enable_status

        lea     msg_enable_status,a1
        move.l  #msg_enable_status_end-msg_enable_status,d3
        bsr     print
        move.l  out_enable_status,d0
        bsr     print_hex32
        bsr     newline

        move.l  out_enable_status,d0
        tst.l   d0
        bne.w   out_enable_bad_reply

        ; Advance VC stream slot-safely.
        move.l  out_enable_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   out_enable_bad_reply

        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

out_enable_bad_reply:
        lea     e_enable_reply,a1
        move.l  #e_enable_reply_end-e_enable_reply,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts


; --------------------------------------------------------------------
; COMPONENT_ENABLE helper.
; MMAL type 6, payload = component_handle (4 bytes).
; VCHIQ request stride 40, reply stride 40.
; Returns D0=0 success, D0=1 failure, CPU-owned shared RAM.
; --------------------------------------------------------------------
component_enable_worker:
        movem.l d2-d7/a2-a3,-(sp)

        move.l  #$1600E001,component_enable_context

        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_compen_tx_legacy
        move.l  #40,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   component_enable_bad_reply
        bra.s   v12g_compen_tx_ready
v12g_compen_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_compen_tx_ready:

        ; 40-byte VCHIQ stride, clear 10 longs.
        move.l  a2,a0
        moveq   #9,d7
component_enable_clear_loop:
        clr.l   (a0)+
        dbra    d7,component_enable_clear_loop

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32

        lea     4(a2),a0
        move.l  #28,d0
        bsr     store_le32

        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32

        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_ENABLE,d0
        bsr     store_le32

        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     20(a2),a0
        move.l  component_enable_context,d0
        bsr     store_le32

        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        lea     32(a2),a0
        move.l  component_handle,d0
        bsr     store_le32

        move.l  port_tx_pos,d0
        add.l   #40,d0
        move.l  d0,port_tx_pos

        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,component_enable_armed

        bsr     dma_pre_all

        move.l  component_enable_armed,d0
        tst.l   d0
        beq.w   component_enable_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2

component_enable_no_bell:
        move.l  #POLL_COUNT,d7

component_enable_poll:
        bsr     short_delay
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bhi.w   component_enable_reply_seen

        bsr     dma_pre_all
        subq.l  #1,d7
        bne.w   component_enable_poll

        bsr     dma_post_all
        lea     e_component_enable_timeout,a1
        move.l  #e_component_enable_timeout_end-e_component_enable_timeout,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

component_enable_reply_seen:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   component_enable_bad_reply
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,component_enable_rx_msgid

        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,component_enable_rx_size

        move.l  component_enable_rx_msgid,d0
        and.l   #$ff000000,d0
        cmp.l   #VCHIQ_MSG_DATA,d0
        bne.w   component_enable_bad_reply

        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   component_enable_bad_reply

        lea     12(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_COMPONENT_ENABLE,d0
        bne.w   component_enable_bad_reply

        lea     20(a2),a0
        bsr     load_le32
        cmp.l   component_enable_context,d0
        bne.w   component_enable_bad_reply

        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   component_enable_bad_reply

        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,component_enable_status

        lea     msg_component_status,a1
        move.l  #msg_component_status_end-msg_component_status,d3
        bsr     print
        move.l  component_enable_status,d0
        bsr     print_hex32
        bsr     newline

        move.l  component_enable_status,d0
        tst.l   d0
        bne.w   component_enable_bad_reply

        move.l  component_enable_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   component_enable_bad_reply

        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

component_enable_bad_reply:
        lea     e_component_enable_reply,a1
        move.l  #e_component_enable_reply_end-e_component_enable_reply,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts


; --------------------------------------------------------------------
; TEST17 - BUFFER_FROM_HOST empty-buffer roundtrip
;
; Official 32-bit worker structure:
;   MMAL header                       24
;   drvbuf                            16
;   drvbuf_ref                        16
;   MMAL_BUFFER_HEADER_T              56
;   type-specific                     40
;   is_zero_copy                       4
;   has_reference                      4
;   payload_in_message                 4
;   short_data                       128
; --------------------------------------
; MMAL payload total                 292 = 0x124
; VCHIQ header + payload             300
; VCHIQ aligned stride               304
;
; For this first buffer test:
;   cmd=0, length=0, offset=0, flags=0
;   payload_in_message=0
;   is_zero_copy=0
;   has_reference=0
;   pts=dts=MMAL_TIME_UNKNOWN
;   NO BULK is submitted.
;
; Return:
;   D0=0 success
;   D0=1 failure
; Shared memory is CPU-owned on return.
; --------------------------------------------------------------------
h264_output_test:
        movem.l d2-d7/a2-a3,-(sp)

        clr.l   v5_wait_stage
        clr.l   v5_wait_timeout_stage
        clr.l   v5_wait_pending
        clr.l   v5_wait_switch
        clr.l   v5_wait_active
        clr.l   v5_wait_display
        clr.l   v5_wait_vblank
        clr.l   v5_wait_raster
        clr.l   bulk_done_seen
        clr.l   eos_sent
        clr.l   eos_pending
        clr.l   eos_bulk_done
        clr.l   eos_return_seen
        clr.l   buffer_seen
        clr.l   event_seen
        clr.l   output_event_seen
        clr.l   v10h_error_seen
        clr.l   v10h_error_status
        clr.l   v10h_last_frame_no
        clr.l   v10h_last_frame_payload
        clr.l   v10h_last_pts_ticks
        clr.l   v10h_last_nal_count
        clr.l   v10h_last_fragment_no
        clr.l   v10h_last_chunk_len
        clr.l   v10h_last_chunk_flags
        clr.l   v10h_last_nal_type
        clr.l   v10h_current_frame_payload
        clr.l   v10h_chunk_fragment_no
        clr.l   output_buffer_seen
        clr.l   output_bulk_queued
        clr.l   output_bulk_done
        clr.l   output_dma_active
        lea     output_dma_active_slots,a0
        moveq   #0,d0
        moveq   #OUTPUT_POOL_MAX-1,d1
v10j_clear_output_dma_slots:
        move.l  d0,(a0)+
        dbra    d1,v10j_clear_output_dma_slots
        clr.l   output_current_idx
        clr.l   output_header_idx
        clr.l   output_empty_idx
        clr.l   output_deferred_count
        clr.l   output_deferred_head
        clr.l   output_deferred_tail
        clr.l   output_eos_seen
        clr.l   output_current_eos
        clr.l   output_pagelist_dma_active
        clr.l   bulk_dma_active
        clr.l   input_return_total
        clr.l   input_bulk_total
        clr.l   input_bulk_pending
        clr.l   input_in_use_count
        clr.l   input_eof_seen
        clr.l   bulk_current_slot
        clr.l   bulk_current_context
        clr.l   output_frame_total
        clr.l   t8c_display_frame_total
        clr.l   t8c_skipped_frames
        clr.l   t8c_late_skipped_frames
        lea     input_slot_state,a0
        moveq   #0,d0
        moveq   #INPUT_POOL_COUNT-1,d1
h31e_clear_input_states:
        move.l  d0,(a0)+
        dbra    d1,h31e_clear_input_states
        move.l  #1,frame_cycle
        move.l  #30,bulk_grace

        lea     msg19_prepare_output,a1
        move.l  #msg19_prepare_output_end-msg19_prepare_output,d3
        bsr     print

        ; ------------------------------------------------------------
        ; V10P: allocate the ACTUAL host I420 output pool requested from MMAL.
        ; V10I proved that merely declaring buffer_num=19 is not enough for
        ; 1.mkv: VideoCore still returned ENOSPC while only two host headers
        ; were offered.  Here each requested buffer gets its own page-aligned
        ; max-size slot. One serialized BULK_RX pagelist remains shared.
        ; ------------------------------------------------------------
        move.l  output_buf_size_saved,d0
        tst.l   d0
        beq.w   h19_bad_local
        cmp.l   #OUTPUT_MAX_DMA,d0
        bhi.w   h19_bad_local

        move.l  v10j_output_req_count,d2
        cmpi.l  #2,d2
        bcs.w   h19_bad_local
        cmpi.l  #OUTPUT_POOL_MAX,d2
        bhi.w   h19_bad_local

        ; pagelist offset = requested_count * OUTPUT_SLOT_STRIDE.
        moveq   #0,d0
        move.l  d2,d3
v10j_output_size_loop:
        add.l   #OUTPUT_SLOT_STRIDE,d0
        subq.l  #1,d3
        bne.s   v10j_output_size_loop
        move.l  d0,output_pagelist_offset_saved
        add.l   #OUTPUT_ALLOC_EXTRA,d0
        move.l  d0,output_alloc_size_saved

        move.l  a4,a6
        move.l  output_alloc_size_saved,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   h19_output_alloc_fail
        move.l  d0,output_alloc

        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,output_data_ptr0
        move.l  d0,output_data_ptr

        move.l  d0,d1
        add.l   #OUTPUT_SLOT_STRIDE,d1
        move.l  d1,output_data_ptr1

        move.l  d0,d1
        add.l   output_pagelist_offset_saved,d1
        move.l  d1,output_pagelist_ptr

        cmp.l   #$3f000000,d0
        bcc.w   h19_output_map_fail
        cmp.l   #$3f000000,d1
        bcc.w   h19_output_map_fail

        move.l  output_data_ptr,d0
        or.l    #$c0000000,d0
        move.l  d0,output_data_bus
        move.l  output_pagelist_ptr,d0
        or.l    #$c0000000,d0
        move.l  d0,output_pagelist_bus

        ; TEST61: two page-aligned I420 output buffers are offered at once.
        ; VideoCore can decode into one while Emu68 converts the other.
        ; A single shared pagelist is sufficient because host BULK_RX itself
        ; remains serialized; only decoded-buffer ownership is double buffered.

        lea     msg19_output_cpu,a1
        move.l  #msg19_output_cpu_end-msg19_output_cpu,d3
        bsr     print
        move.l  output_data_ptr0,d0
        bsr     print_hex32
        bsr     newline

        lea     msg61_output_cpu1,a1
        move.l  #msg61_output_cpu1_end-msg61_output_cpu1,d3
        bsr     print
        move.l  output_data_ptr1,d0
        bsr     print_hex32
        bsr     newline

        lea     msg19_output_bus,a1
        move.l  #msg19_output_bus_end-msg19_output_bus,d3
        bsr     print
        move.l  output_data_ptr0,d0
        or.l    #$c0000000,d0
        bsr     print_hex32
        bsr     newline

        lea     msg19_output_size,a1
        move.l  #msg19_output_size_end-msg19_output_size,d3
        bsr     print
        move.l  output_buf_size_saved,d0
        bsr     print_hex32
        bsr     newline
        lea     msg_v10j_pool_info,a1
        move.l  #msg_v10j_pool_info_end-msg_v10j_pool_info,d3
        bsr     print
        move.l  v10j_output_req_count,d0
        bsr     print_hex32
        lea     msg_v10j_pool_info_mid,a1
        move.l  #msg_v10j_pool_info_mid_end-msg_v10j_pool_info_mid,d3
        bsr     print
        move.l  output_alloc_size_saved,d0
        bsr     print_hex32
        bsr     newline

        lea     msg19_queue_output,a1
        move.l  #msg19_queue_output_end-msg19_queue_output,d3
        bsr     print

        moveq   #0,d6
v10j_queue_initial_outputs:
        move.l  d6,d0
        bsr     h61_queue_output_idx
        tst.l   d0
        bne.w   h19_bad_reply
        addq.l  #1,d6
        cmp.l   v10j_output_req_count,d6
        bcs.s   v10j_queue_initial_outputs

        lea     msg61_output_queued,a1
        move.l  #msg61_output_queued_end-msg61_output_queued,d3
        bsr     print

        ; ------------------------------------------------------------
        ; TEST33 INPUT POOL
        ; Allocate 1 reusable 64-KiB MMAL input buffer plus one EOS slot.
        ; The data slot owns 20 data pages, one pagelist page and one guard page.
        ; Only one VCHIQ BULK_TX is outstanding at a time, but previously
        ; transferred MMAL buffers may remain owned by VideoCore while the
        ; next free pool slot is filled and sent.
        ; ------------------------------------------------------------
        lea     msg19_prepare_input,a1
        move.l  #msg19_prepare_input_end-msg19_prepare_input,d3
        bsr     print

        move.l  a4,a6
        move.l  #BULK_ALLOC_SIZE,d0
        move.l  #MEMF_FASTCLEAR,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   h19_bulk_alloc_fail
        move.l  d0,bulk_alloc

        add.l   #$00000fff,d0
        and.l   #$fffff000,d0
        move.l  d0,bulk_pool_base

        ; Entire single-slot pool must remain in the Pi3/Emu68 DMA window.
        move.l  d0,d1
        add.l   #$00083fff,d1
        cmp.l   #$3f000000,d0
        bcc.w   h19_bulk_map_fail
        cmp.l   #$3f000000,d1
        bcc.w   h19_bulk_map_fail

        ; Feed the first block through slot 0.  Further blocks are queued
        ; automatically as BULK_TX_DONE / BUFFER_TO_HOST callbacks arrive.
        bsr     t31s_feed_next_input
        tst.l   d0
        bne.w   h22_resend_fail

        lea     msg19_wait,a1
        move.l  #msg19_wait_end-msg19_wait,d3
        bsr     print

        move.l  #POLL_COUNT,d7

; ------------------------------------------------------------
; Collect input BULK_TX_DONE, output event/buffer, and if required
; output BULK_RX_DONE.
; ------------------------------------------------------------
h19_poll:
        bsr     short_delay
        bsr     dma_post_all

        ; V13: Ctrl-C belongs only to this CLI process.  On first detection,
        ; stop presenting RGB immediately, but keep the MMAL/VCHIQ engine alive
        ; long enough to send EOS, drain ownership and use the proven cleanup.
        bsr     v13_poll_ctrl_c
        tst.l   d0
        beq.s   h19_check
        move.l  #1,input_eof_seen
        bsr     t31s_display_abort_cleanup

h19_check:
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        move.l  d0,d5

        cmp.l   port_rx_pos,d5
        bls.w   h19_no_msg

        ; TEST26C: map absolute RX stream position through MASTER slot_queue.
        ; Low 12 bits are offset within the selected 4-KiB slot.
        bsr     h26a_map_rx_current
        tst.l   d0
        bne.w   h19_bad_reply

        ; TEST26C: h26a_map_rx_current returns the mapped record in A2.
        ; load_le32 reads from A0, so explicitly select the returned header.
        move.l  a2,a0
        bsr     load_le32
        move.l  d0,bulk_rx_msgid
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,bulk_rx_size

        jmp     v9g_h19_dispatch
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop

h19_input_bulk_done:
        move.l  bulk_rx_size,d0
        cmp.l   #4,d0
        bcs.w   h19_bad_reply
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,bulk_actual

        ; TEST33: after EOS has been published, every further BULK_TX_DONE
        ; belongs to the official 8-byte EOS dummy.  Normal stream bulks are
        ; serialized: only one is outstanding, while up to 20 MMAL buffers
        ; may remain VideoCore-owned.
        move.l  eos_sent,d1
        tst.l   d1
        bne.w   h19a_eos_bulk_done_msg

        move.l  input_bulk_pending,d1
        tst.l   d1
        beq.w   h19_bad_reply
        cmp.l   current_h264_bulk_len,d0
        bne.w   h19_bad_bulk_actual

        clr.l   input_bulk_pending
        move.l  #1,bulk_done_seen
        addq.l  #1,input_bulk_total

        move.l  bulk_dma_active,d0
        tst.l   d0
        beq.w   h19a_after_h264_dma_post
        move.l  #BULK_DMA_SIZE,bulk_dma_len
        move.l  bulk_data_ptr,a0
        lea     bulk_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   bulk_dma_active

h19a_after_h264_dma_post:
        ; The DMA transfer is complete, but this pool slot remains busy until
        ; its unique MMAL BUFFER_TO_HOST context returns.  h19_consume may now
        ; feed another free slot immediately.
        bra.w   h19_consume

h19a_eos_bulk_done_msg:
        ; After H264, the next BULK_TX_DONE must be the 8-byte dummy
        ; associated with MMAL_WORKER_BUFFER_FROM_HOST_ZEROLEN.
        move.l  eos_sent,d1
        tst.l   d1
        beq.w   h19_bad_reply
        move.l  eos_bulk_done,d1
        tst.l   d1
        bne.w   h19_bad_reply
        cmp.l   #EOS_BULK_LEN,d0
        bne.w   h19a_bad_eos_actual

        move.l  #1,eos_bulk_done

        move.l  bulk_dma_active,d0
        tst.l   d0
        beq.w   h19a_after_eos_dma_post
        move.l  #BULK_DMA_SIZE,bulk_dma_len
        move.l  bulk_data_ptr,a0
        lea     bulk_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   bulk_dma_active

h19a_after_eos_dma_post:
        lea     msg19a_eos_done,a1
        move.l  #msg19a_eos_done_end-msg19a_eos_done,d3
        bsr     print
        bra.w   h19_consume

; ------------------------------------------------------------
; Send the official MMAL >=12.2 zero-length EOS sequence:
;   Worker 24, buffer length=0, flags=EOS
;   immediately followed by an 8-byte dummy VCHIQ BULK_TX.
; Shared VCHIQ memory is CPU-owned on entry.
; ------------------------------------------------------------
h19a_send_eos:
        lea     msg19a_eos_send,a1
        move.l  #msg19a_eos_send_end-msg19a_eos_send,d3
        bsr     print

        ; Use a dedicated 21st pool slot for EOS. Normal input slots may
        ; still be VideoCore-owned here, so reusing the last normal slot would
        ; be unsafe and could recreate the TEST31D end-of-stream deadlock.
        move.l  bulk_pool_base,d0
        add.l   #INPUT_SLOT_STRIDE,d0  ; EOS slot directly after the single data slot
        move.l  d0,bulk_data_ptr
        move.l  d0,d1
        add.l   #INPUT_PAGELIST_OFFSET,d1
        move.l  d1,bulk_pagelist_ptr

        move.l  d0,d2
        or.l    #$c0000000,d2
        move.l  d2,bulk_data_bus
        move.l  d1,d2
        or.l    #$c0000000,d2
        move.l  d2,bulk_pagelist_bus

        ; Dummy payload bytes are irrelevant, but keep them deterministic.
        move.l  bulk_data_ptr,a0
        clr.l   (a0)
        clr.l   4(a0)

        ; Build the dedicated one-page write pagelist for 8 dummy bytes.
        move.l  bulk_pagelist_ptr,a0
        move.l  #EOS_BULK_LEN,d0
        bsr     store_le32
        move.l  bulk_pagelist_ptr,a0
        move.b  #PAGELIST_WRITE,4(a0)
        clr.b   5(a0)
        clr.b   6(a0)
        clr.b   7(a0)
        lea     8(a0),a0
        move.l  bulk_data_bus,d0
        bsr     store_le32

        ; Enter DMA ownership for the dedicated EOS data + pagelist pages.
        move.l  #BULK_DMA_SIZE,bulk_dma_len
        move.l  bulk_data_ptr,a0
        lea     bulk_dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        move.l  d0,bulk_phys
        cmp.l   bulk_data_ptr,d0
        bne.w   h19_bulk_dma_fail
        move.l  bulk_dma_len,d1
        cmp.l   #BULK_DMA_SIZE,d1
        bcs.w   h19_bulk_dma_fail
        move.l  #1,bulk_dma_active

        ; Host slot 34 + current tx position. 304-byte Worker + 16 bulk.
        move.l  #320,d0
        bsr     h26a_reserve_tx
        tst.l   d0
        bne.w   h19_bad_reply

        move.l  a2,a0
        move.l  #79,d7
h19a_clear_eos_control:
        clr.l   (a0)+
        dbra    d7,h19a_clear_eos_control

        ; Worker 24 as normal VCHIQ DATA message.
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        move.l  mmal_remote_port,d1
        or.l    d1,d0
        or.l    port_query_index,d0
        nop
        bsr     store_le32
        lea     4(a2),a0
        move.l  #292,d0
        bsr     store_le32

        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_BUFFER_FROM_HOST_ZEROLEN,d0
        bsr     store_le32
        lea     16(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     20(a2),a0
        move.l  #MMAL_EOS_BUFFER_CONTEXT,d0
        bsr     store_le32
        lea     24(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     28(a2),a0
        moveq   #0,d0
        bsr     store_le32

        ; drvbuf -> decoder input.
        lea     32(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     36(a2),a0
        move.l  component_handle,d0
        bsr     store_le32
        lea     40(a2),a0
        move.l  input_port_handle,d0
        bsr     store_le32
        lea     44(a2),a0
        move.l  #MMAL_EOS_BUFFER_CONTEXT,d0
        bsr     store_le32

        ; buffer_header.data valid, alloc size valid, length=0, EOS=1.
        lea     76(a2),a0
        move.l  bulk_data_ptr,d0
        bsr     store_le32
        lea     80(a2),a0
        move.l  input_before_buf_size,d0
        bsr     store_le32
        ; length @84 = 0, offset @88 = 0
        lea     92(a2),a0
        move.l  #MMAL_BUFFER_FLAG_EOS,d0
        bsr     store_le32

        ; pts/dts unknown.
        lea     96(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     100(a2),a0
        move.l  #$80000000,d0
        bsr     store_le32
        lea     104(a2),a0
        moveq   #0,d0
        bsr     store_le32
        lea     108(a2),a0
        move.l  #$80000000,d0
        bsr     store_le32

        ; payload_in_message remains zero.

        ; Dummy BULK_TX immediately follows Worker 24.
        lea     304(a2),a3
        move.l  a3,a0
        move.l  #VCHIQ_MSG_BULK_TX,d0
        move.l  mmal_remote_port,d1
        or.l    d1,d0
        or.l    port_query_index,d0
        nop
        bsr     store_le32
        lea     4(a3),a0
        move.l  #8,d0
        bsr     store_le32
        lea     8(a3),a0
        move.l  bulk_pagelist_bus,d0
        bsr     store_le32
        lea     12(a3),a0
        move.l  #EOS_BULK_LEN,d0
        bsr     store_le32

        move.l  port_tx_pos,d0
        add.l   #320,d0
        move.l  d0,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,eos_armed

        move.l  #1,eos_sent

        ; Give VideoCore shared VCHIQ memory back, then ring if armed.
        bsr     dma_pre_all
        move.l  eos_armed,d0
        tst.l   d0
        beq.w   h19a_no_eos_bell
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
h19a_no_eos_bell:
        ; Fresh full observation window after the EOS marker.
        move.l  #POLL_COUNT,d7
        bra.w   h19_poll

h19_output_bulk_done_msg:
        move.l  bulk_rx_size,d0
        cmp.l   #4,d0
        bcs.w   h19_bad_reply
        lea     8(a2),a0
        bsr     load_le32
        move.l  d0,output_bulk_actual


        move.l  output_bulk_actual,d0
        cmp.l   output_bulk_len,d0
        bne.w   h19_bad_output_actual

        ; End pagelist DMA phase (VC read it).
        move.l  output_pagelist_dma_active,d0
        tst.l   d0
        beq.w   h19_post_output_data
        move.l  #12,output_pagelist_dma_len
        move.l  output_pagelist_ptr,a0
        lea     output_pagelist_dma_len,a1
        move.l  #DMA_ReadFromRAM,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        clr.l   output_pagelist_dma_active

h19_post_output_data:
        ; VideoCore wrote the current I420 slot. Return only that slot to CPU.
        move.l  output_current_idx,d0
        bsr     h61_post_output_dma_idx
        tst.l   d0
        bne.w   h19_bad_reply

h19_after_output_post:
        move.l  #1,output_bulk_done

        ; TEST33: only validate the returned I420 frame size here.
        ; The old full Y/U/V byte-sum diagnostics scanned another 115200 bytes
        ; per frame and were useful while proving decoder correctness, but they
        ; are deliberately removed from the live 25-fps path.
        move.l  output_bulk_actual,d0
        cmp.l   output_frame_bytes_expected,d0
        bne.w   h22_bad_frame_size

        ; TEST33 STREAMING:
        ; The current I420 frame is not stored in a movie-sized Fast-RAM array.
        ; Convert selected pictures immediately into the inactive Chip-RAM buffer.
        ; V9 keeps native timing below 25 fps; higher source rates are decoded
        ; completely but rationally reduced to max. 25 fps for RGB/HAM6.
        ; The MMAL output buffer is recycled afterwards,
        ; providing natural back-pressure so decoding cannot run away from video.
        ; H264RGB2: there is no fixed output-frame ceiling. Every complete
        ; I420 payload is accepted until the decoder returns OUTPUT EOS.

        ; TEST33 RGB streaming: convert this I420 frame immediately into
        ; the inactive Chip-RAM display buffer and schedule it from the real
        ; VERTB timebase.  The MMAL output buffer is recycled only afterwards,
        ; so the whole pipeline remains bounded-memory and naturally back-pressured.
        ; V13: after Ctrl-C, keep draining/recycling decoder output but never
        ; restart or update the RGB display that was just restored.
        move.l  v13_stop_requested,d0
        tst.l   d0
        bne.w   h8c_rgb_frame_done

        ; V9 RGB policy for sources above 25 fps:
        ; MMAL still returns and we still count/recycle EVERY decoded picture.
        ; A rational source-frame selector reduces only the classic RGB/HAM6
        ; path to at most 25 pictures/s.  50 fps becomes 1/2, 30 fps becomes
        ; 5/6, 30000/1001 is handled by the same accumulator.
        move.l  t8c_cap25_mode,d0
        tst.l   d0
        beq.s   h8c_selected_rgb_candidate
        move.l  t8c_select_accum,d0
        add.l   t8c_select_step,d0
        cmp.l   v7_fps_num,d0
        bcs.s   h8c_rate_skip_rgb_frame
        sub.l   v7_fps_num,d0
        move.l  d0,t8c_select_accum
        bra.s   h8c_selected_rgb_candidate
h8c_rate_skip_rgb_frame:
        move.l  d0,t8c_select_accum
        addq.l  #1,t8c_skipped_frames
        bra.w   h8c_rgb_frame_done

        ; V8B let lateness move the future timeline and stretched the movie.
        ; V9 keeps an absolute 25-fps grid.  If a selected RGB candidate
        ; reaches us at or after its nominal target, do not spend more time
        ; converting an image whose 40-ms display slot has already started.
        ; Skip it only for RGB and advance the nominal grid by one 40-ms slot.
h8c_selected_rgb_candidate:
        move.l  t8c_cap25_mode,d0
        tst.l   d0
        beq.s   h8c_stream_rgb_frame
        move.l  t31s_display_started,d0
        tst.l   d0
        beq.s   h8c_stream_rgb_frame
        move.l  t31s_next_switch_vblank,d1
        tst.l   d1
        beq.s   h8c_stream_rgb_frame
        move.l  t31s_vblank_counter,d0
        sub.l   d0,d1                     ; d1 = nominal headroom
        tst.l   d1
        bgt.s   h8c_stream_rgb_frame       ; still at least one full VBlank before target
        addq.l  #1,t8c_late_skipped_frames
        addq.l  #2,t31s_next_switch_vblank
        bra.s   h8c_rgb_frame_done

h8c_stream_rgb_frame:
        bsr     t31s_stream_current_frame
        tst.l   d0
        bne.w   h30_store_fail
        addq.l  #1,t8c_display_frame_total
h8c_rgb_frame_done:
        move.l  output_current_idx,d0
        tst.l   d0
        bne.s   h61_count_slot1
        addq.l  #1,t61_slot0_frames
        bra.s   h61_count_slot_done
h61_count_slot1:
        addq.l  #1,t61_slot1_frames
h61_count_slot_done:
        addq.l  #1,output_frame_total

        ; TEST33: absolutely no DOS/console output in the frame-critical
        ; streaming section.  All useful counters remain in memory and are
        ; printed only after success/failure.
        bra.w   h19_consume

h30_store_fail:
        lea     e30_store_frame,a1
        move.l  #e30_store_frame_end-e30_store_frame,d3
        bsr     print
        bsr     t31s_display_abort_cleanup
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        beq.s   h30_store_fail_no_v5
        bsr     v5_print_wait_timeout
h30_store_fail_no_v5:
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

; --------------------------------------------------------------------
; TEST33 - true bounded-memory streaming presentation
;
 ; Current VideoCore I420 output stays in output_data_ptr. Y, U and V are source data.
; A dedicated 20736-byte Fast-RAM color-planar scratch frame is then copied
; into one of the two 20736-byte Chip-RAM display buffers.
; No decoded movie frames are retained after presentation.
;
; Timing:
;   frame 1: start at T0, reload at T1 for its second PAL refresh
;   frame 2: switch at T2, reload at T3
;   frame 3: switch at T4, reload at T5 ...
; This gives 25 video frames/s on a 50 Hz PAL display. The decoder output buffer
; is not recycled until the second refresh has started, which deliberately
; back-pressures MMAL instead of accumulating decoded frames in RAM.
; --------------------------------------------------------------------
t31s_stream_current_frame:
        movem.l d1-d7/a0-a6,-(sp)

        ; TEST33 stage 1: MMAL/VCHIQ gap since previous streamed frame.
        move.l  t31s_vblank_counter,d0
        move.l  d0,d1
        sub.l   t31u_last_stream_end_vblank,d1
        add.l   d1,t31u_gap_total
        tst.l   d1
        beq.w   t31u_gap_no_nonzero
        addq.l  #1,t31u_gap_nonzero
t31u_gap_no_nonzero:
        cmp.l   t31u_gap_max,d1
        bls.w   t31u_gap_max_ok
        move.l  d1,t31u_gap_max
t31u_gap_max_ok:

        ; Select the alternating Chip-RAM destination, but do not wait for it
        ; yet. The Fast-RAM conversion can proceed while Agnus still displays
        ; this buffer from two frames ago.
        move.l  t30_chip_ptr,a1
        cmpa.l  #0,a1
        beq.w   t31s_stream_fail
        move.l  t8c_display_frame_total,d0
        and.l   #1,d0
        beq.w   t31w_chip_dest_ready
        adda.l  #T30_FRAME_BYTES,a1
t31w_chip_dest_ready:
        move.l  a1,t30_display_ptr

        ; TEST61 stage 2: I420 YUV420 -> HAM6 in Fast RAM.
        ;
        ; Decoder geometry follows the SPS. RGB/HAM output is fixed low-resolution 192x144;
        ; V6 scales the complete visible crop with aspect preservation and black bars.
        ; The compact scratch contains six 3456-byte planes = 20736 bytes.
        ;
        ; HAM6 is stateful across a scanline.  COLOR00 is black and hardware
        ; resets the held color to COLOR00 at every new line.  For each pixel
        ; the encoder uses exactly the TEST49 direct/Blue/Red/Green decision rules,
       ; but TEST61 resolves them through precomputed Fast-RAM transition tables.
       ; The 4096-entry target table still supplies the YUV->4-bit RGB target.
        move.l  t31s_vblank_counter,d0
        move.l  d0,t31u_stage_start_vblank

        ; V9: build a low-resolution 192x144 scaled I420
        ; rows (aspect preserved, black bars as required) and feed the unchanged
        ; HAM6 row encoder. IMPORTANT: HAM output must first go to the Fast-RAM
        ; scratch. V6B accidentally left A1 pointing at the selected Chip buffer,
        ; bypassing Dirty8 and making the conversion much slower.
        move.l  t33_fast_ptr,a1         ; 192x144 HAM plane-0 row pointer in Fast RAM
        cmpa.l  #0,a1
        beq.w   t31s_stream_fail
        bsr     v6_scale_frame_to_ham
        tst.l   d0
        bne.w   t31s_stream_fail

        move.l  t31s_vblank_counter,d0
        sub.l   t31u_stage_start_vblank,d0
        add.l   d0,t31u_convert_total
        tst.l   d0
        beq.w   t31u_convert_no_nonzero
        addq.l  #1,t31u_convert_nonzero
t31u_convert_no_nonzero:
        cmp.l   t31u_convert_max,d0
        bls.w   t31u_convert_max_ok
        move.l  d0,t31u_convert_max
t31u_convert_max_ok:

        ; TEST61 stage 3: wait until the selected Chip buffer is reusable.
        ; Normally TEST56 waited until the VBlank ISR had switched ACTIVE away.
        ; TEST61 can release the old ACTIVE buffer a little earlier: if the
        ; alternate prepared frame is due on the NEXT VBlank, then after PAL V8
        ; becomes set (raster >=256) the visible HAM window ending at line $E4
        ; has already been fetched completely.  No further bitplane DMA will
        ; read the old buffer before the pending VBlank takeover, so Dirty8 may
        ; safely start in the lower border instead of waiting for that VBlank.
        move.l  t31s_vblank_counter,d0
        move.l  d0,t31u_stage_start_vblank
        move.l  t31s_display_started,d0
        tst.l   d0
        beq.w   t31w_buffer_free
        move.l  #V5_SPIN_TIMEOUT,d7

t31w_wait_buffer_free:
        subq.l  #1,d7
        bne.s   t31w_wait_buffer_watch_ok
        move.l  #2,v5_wait_stage
        bsr     v5_mark_wait_timeout
        bra.w   t31s_stream_fail
t31w_wait_buffer_watch_ok:
        ; If ISR already promoted the other buffer, destination is fully free.
        move.l  t30_active_ptr,d0
        cmp.l   t30_display_ptr,d0
        bne.w   t31w_buffer_free

        ; Early release is legal only while another prepared buffer is pending.
        move.l  t31s_pending_valid,d0
        tst.l   d0
        beq.w   t31w_wait_buffer_free

        ; We must be in the PAL refresh immediately BEFORE the pending switch.
        move.l  t31s_switch_vblank,d1
        subq.l  #1,d1
        move.l  t31s_vblank_counter,d0
        cmp.l   d1,d0
        bne.w   t31w_wait_buffer_free

        ; DIWSTOP is now line $E4. For this isolated resolution test we keep
        ; the older conservative release point: VPOSR V8 set means raster >=256,
        ; safely below the complete 192x144 HAM window.
        lea     CUSTOM_BASE,a0
        move.w  VPOSR(a0),d0
        btst    #0,d0
        beq.w   t31w_wait_buffer_free

        ; Guard the tiny raster/VBlank race: counter must still be target-1.
        move.l  t31s_vblank_counter,d0
        cmp.l   d1,d0
        bne.w   t31w_wait_buffer_free
        addq.l  #1,t57_early_release_total

t31w_buffer_free:
        move.l  t31s_vblank_counter,d0
        sub.l   t31u_stage_start_vblank,d0
        add.l   d0,t31u_buffer_total
        tst.l   d0
        beq.w   t31u_buffer_no_nonzero
        addq.l  #1,t31u_buffer_nonzero
t31u_buffer_no_nonzero:
        cmp.l   t31u_buffer_max,d0
        bls.w   t31u_buffer_max_ok
        move.l  d0,t31u_buffer_max
t31u_buffer_max_ok:

        ; TEST61 stage 4: temporal dirty-copy from Fast scratch to Chip RAM.
        ; Each Chip buffer is reused every second video frame.  A separate Fast
        ; shadow mirrors the exact contents of each Chip buffer.  Compare all
        ; 5184 longwords against that Fast mirror and touch the slow Chip bus
        ; only when a longword really changed.  The visible frame is bit-exact
        ; to TEST52; this changes transfer policy only.
        move.l  t31s_vblank_counter,d0
        move.l  d0,t31u_stage_start_vblank
        move.l  t33_fast_ptr,a0
        move.l  t30_display_ptr,a1
        move.l  t56_shadow_ptr,a2
        cmpa.l  #0,a2
        beq.w   t31s_stream_fail
        move.l  t8c_display_frame_total,d0
        and.l   #1,d0
        beq.s   t56_shadow_ready
        adda.l  #T30_FRAME_BYTES,a2
t56_shadow_ready:
        moveq   #0,d1                       ; changed longwords this frame
        move.w  #647,d7                     ; 648 groups * 8 longs = 5184 longs
; TEST61: exact TEST53 dirty policy, but 8x unrolled.  A2 postincrements in CMP,
; A1 advances in the changed store or the unchanged path.  This removes one
; address ADDQ per longword and seven of eight DBRA iterations.
t56_dirty_copy_loop:
        move.l  (a0)+,d0
        cmp.l   (a2)+,d0
        beq.s   t56_dc0_same
        move.l  d0,-4(a2)
        move.l  d0,(a1)+
        addq.l  #1,d1
        bra.s   t56_dc0_done
t56_dc0_same:
        addq.l  #4,a1
t56_dc0_done:
        move.l  (a0)+,d0
        cmp.l   (a2)+,d0
        beq.s   t56_dc1_same
        move.l  d0,-4(a2)
        move.l  d0,(a1)+
        addq.l  #1,d1
        bra.s   t56_dc1_done
t56_dc1_same:
        addq.l  #4,a1
t56_dc1_done:
        move.l  (a0)+,d0
        cmp.l   (a2)+,d0
        beq.s   t56_dc2_same
        move.l  d0,-4(a2)
        move.l  d0,(a1)+
        addq.l  #1,d1
        bra.s   t56_dc2_done
t56_dc2_same:
        addq.l  #4,a1
t56_dc2_done:
        move.l  (a0)+,d0
        cmp.l   (a2)+,d0
        beq.s   t56_dc3_same
        move.l  d0,-4(a2)
        move.l  d0,(a1)+
        addq.l  #1,d1
        bra.s   t56_dc3_done
t56_dc3_same:
        addq.l  #4,a1
t56_dc3_done:
        move.l  (a0)+,d0
        cmp.l   (a2)+,d0
        beq.s   t56_dc4_same
        move.l  d0,-4(a2)
        move.l  d0,(a1)+
        addq.l  #1,d1
        bra.s   t56_dc4_done
t56_dc4_same:
        addq.l  #4,a1
t56_dc4_done:
        move.l  (a0)+,d0
        cmp.l   (a2)+,d0
        beq.s   t56_dc5_same
        move.l  d0,-4(a2)
        move.l  d0,(a1)+
        addq.l  #1,d1
        bra.s   t56_dc5_done
t56_dc5_same:
        addq.l  #4,a1
t56_dc5_done:
        move.l  (a0)+,d0
        cmp.l   (a2)+,d0
        beq.s   t56_dc6_same
        move.l  d0,-4(a2)
        move.l  d0,(a1)+
        addq.l  #1,d1
        bra.s   t56_dc6_done
t56_dc6_same:
        addq.l  #4,a1
t56_dc6_done:
        move.l  (a0)+,d0
        cmp.l   (a2)+,d0
        beq.s   t56_dc7_same
        move.l  d0,-4(a2)
        move.l  d0,(a1)+
        addq.l  #1,d1
        bra.s   t56_dc7_done
t56_dc7_same:
        addq.l  #4,a1
t56_dc7_done:
        dbra    d7,t56_dirty_copy_loop

        add.l   d1,t56_dirty_long_total
        cmp.l   t56_dirty_long_max,d1
        bls.s   t56_dirty_max_ok
        move.l  d1,t56_dirty_long_max
t56_dirty_max_ok:

        move.l  t31s_vblank_counter,d0
        sub.l   t31u_stage_start_vblank,d0
        add.l   d0,t31w_copy_total
        tst.l   d0
        beq.w   t31w_copy_no_nonzero
        addq.l  #1,t31w_copy_nonzero
t31w_copy_no_nonzero:
        cmp.l   t31w_copy_max,d0
        bls.w   t31w_copy_max_ok
        move.l  d0,t31w_copy_max
t31w_copy_max_ok:

        ; TEST61 stage 5: schedule/takeover/final-display synchronization.
        move.l  t31s_vblank_counter,d0
        move.l  d0,t31u_stage_start_vblank

        move.l  t31s_display_started,d0
        tst.l   d0
        bne.w   t31s_stream_schedule

        ; TEST63: two-frame preroll.  TEST62 proved that both MMAL/I420 slots
        ; really run in parallel and that steady-state delivery is essentially
        ; real-time.  Instead of showing frame 1 immediately and holding it for
        ; the old +6-VBlank startup reserve, prepare frames 1 and 2 completely
        ; before starting the RGB clock.  Then frame 2 can be scheduled exactly
        ; two PAL VBlanks after frame 1 without sacrificing startup headroom.
        move.l  t8c_display_frame_total,d0
        tst.l   d0
        bne.w   t63_start_preroll_display

        ; Human frame 1 is ready in its Chip buffer.  Keep Workbench/native
        ; takeover off for one more decoded frame and remember this buffer.
        move.l  t30_display_ptr,d0
        move.l  d0,t63_preroll_ptr
        move.l  #1,t63_preroll_frames
        bra.w   t31s_stream_check_final

t63_start_preroll_display:
        ; Only human frame 2 may arrive here while display_started is still 0.
        cmp.l   #1,d0
        bne.w   t31s_stream_fail
        move.l  t30_display_ptr,d2       ; prepared human frame 2
        move.l  t63_preroll_ptr,d1       ; prepared human frame 1
        tst.l   d1
        beq.w   t31s_stream_fail

        ; t30_display_begin publishes t30_display_ptr as ACTIVE and resets the
        ; VBlank clock.  Temporarily point it at frame 1, then restore frame 2
        ; as the pending next image after the first synchronized RGB VBlank.
        move.l  d1,t30_display_ptr
        bsr     t30_display_begin
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        bne.w   t31s_stream_fail
        move.l  #1,t31s_display_started
        move.l  d2,t30_display_ptr
        move.l  #2,t63_preroll_frames

        move.l  t31s_vblank_counter,d6
        jsr     v7_next_interval             ; V7: rational PAL-refresh interval for frame 2
        add.l   d0,d6
        move.l  d2,t31s_pending_ptr
        move.l  d6,t31s_switch_vblank
        move.l  #1,t31s_pending_valid
        jsr     v7_next_interval             ; human frame 3 nominal target
        add.l   d0,d6
        move.l  d6,t31s_next_switch_vblank
        bra.w   t31s_stream_check_final

t31s_stream_schedule:
        move.l  t31s_next_switch_vblank,d6
        move.l  d6,d5                       ; V9: immutable nominal target
        move.l  t31s_vblank_counter,d0

        ; TEST61 deadline/slack profile.  d6 is the absolute desired VBlank,
        ; d0 is the current VBlank after Fast conversion + Chip copy.
        ; Positive d1 = that many complete VBlanks of scheduling headroom.
        move.l  d6,d1
        sub.l   d0,d1
        cmp.l   #1,d1
        beq.w   t31x_slack_one
        cmp.l   #2,d1
        beq.w   t31x_slack_two
        cmp.l   #3,d1
        bge.w   t31x_slack_threeplus
        bra.w   t31x_slack_done
t31x_slack_one:
        addq.l  #1,t31x_slack1
        bra.w   t31x_slack_done
t31x_slack_two:
        addq.l  #1,t31x_slack2
        bra.w   t31x_slack_done
t31x_slack_threeplus:
        addq.l  #1,t31x_slack3plus
t31x_slack_done:
        ; TEST66: remember the current frame's true scheduling headroom.
        ; A 1-refresh catch-up is only safe when this frame arrived at least
        ; two full VBlanks before its target.
        move.l  d1,t66_current_slack

        cmp.l   d6,d0
        bcs.w   t31s_stream_target_ok

        ; TEST66 keeps TEST65's proven raster rescue and debt accounting.  The new part
        ; is below: if a rare miss really needs a later switch, remember the
        ; lost VBlank(s) as timing debt instead of permanently slowing every
        ; following frame.
        beq.w   t65_try_same_vblank
        addq.l  #1,t31x_past_target
        bra.w   t31x_miss_class_done

t65_try_same_vblank:
        lea     CUSTOM_BASE,a0
        moveq   #0,d2
        move.w  VPOSR(a0),d2
        andi.w  #$0001,d2                  ; V8 -> vertical bit 8
        lsl.w   #8,d2
        moveq   #0,d3
        move.w  VHPOSR(a0),d3
        lsr.w   #8,d3                      ; vertical low 8 bits
        or.w    d3,d2                      ; d2 = raster line 0..311
        cmpi.w  #$0052,d2                  ; V9/192x144: stay two lines before PAL VSTART $54
        bcc.w   t65_same_vblank_too_late

        ; Guard against a pathological wrap while the raster registers were
        ; sampled.  We must still be in this exact target VBlank.
        move.l  t31s_vblank_counter,d2
        cmp.l   d6,d2
        bne.w   t65_same_vblank_too_late

        move.l  t30_display_ptr,d2
        move.l  d2,t30_active_ptr
        bsr     t30_set_bpl_ptrs
        addq.l  #1,t65_same_vblank_total
        bra.w   t65_set_next_target

t65_same_vblank_too_late:
        addq.l  #1,t65_same_vblank_late
        addq.l  #1,t31x_at_target
t31x_miss_class_done:
        addq.l  #1,t31s_missed_deadlines

        ; Record the first two misses without any console I/O in the live path.
        move.l  d0,d2
        sub.l   d6,d2                    ; arithmetic lateness in VBlanks
        cmp.l   t31x_max_past_delta,d2
        bls.w   t31x_max_delta_ok
        move.l  d2,t31x_max_past_delta
t31x_max_delta_ok:
        move.l  t31s_missed_deadlines,d1
        cmp.l   #1,d1
        bne.w   t31x_try_miss2
        move.l  t8c_display_frame_total,d1
        addq.l  #1,d1                    ; report human frame number 1..N
        move.l  d1,t31x_miss1_frame
        move.l  d6,t31x_miss1_target
        move.l  d0,t31x_miss1_current
        move.l  d2,t31x_miss1_delta
        bra.w   t31x_miss_record_done
t31x_try_miss2:
        cmp.l   #2,d1
        bne.w   t31x_miss_record_done
        move.l  t8c_display_frame_total,d1
        addq.l  #1,d1
        move.l  d1,t31x_miss2_frame
        move.l  d6,t31x_miss2_target
        move.l  d0,t31x_miss2_current
        move.l  d2,t31x_miss2_delta
t31x_miss_record_done:

        ; Native <=25-fps sources retain TEST66's proven catch-up accounting.
        ; In V9 cap25 mode we deliberately create NO timing debt: the
        ; absolute 25-fps grid must never slide later. Following late RGB
        ; candidates are skipped before conversion until real time is caught up.
        move.l  t8c_cap25_mode,d1
        tst.l   d1
        bne.s   t8c_no_catchup_debt
        move.l  d0,d2
        sub.l   d6,d2
        addq.l  #1,d2
        add.l   d2,t65_catchup_debt
        add.l   d2,t65_debt_added_total
        move.l  t65_catchup_debt,d1
        cmp.l   t65_debt_max,d1
        bls.s   t65_debt_max_ok
        move.l  d1,t65_debt_max
t65_debt_max_ok:
t8c_no_catchup_debt:

        ; Current frame still gets a clean future refresh if same-VBlank rescue
        ; was no longer possible. The next nominal cap25 target is based on d5.
        move.l  d0,d6
        addq.l  #1,d6

t31s_stream_target_ok:
        move.l  t30_display_ptr,d0
        move.l  d0,t31s_pending_ptr
        move.l  d6,t31s_switch_vblank
        move.l  #1,t31s_pending_valid

t65_set_next_target:
        ; V9 cap25 mode uses an ABSOLUTE 25-fps timeline. d5 is the nominal
        ; target that belonged to this RGB candidate before any late rescue.
        ; A late actual switch can therefore never stretch all following frames.
        move.l  t8c_cap25_mode,d1
        tst.l   d1
        beq.s   t8c_native_next_interval
        move.l  d5,d6
        addq.l  #2,d6
        move.l  d6,t31s_next_switch_vblank
        bra.w   t31s_stream_check_final

t8c_native_next_interval:
        ; Native <=25-fps path: V7 rational scheduler remains unchanged.
        jsr     v7_next_interval
        move.l  d0,d3                       ; nominal interval, always >=1

        ; Keep every video frame visible for at least one PAL refresh.
        ; If previous lateness created timing debt, shorten only a nominal
        ; interval of at least 2 VBlanks and only with >=2 VBlanks headroom.
        ; This generalises TEST66 SAFE-CATCHUP without dropping a frame.
        move.l  output_current_eos,d1
        tst.l   d1
        bne.w   v7_next_apply
        move.l  t65_catchup_debt,d1
        tst.l   d1
        beq.w   v7_next_apply
        cmp.l   #2,d3
        bcs.s   v7_catchup_defer
        move.l  t66_current_slack,d2
        cmp.l   #2,d2
        bge.s   v7_catchup_safe
v7_catchup_defer:
        addq.l  #1,t66_catchup_deferred
        bra.s   v7_next_apply

v7_catchup_safe:
        subq.l  #1,d1
        move.l  d1,t65_catchup_debt
        addq.l  #1,t65_catchup_total
        subq.l  #1,d3

v7_next_apply:
        add.l   d3,d6
        move.l  d6,t31s_next_switch_vblank

t31s_stream_check_final:
        ; H264RGB2: the final payload is identified by the decoder's EOS, not
        ; by an expected frame number. If EOS arrived on the other empty slot
        ; while this BULK_RX was active, output_current_eos is also set.
        move.l  output_current_eos,d0
        tst.l   d0
        beq.w   t31s_stream_ok

        move.l  #V5_SPIN_TIMEOUT,d7
t31s_final_wait_pending:
        move.l  t31s_pending_valid,d0
        tst.l   d0
        beq.s   t31s_final_pending_done
        subq.l  #1,d7
        bne.w   t31s_final_wait_pending
        move.l  #3,v5_wait_stage
        bsr     v5_mark_wait_timeout
        bra.w   t31s_stream_fail
t31s_final_pending_done:
        move.l  #3,v5_wait_stage
        bsr     t31s_wait_frame_start
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        bne.w   t31s_stream_fail
        bsr     t30_display_end
        clr.l   t31s_display_started

t31s_stream_ok:
        move.l  t31s_vblank_counter,d0
        move.l  d0,d1
        sub.l   t31u_stage_start_vblank,d1
        add.l   d1,t31u_post_total
        tst.l   d1
        beq.w   t31u_post_no_nonzero
        addq.l  #1,t31u_post_nonzero
t31u_post_no_nonzero:
        cmp.l   t31u_post_max,d1
        bls.w   t31u_post_max_ok
        move.l  d1,t31u_post_max
t31u_post_max_ok:
        move.l  d0,t31u_last_stream_end_vblank

        moveq   #0,d0
        bra.w   t31s_stream_done

t31s_stream_fail:
        moveq   #1,d0

t31s_stream_done:
        movem.l (sp)+,d1-d7/a0-a6
        rts

; --------------------------------------------------------------------
; TEST61 HAM6 scanline encoder: TEST49-equivalent decisions, table accelerated.
; Input: A0=192 Y bytes, A2/A3=96 U/V bytes,
;        A1=current compact plane-0 output row.
; Output: consumes one 192-pixel luma row + one 96-sample chroma row and
;         advances A1 by 24 bytes.  Hardware HAM state starts each line at
;         COLOR00, therefore d6 starts at packed RGB $000 (black).
; --------------------------------------------------------------------
; --------------------------------------------------------------------
; TEST61 HAM6 scanline encoder: TEST49-equivalent adaptive edge reset.
; Expensive per-pixel squared-error comparisons are replaced by:
;   ham.bin   16 MB: exact winner code for targetRGB + heldRGB
;   edge.bin   2 MB: exact TEST49 edge-threshold bitset
;   state.bin 512 KB: exact next Denise held state for heldRGB + code
; The visible HAM code stream is intended to be bit-identical to TEST49.
; Input/output contract is unchanged from TEST49.
; --------------------------------------------------------------------
t44_convert_ham_row:
        movem.l d1-d7/a4-a6,-(sp)
        move.l  v9m_ham_lut_ptr,a5         ; external 16-MiB transition-table base
        moveq   #0,d6                       ; low=held RGB, high=previous target RGB
        clr.b   t56_edge_cooldown
        moveq   #23,d7                      ; 24 groups x 8 pixels = 192

t44_ham_group:
        moveq   #0,d1                       ; accum P4:P5:00:00
        moveq   #0,d2                       ; accum P0:P1:P2:P3
        ; HAM pixel pair 0: one shared I420 U/V sample for two Y pixels.
        moveq   #0,d3
        move.b  (a2)+,d3
        andi.w  #$00F0,d3
        moveq   #0,d0
        move.b  (a3)+,d0
        lsr.b   #4,d0
        or.w    d0,d3
        movea.l d3,a6                     ; preserve UV key across both pixels
        ; t51_p0_0: form 12-bit Y4/U4/V4 key and locate 64-byte target record.
        moveq   #0,d0
        move.b  (a0)+,d0
        andi.w  #$00F0,d0
        lsl.w   #4,d0
        move.l  a6,d3
        or.w    d3,d0
        lsl.l   #6,d0
        lea     t44_target_lut,a4
        adda.l  d0,a4
        moveq   #0,d3
        move.w  56(a4),d3                  ; current target $0RGB
