        bsr     newline

        lea     msg8a_late_promote,a1
        move.l  #msg8a_late_promote_end-msg8a_late_promote,d3
        bsr     print
        move.l  t8a_isr_late_promote,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31x_deadline_head,a1
        move.l  #msg31x_deadline_head_end-msg31x_deadline_head,d3
        bsr     print

        lea     msg31x_slack1,a1
        move.l  #msg31x_slack1_end-msg31x_slack1,d3
        bsr     print
        move.l  t31x_slack1,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31x_slack2,a1
        move.l  #msg31x_slack2_end-msg31x_slack2,d3
        bsr     print
        move.l  t31x_slack2,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31x_slack3,a1
        move.l  #msg31x_slack3_end-msg31x_slack3,d3
        bsr     print
        move.l  t31x_slack3plus,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31x_equal,a1
        move.l  #msg31x_equal_end-msg31x_equal,d3
        bsr     print
        move.l  t31x_at_target,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31x_past,a1
        move.l  #msg31x_past_end-msg31x_past,d3
        bsr     print
        move.l  t31x_past_target,d0
        bsr     print_hex32
        lea     msg31x_maxdelta,a1
        move.l  #msg31x_maxdelta_end-msg31x_maxdelta,d3
        bsr     print
        move.l  t31x_max_past_delta,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31x_miss1,a1
        move.l  #msg31x_miss1_end-msg31x_miss1,d3
        bsr     print
        move.l  t31x_miss1_frame,d0
        bsr     print_hex32
        lea     msg31x_sep_target,a1
        move.l  #msg31x_sep_target_end-msg31x_sep_target,d3
        bsr     print
        move.l  t31x_miss1_target,d0
        bsr     print_hex32
        lea     msg31x_sep_current,a1
        move.l  #msg31x_sep_current_end-msg31x_sep_current,d3
        bsr     print
        move.l  t31x_miss1_current,d0
        bsr     print_hex32
        lea     msg31x_sep_delta,a1
        move.l  #msg31x_sep_delta_end-msg31x_sep_delta,d3
        bsr     print
        move.l  t31x_miss1_delta,d0
        bsr     print_hex32
        bsr     newline

        lea     msg31x_miss2,a1
        move.l  #msg31x_miss2_end-msg31x_miss2,d3
        bsr     print
        move.l  t31x_miss2_frame,d0
        bsr     print_hex32
        lea     msg31x_sep_target,a1
        move.l  #msg31x_sep_target_end-msg31x_sep_target,d3
        bsr     print
        move.l  t31x_miss2_target,d0
        bsr     print_hex32
        lea     msg31x_sep_current,a1
        move.l  #msg31x_sep_current_end-msg31x_sep_current,d3
        bsr     print
        move.l  t31x_miss2_current,d0
        bsr     print_hex32
        lea     msg31x_sep_delta,a1
        move.l  #msg31x_sep_delta_end-msg31x_sep_delta,d3
        bsr     print
        move.l  t31x_miss2_delta,d0
        bsr     print_hex32
        bsr     newline

        lea     msg19_frame_ok,a1
        move.l  #msg19_frame_ok_end-msg19_frame_ok,d3
        bsr     print
        lea     msg_h264rgb2_frame_count,a1
        move.l  #msg_h264rgb2_frame_count_end-msg_h264rgb2_frame_count,d3
        bsr     print
        move.l  output_frame_total,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_v8c_rgb_count,a1
        move.l  #msg_v8c_rgb_count_end-msg_v8c_rgb_count,d3
        bsr     print
        move.l  t8c_display_frame_total,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_v8c_skip_count,a1
        move.l  #msg_v8c_skip_count_end-msg_v8c_skip_count,d3
        bsr     print
        move.l  t8c_skipped_frames,d0
        bsr     print_hex32
        bsr     newline

        lea     msg_v8c_late_skip_count,a1
        move.l  #msg_v8c_late_skip_count_end-msg_v8c_late_skip_count,d3
        bsr     print
        move.l  t8c_late_skipped_frames,d0
        bsr     print_hex32
        bsr     newline

        lea     msg30_play_done,a1
        move.l  #msg30_play_done_end-msg30_play_done,d3
        bsr     print

        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

h30_playback_fail:
        ; Legacy label retained for branch compatibility; TEST37 does not use
        ; a separate playback phase.
        lea     e30_playback,a1
        move.l  #e30_playback_end-e30_playback,d3
        bsr     print
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

; --------------------------------------------------------------------
; TEST37 legacy preload playback routine (NOT USED by the live streaming path).
; Retained from TEST31C only to keep the proven display helpers together.
; TEST37 live output goes through t31s_stream_current_frame above.
; --------------------------------------------------------------------
t30_playback:
        movem.l d1-d7/a0-a3/a6,-(sp)

        move.l  t30_chip_ptr,d0
        tst.l   d0
        bne.w   t30_play_have_chip

        jsr     v9i_alloc_chip_guarded
        tst.l   d0
        beq.w   t30_play_fail

t30_play_have_chip:
        clr.l   t30_play_index
        clr.l   t30_active_ptr

        ; Copy frame 0 before taking over RGB. t30_display_begin promotes
        ; this prepared buffer to ACTIVE exactly at the next raster frame.
        bsr     t30_copy_play_frame
        tst.l   d0
        bne.w   t30_play_fail
        bsr     t30_display_begin

t30_play_loop:
        ; First PAL refresh of ACTIVE is currently visible. At the next
        ; frame boundary reload ACTIVE so the same image gets a clean
        ; second refresh instead of Agnus continuing past the 20736 bytes.
        bsr     t31s_wait_frame_start
        bsr     t30_set_bpl_ptrs

        ; Was that the final decoded frame?
        move.l  t30_play_index,d0
        addq.l  #1,d0
        cmp.l   output_frame_total,d0
        bcc.w   t30_play_finish

        ; During ACTIVE's second refresh prepare the next frame in the
        ; alternate Chip-RAM buffer. t30_display_ptr is NEXT only; hardware
        ; continues to fetch from t30_active_ptr until the VBlank switch.
        move.l  d0,t30_play_index
        bsr     t30_copy_play_frame
        tst.l   d0
        bne.w   t30_play_abort_display

        ; Exactly at the next raster frame promote NEXT to ACTIVE and write
        ; all six bitplane pointers. No pointer changes occur in display.
        bsr     t31s_wait_frame_start
        move.l  t30_display_ptr,d0
        move.l  d0,t30_active_ptr
        bsr     t30_set_bpl_ptrs
        bra.w   t30_play_loop

t30_play_finish:
        ; Final frame already started its second PAL refresh above. Restore
        ; the system display only when that refresh has completed.
        bsr     t30_display_end
        moveq   #0,d0
        bra.w   t30_play_done

t30_play_abort_display:
        bsr     t30_display_end
t30_play_fail:
        moveq   #1,d0
t30_play_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Copy one stored 20736-byte planar frame from Fast-RAM to alternating
; Chip-RAM buffer. t30_display_ptr is NEXT; it is never used by Agnus until
; playback promotes it to t30_active_ptr at a raster frame boundary.
t30_copy_play_frame:
        movem.l d1-d3/d7/a0-a1,-(sp)

        move.l  t30_frames_ptr,a0
        cmpa.l  #0,a0
        beq.w   t30_copy_fail

        move.l  t30_play_index,d0
        cmp.l   output_frame_total,d0
        bcc.w   t30_copy_fail

        ; Source += frame_index * 48000.
        tst.l   d0
        beq.w   t30_copy_src_ready
        move.w  d0,d1
        subq.w  #1,d1
t30_copy_src_advance:
        adda.l  #T30_FRAME_BYTES,a0
        dbra    d1,t30_copy_src_advance

t30_copy_src_ready:
        move.l  t30_chip_ptr,a1
        cmpa.l  #0,a1
        beq.w   t30_copy_fail

        ; Odd frames use the second 20736-byte Chip-RAM buffer.
        move.l  t30_play_index,d0
        and.l   #1,d0
        beq.w   t30_copy_dst_ready
        adda.l  #T30_FRAME_BYTES,a1
t30_copy_dst_ready:
        move.l  a1,t30_display_ptr

        ; 20736 bytes = 5184 longwords.
        move.w  #5183,d7
t30_copy_long_loop:
        move.l  (a0)+,(a1)+
        dbra    d7,t30_copy_long_loop

        moveq   #0,d0
        bra.w   t30_copy_done
t30_copy_fail:
        moveq   #1,d0
t30_copy_done:
        movem.l (sp)+,d1-d3/d7/a0-a1
        rts

; Write ACTIVE six-bitplane pointers. High word first, then low.
; The caller only invokes this routine at a raster frame boundary.
t30_set_bpl_ptrs:
        movem.l d0-d1/a0,-(sp)
        lea     CUSTOM_BASE,a0

        move.l  t30_active_ptr,d1

        move.l  d1,d0
        swap    d0
        move.w  d0,BPL1PTH(a0)
        swap    d0
        move.w  d0,BPL1PTL(a0)

        move.l  d1,d0
        add.l   #T30_PLANE_BYTES,d0
        swap    d0
        move.w  d0,BPL1PTH+4(a0)
        swap    d0
        move.w  d0,BPL1PTL+4(a0)

        move.l  d1,d0
        add.l   #T30_PLANE2_OFF,d0
        swap    d0
        move.w  d0,BPL1PTH+8(a0)
        swap    d0
        move.w  d0,BPL1PTL+8(a0)

        move.l  d1,d0
        add.l   #T30_PLANE3_OFF,d0
        swap    d0
        move.w  d0,BPL1PTH+12(a0)
        swap    d0
        move.w  d0,BPL1PTL+12(a0)

        move.l  d1,d0
        add.l   #T30_PLANE4_OFF,d0
        swap    d0
        move.w  d0,BPL1PTH+16(a0)
        swap    d0
        move.w  d0,BPL1PTL+16(a0)

        move.l  d1,d0
        add.l   #T30_PLANE5_OFF,d0
        swap    d0
        move.w  d0,BPL1PTH+20(a0)
        swap    d0
        move.w  d0,BPL1PTL+20(a0)

        movem.l (sp)+,d0-d1/a0
        rts

; --------------------------------------------------------------------
; TEST61 VERTB interrupt server.
;
; The main streaming loop only changes t30_active_ptr.  Exec calls this
; server once per vertical blank and passes is_Data in A1. is_Data points
; directly at t30_active_ptr. The server can promote a prepared NEXT pointer
; at an absolute VBlank target, then reloads all six bitplane pointers every refresh.
; VERTB servers must return D0=0 (Z set) so the remaining server chain runs.
; --------------------------------------------------------------------
t31s_vblank_code:
        movem.l d1-d2/a0,-(sp)

        ; is_Data (A1) points at t30_active_ptr. Layout immediately after it:
        ; +4  vblank counter
        ; +8  pending pointer
        ; +12 switch-vblank target
        ; +16 pending-valid flag
        addq.l  #1,4(a1)

        ; If NEXT has been prepared and its absolute VBlank target is now due,
        ; promote it atomically before reloading the BPL pointers for this new
        ; refresh.  The main decoder can prepare NEXT at any point beforehand.
        move.l  16(a1),d2
        tst.l   d2
        beq.w   t31s_vblank_reload
        move.l  4(a1),d2
        cmp.l   12(a1),d2
        bcs.w   t31s_vblank_reload          ; current < target: not due yet
        beq.s   t8a_vblank_promote          ; exact target: normal case

        ; V9: publication race repair inherited from V8A. The main loop intentionally writes
        ; pending_ptr + switch_vblank first and pending_valid LAST. At 50 fps
        ; there is only one VBlank of headroom, so the exact target ISR can run
        ; between those stores. V8 used equality only and then left pending_valid
        ; set forever. If current > target, promote now on the first later VBlank.
        addq.l  #1,t8a_isr_late_promote

t8a_vblank_promote:
        move.l  8(a1),d1
        move.l  d1,(a1)
        clr.l   16(a1)

t31s_vblank_reload:
        move.l  (a1),d1
        tst.l   d1
        beq.w   t31s_vblank_done
        lea     CUSTOM_BASE,a0

        move.l  d1,d0
        swap    d0
        move.w  d0,BPL1PTH(a0)
        swap    d0
        move.w  d0,BPL1PTL(a0)

        move.l  d1,d0
        add.l   #T30_PLANE_BYTES,d0
        swap    d0
        move.w  d0,BPL1PTH+4(a0)
        swap    d0
        move.w  d0,BPL1PTL+4(a0)

        move.l  d1,d0
        add.l   #T30_PLANE2_OFF,d0
        swap    d0
        move.w  d0,BPL1PTH+8(a0)
        swap    d0
        move.w  d0,BPL1PTL+8(a0)

        move.l  d1,d0
        add.l   #T30_PLANE3_OFF,d0
        swap    d0
        move.w  d0,BPL1PTH+12(a0)
        swap    d0
        move.w  d0,BPL1PTL+12(a0)

        move.l  d1,d0
        add.l   #T30_PLANE4_OFF,d0
        swap    d0
        move.w  d0,BPL1PTH+16(a0)
        swap    d0
        move.w  d0,BPL1PTL+16(a0)

        move.l  d1,d0
        add.l   #T30_PLANE5_OFF,d0
        swap    d0
        move.w  d0,BPL1PTH+20(a0)
        swap    d0
        move.w  d0,BPL1PTL+20(a0)

t31s_vblank_done:
        movem.l (sp)+,d1-d2/a0
        moveq   #0,d0
        rts

; H264RGB6A: snapshot the first formerly-unbounded display wait that times out.
; v5_wait_stage must identify the current wait site before entry.
v5_mark_wait_timeout:
        movem.l d0-d2/a0,-(sp)
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        bne.s   v5_mark_wait_done
        move.l  v5_wait_stage,d0
        move.l  d0,v5_wait_timeout_stage
        move.l  t31s_pending_valid,v5_wait_pending
        move.l  t31s_switch_vblank,v5_wait_switch
        move.l  t30_active_ptr,v5_wait_active
        move.l  t30_display_ptr,v5_wait_display
        move.l  t31s_vblank_counter,v5_wait_vblank
        lea     CUSTOM_BASE,a0
        moveq   #0,d1
        move.w  VPOSR(a0),d1
        andi.w  #$0001,d1
        lsl.w   #8,d1
        moveq   #0,d2
        move.w  VHPOSR(a0),d2
        lsr.w   #8,d2
        or.w    d2,d1
        move.l  d1,v5_wait_raster
v5_mark_wait_done:
        movem.l (sp)+,d0-d2/a0
        rts

; Install the low-priority vertical-blank server once.
; Return D0=0 success.
t31s_install_vblank:
        movem.l d1/a1/a6,-(sp)
        move.l  t31s_vblank_installed,d0
        tst.l   d0
        bne.w   t31s_install_done
        move.l  4.w,a6
        moveq   #INTB_VERTB,d0
        lea     t31s_vblank_is,a1
        jsr     AddIntServer(a6)
        move.l  #1,t31s_vblank_installed
t31s_install_done:
        moveq   #0,d0
        movem.l (sp)+,d1/a1/a6
        rts

; Remove the server if it was installed. Safe on all cleanup paths.
t31s_remove_vblank:
        movem.l d1/a1/a6,-(sp)
        move.l  t31s_vblank_installed,d0
        tst.l   d0
        beq.w   t31s_remove_done
        move.l  4.w,a6
        moveq   #INTB_VERTB,d0
        lea     t31s_vblank_is,a1
        jsr     RemIntServer(a6)
        clr.l   t31s_vblank_installed
t31s_remove_done:
        moveq   #0,d0
        movem.l (sp)+,d1/a1/a6
        rts

; Wait for one *future* real hardware VBlank.
;
; TEST31F polled VPOSR V8 set->clear.  That detects a frame boundary, but the
; delay depends on where in the current raster the routine was entered.  A call
; made late in the frame can therefore return after only a few milliseconds.
;
; TEST33 instead snapshots the counter incremented by our Exec VERTB server and
; waits until that counter changes.  Therefore every call spans exactly one
; future vertical blank event (nominally 20 ms on PAL).  V7 schedules decoded frames with a rational 50-Hz phase accumulator; while a slow
; decoder simply causes the current ACTIVE frame to be repeated safely.
t31s_wait_frame_start:
        movem.l d0-d2,-(sp)
        move.l  t31s_vblank_counter,d0
        move.l  #V5_SPIN_TIMEOUT,d2

t31s_wait_vblank_counter:
        move.l  t31s_vblank_counter,d1
        cmp.l   d0,d1
        bne.s   t31s_wait_vblank_done
        subq.l  #1,d2
        bne.w   t31s_wait_vblank_counter
        bsr     v5_mark_wait_timeout
t31s_wait_vblank_done:
        movem.l (sp)+,d0-d2
        rts

t30_display_begin:
        movem.l d0-d2/a0-a1,-(sp)
        lea     CUSTOM_BASE,a0

        ; Stop the Workbench Copper and bitplane DMA during takeover.  The
        ; Exec VERTB chain remains active and will maintain our bitplane
        ; pointers independently of the main decoder loop.
        move.w  #$0080,DMACON(a0)      ; clear COPPER DMA
        move.w  #$0100,DMACON(a0)      ; clear BITPLANE DMA
        move.w  #$0000,BPLCON0(a0)
        ; V9 uses a compact 192x144 native fetch, centered in the PAL raster.
        move.w  #$5481,DIWSTRT(a0)
        move.w  #$E4C1,DIWSTOP(a0)
        move.w  #$0058,DDFSTRT(a0)
        move.w  #$00B0,DDFSTOP(a0)
        move.w  #$0000,BPLCON1(a0)
        move.w  #$0000,BPLCON2(a0)
        move.w  #$0000,BPL1MOD(a0)
        move.w  #$0000,BPL2MOD(a0)

        ; TEST61 HAM6 uses 16 direct base colors; modification pixels can then
        ; replace one 4-bit R/G/B component and reach the full 12-bit gamut.
        lea     COLOR00(a0),a1
        lea     t44_palette,a0
        moveq   #15,d1
t44_palette_loop:
        move.w  (a0)+,(a1)+
        dbra    d1,t44_palette_loop

        ; Publish prepared frame 0 before installing the VBlank server.
        move.l  t30_display_ptr,d0
        move.l  d0,t30_active_ptr
        ; TEST33 keeps the proven TEST31T server lifecycle unchanged. The
        ; timing clock starts here with the first RGB takeover.
        clr.l   t31s_vblank_counter
        clr.l   t31s_pending_ptr
        clr.l   t31s_switch_vblank
        clr.l   t31s_pending_valid
        clr.l   t31s_next_switch_vblank
        clr.l   v7_sched_accum
        bsr     t31s_install_vblank

        ; Wait for one real frame boundary. H264RGB6A bounds this wait.
        move.l  #5,v5_wait_stage
        bsr     t31s_wait_frame_start
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        bne.s   t30_display_begin_no_enable
        bsr     t30_set_bpl_ptrs
        lea     CUSTOM_BASE,a0
        move.w  #$6A00,BPLCON0(a0)      ; 6 planes + HAM + color, lowres
        move.w  #$8300,DMACON(a0)      ; set MASTER + BITPLANE DMA only
t30_display_begin_no_enable:
        ; If stage 5 timed out, takeover already stopped the Workbench Copper.
        ; Restore it here because display_started has not yet been published.
        move.l  v5_wait_timeout_stage,d0
        tst.l   d0
        beq.s   t30_display_begin_return
        bsr     t31s_remove_vblank
        lea     CUSTOM_BASE,a0
        move.w  #$0100,DMACON(a0)      ; clear BITPLANE DMA
        move.w  #$0000,BPLCON0(a0)
        move.w  #$0000,COPJMP1(a0)     ; restart system Copper list
        move.w  #$8080,DMACON(a0)      ; set COPPER DMA
t30_display_begin_return:
        movem.l (sp)+,d0-d2/a0-a1
        rts

t30_display_end:
        movem.l a0,-(sp)

        ; Restore at a frame boundary when possible. H264RGB6A bounds the wait;
        ; on timeout we still remove our server and restore the system display.
        move.l  #6,v5_wait_stage
        bsr     t31s_wait_frame_start
        bsr     t31s_remove_vblank
        lea     CUSTOM_BASE,a0
        move.w  #$0100,DMACON(a0)      ; clear BITPLANE DMA
        move.w  #$0000,BPLCON0(a0)
        move.w  #$0000,COPJMP1(a0)     ; restart system Copper list
        move.w  #$8080,DMACON(a0)      ; set COPPER DMA

        movem.l (sp)+,a0
        rts

; Safe to call from every TEST33 failure path.
t31s_display_abort_cleanup:
        movem.l d0,-(sp)
        move.l  t31s_display_started,d0
        tst.l   d0
        beq.w   t31s_cleanup_server_only
        bsr     t30_display_end
        clr.l   t31s_display_started
        bra.w   t31s_display_abort_done

t31s_cleanup_server_only:
        ; Covers a partial takeover as well: never leave our VERTB node linked.
        bsr     t31s_remove_vblank

t31s_display_abort_done:
        movem.l (sp)+,d0
        rts

h19_success_event:
        bsr     t31s_display_abort_cleanup
        lea     msg19_event_ok,a1
        move.l  #msg19_event_ok_end-msg19_event_ok,d3
        bsr     print
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

; H264RGB6A: print the snapshot from the first display-wait watchdog.
v5_print_wait_timeout:
        movem.l d0-d3/a1,-(sp)
        lea     e_v5_wait_timeout,a1
        move.l  #e_v5_wait_timeout_end-e_v5_wait_timeout,d3
        bsr     print
        move.l  v5_wait_timeout_stage,d0
        bsr     print_hex32
        lea     msg_v5_wait_state,a1
        move.l  #msg_v5_wait_state_end-msg_v5_wait_state,d3
        bsr     print
        move.l  v5_wait_pending,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  v5_wait_switch,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  v5_wait_vblank,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  v5_wait_raster,d0
        bsr     print_hex32
        lea     msg_v5_wait_ptrs,a1
        move.l  #msg_v5_wait_ptrs_end-msg_v5_wait_ptrs,d3
        bsr     print
        move.l  v5_wait_active,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  v5_wait_display,d0
        bsr     print_hex32
        bsr     newline
        movem.l (sp)+,d0-d3/a1
        rts

h19_v5_wait_fail:
        bsr     t31s_display_abort_cleanup
        bsr     v5_print_wait_timeout
        moveq   #1,d0
        movem.l (sp)+,d2-d7/a2-a3
        rts

h19_timeout:
        lea     e19_timeout,a1
