fail_connect_timeout:
        ; No CONNECT reply during this polling window.
        ; Shared memory is currently in DMA ownership because the polling
        ; loop called dma_pre_all before branching here.
        move.l  connect_retries,d0
        tst.l   d0
        beq.w   connect_retries_exhausted

        subq.l  #1,d0
        move.l  d0,connect_retries

        ; Re-acquire CPU view and first check whether the reply arrived
        ; exactly at the polling boundary.
        bsr     dma_post_all

        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        cmp.l   #8,d0
        bcc.w   connect_response_seen_a

        ; Re-assert the same remote event. Do NOT write another CONNECT and
        ; do NOT advance tx_pos again.
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32

        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,connect_retry_arm

        move.l  connect_retries,d0
        cmp.l   #1,d0
        beq.w   connect_retry_msg2

        lea     msg_retry3,a1
        move.l  #msg_retry3_end-msg_retry3,d3
        bsr     print
        bra.w   connect_retry_diag

connect_retry_msg2:
        lea     msg_retry2,a1
        move.l  #msg_retry2_end-msg_retry2,d3
        bsr     print

connect_retry_diag:
        lea     msg_retry_arm,a1
        move.l  #msg_retry_arm_end-msg_retry_arm,d3
        bsr     print
        move.l  connect_retry_arm,d0
        bsr     print_hex32
        bsr     newline

        ; Publish fired=1 to VideoCore.
        bsr     dma_pre_all

        ; Follow VCHIQ remote-event semantics: ring only if VC is armed.
        move.l  connect_retry_arm,d0
        tst.l   d0
        beq.w   connect_retry_no_bell

        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
        lea     msg_retry_bell,a1
        move.l  #msg_retry_bell_end-msg_retry_bell,d3
        bsr     print
        bra.w   connect_retry_wait

connect_retry_no_bell:
        lea     msg_retry_nobell,a1
        move.l  #msg_retry_nobell_end-msg_retry_nobell,d3
        bsr     print

connect_retry_wait:
        move.l  #POLL_COUNT,d7
        bra.w   connect_poll_loop_a

connect_retries_exhausted:
        ; Final failure. Re-acquire CPU ownership only for diagnostics.
        bsr     dma_post_all

        lea     e_connect_retry,a1
        move.l  #e_connect_retry_end-e_connect_retry,d3
        bsr     print

        lea     msg_diag_tx,a1
        move.l  #msg_diag_tx_end-msg_diag_tx,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        lea     msg_diag_arm,a1
        move.l  #msg_diag_arm_end-msg_diag_arm,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        lea     msg_diag_fired,a1
        move.l  #msg_diag_fired_end-msg_diag_fired,d3
        bsr     print
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        bsr     load_le32
        bsr     print_hex32
        bsr     newline

        bsr     dma_pre_all
        bra.w   close_prog

