v9d_attach_exit:
        jsr     v12e_free_mp4
        ; V10 LUTs are process-local even on the persistent-VCHIQ path.
        ; The VCHIQ resource/slot block itself stays resident by design.
        jsr     v9m_free_luts
        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

close_prog:
        move.l  t23_file_handle,d0
        beq.w   h23_close_done
        move.l  d0,d1
        move.l  a5,a6
        jsr     Close(a6)
        clr.l   t23_file_handle
h23_close_done:
        jsr     v12e_free_mp4
        jsr     v10b_stream_reset
        bsr     v9_cleanup_all
        jsr     v9m_free_luts

        move.l  a4,a6
        move.l  a5,a1
        jsr     CloseLibrary(a6)

exit_prog:
        moveq   #0,d0
        movem.l (sp)+,d2-d7/a2-a6
        rts

; --------------------------------------------------------------------
; Helpers
; --------------------------------------------------------------------

; A1=text, D3=len
; V13 quiet-output policy:
;   - ordinary diagnostic/status text is suppressed
;   - lines containing FEHLER or WARNUNG remain visible
;   - after such a prefix, following hex/status fragments remain visible
;     until the line-ending LF, so useful error values are not lost.
; Startup/help text uses print_force and bypasses this filter.
print:
        movem.l d0-d2/a0-a2/a6,-(sp)

        tst.l   h264rgb_print_tail
        bne.w   print_filtered_write

        move.l  a1,a0
        move.l  d3,d0
        tst.l   d0
        beq.w   print_filtered_done

print_filter_scan:
        move.b  (a0),d1

        ; "FEHLER"
        cmpi.b  #$46,d1
        bne.s   print_filter_check_warn
        cmpi.l  #6,d0
        bcs.w   print_filter_next
        cmpi.b  #$45,1(a0)
        bne.w   print_filter_next
        cmpi.b  #$48,2(a0)
        bne.w   print_filter_next
        cmpi.b  #$4C,3(a0)
        bne.w   print_filter_next
        cmpi.b  #$45,4(a0)
        bne.w   print_filter_next
        cmpi.b  #$52,5(a0)
        beq.w   print_filter_critical

print_filter_check_warn:
        ; "WARNUNG"
        cmpi.b  #$57,d1
        bne.w   print_filter_next
        cmpi.l  #7,d0
        bcs.w   print_filter_next
        cmpi.b  #$41,1(a0)
        bne.w   print_filter_next
        cmpi.b  #$52,2(a0)
        bne.w   print_filter_next
        cmpi.b  #$4E,3(a0)
        bne.w   print_filter_next
        cmpi.b  #$55,4(a0)
        bne.w   print_filter_next
        cmpi.b  #$4E,5(a0)
        bne.w   print_filter_next
        cmpi.b  #$47,6(a0)
        beq.w   print_filter_critical

print_filter_next:
        addq.l  #1,a0
        subq.l  #1,d0
        bne.w   print_filter_scan
        bra.w   print_filtered_done

print_filter_critical:
        move.l  #1,h264rgb_print_tail

print_filtered_write:
        ; Preserve the exact text pointer/length across DOS Write before
        ; inspecting the emitted fragment for its terminating LF.
        move.l  a1,-(sp)
        move.l  d3,-(sp)
        move.l  a1,d2
        move.l  h264rgb_output_handle,d1
        move.l  a5,a6
        jsr     Write(a6)
        move.l  (sp)+,d0
        move.l  (sp)+,a0

        ; End the critical continuation at LF. Prefixes without LF keep
        ; the flag set so print_hex32/status-name fragments stay visible.
print_filter_lf_scan:
        tst.l   d0
        beq.s   print_filtered_done
        cmpi.b  #10,(a0)+
        beq.s   print_filter_clear_tail
        subq.l  #1,d0
        bra.s   print_filter_lf_scan

print_filter_clear_tail:
        clr.l   h264rgb_print_tail

print_filtered_done:
        movem.l (sp)+,d0-d2/a0-a2/a6
        rts

; Unfiltered output for the intentionally small public UI.
print_force:
        movem.l d0-d2/a0-a1/a6,-(sp)
        move.l  a1,d2
        move.l  h264rgb_output_handle,d1
        move.l  a5,a6
        jsr     Write(a6)
        movem.l (sp)+,d0-d2/a0-a1/a6
        rts

; A1 = zero-terminated string. Used for the selected filename.
print_cstr_force:
        movem.l d0-d3/a0,-(sp)
        move.l  a1,a0
        moveq   #0,d3
print_cstr_force_len:
        tst.b   (a0)+
        beq.s   print_cstr_force_go
        addq.l  #1,d3
        bra.s   print_cstr_force_len
print_cstr_force_go:
        bsr     print_force
        movem.l (sp)+,d0-d3/a0
        rts

newline:
        lea     msg_nl,a1
        moveq   #1,d3
        bsr     print
        rts

bswap32:
        ror.w   #8,d0
        swap    d0
        ror.w   #8,d0
        rts

; A0=destination, D0=host value
store_le32:
        bsr     bswap32
        move.l  d0,(a0)
        rts

; A0=source, returns D0 host value
load_le32:
        move.l  (a0),d0
        bsr     bswap32
        rts

; A0=source little-endian u16, returns zero-extended D0
load_le16:
        moveq   #0,d0
        move.w  (a0),d0
        ror.w   #8,d0
        rts

; End current shared-memory DMA phase so CPU sees VideoCore writes.
dma_post_all:
        movem.l d0-d1/a0-a1/a6,-(sp)
        move.l  #DMA_MEM_SIZE,dma_len
        move.l  slot_ptr,a0
        lea     dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePostDMA(a6)
        movem.l (sp)+,d0-d1/a0-a1/a6
        rts

; Flush CPU changes and return shared memory to VideoCore DMA ownership.
dma_pre_all:
        movem.l d0-d1/a0-a1/a6,-(sp)
        move.l  #DMA_MEM_SIZE,dma_len
        move.l  slot_ptr,a0
        lea     dma_len,a1
        moveq   #0,d0
        move.l  a4,a6
        jsr     CachePreDMA(a6)
        movem.l (sp)+,d0-d1/a0-a1/a6
        rts

short_delay:
        movem.l d6,-(sp)
        move.l  #POLL_DELAY,d6
delay_loop:
        subq.l  #1,d6
        bne.w   delay_loop
        movem.l (sp)+,d6
        rts

print_hex32:
        movem.l d0-d3/d5-d7/a0-a2,-(sp)
        move.l  d0,d5
        lea     hexbuf,a1
        lea     hexdigits,a0
        moveq   #7,d7
hex_loop:
        rol.l   #4,d5
        move.l  d5,d0
        and.l   #$f,d0
        move.b  0(a0,d0.w),(a1)+
        dbra    d7,hex_loop

        lea     hexbuf,a1
        moveq   #8,d3
        bsr     print
        movem.l (sp)+,d0-d3/d5-d7/a0-a2
        rts


; --------------------------------------------------------------------
; H264RGB V10P - SPS geometry parser.
; Progressive Baseline/Main/Extended plus High Profile 8-bit 4:2:0.
; High-profile scaling-list syntax is consumed correctly before the common SPS fields.
; Interlaced streams and non-8-bit/non-4:2:0 High variants remain rejected cleanly.
; --------------------------------------------------------------------

; D0 <- one RBSP bit, v6_br_error set on EOF.
; V6C: deliberately uses only byte masks and simple integer arithmetic.
; This avoids the register-count shift sequence used by V6 while we isolate
; the 80000004 seen on real hardware in the new SPS parser.
v6_br_bit:
        movem.l d1-d3/a0-a1,-(sp)
        move.l  v6_br_ptr,a0
        move.l  v6_br_end,d3
        move.l  a0,d2
        cmp.l   d3,d2
        bcs.s   v6_br_bit_have
        move.l  #1,v6_br_error
        moveq   #0,d0
        bra.s   v6_br_bit_done
v6_br_bit_have:
        moveq   #0,d0
        move.b  (a0),d0
        move.l  v6_br_bitpos,d1
        and.l   #7,d1
        lea     v6_bit_masks,a1
        moveq   #0,d2
        move.b  0(a1,d1.w),d2
        and.b   d2,d0
        beq.s   v6_br_bit_zero
        moveq   #1,d0
        bra.s   v6_br_bit_advance
v6_br_bit_zero:
        moveq   #0,d0
v6_br_bit_advance:
        addq.l  #1,d1
        cmp.l   #8,d1
        bcs.s   v6_br_bit_store
        clr.l   d1
        addq.l  #1,a0
        move.l  a0,v6_br_ptr
v6_br_bit_store:
        move.l  d1,v6_br_bitpos
v6_br_bit_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

; D0 <- unsigned Exp-Golomb ue(v), v6_br_error on malformed input.
; V6B computes 2^N-1 by repeated doubling instead of a variable shift.
v6_br_ue:
        movem.l d1-d4,-(sp)
        clr.l   d1                      ; leading zero count
v6_br_ue_zero:
        bsr     v6_br_bit
        tst.l   v6_br_error
        bne.s   v6_br_ue_fail
        tst.l   d0
        bne.s   v6_br_ue_prefix_done
        addq.l  #1,d1
        cmp.l   #31,d1
        bhi.s   v6_br_ue_fail_set
        bra.s   v6_br_ue_zero
v6_br_ue_prefix_done:
        clr.l   d2                      ; prefix base = (1<<N)-1
        move.l  d1,d4
        tst.l   d4
        beq.s   v6_br_ue_prefix_ready
v6_br_ue_pow_loop:
        add.l   d2,d2
        addq.l  #1,d2
        subq.l  #1,d4
        bne.s   v6_br_ue_pow_loop
v6_br_ue_prefix_ready:
        clr.l   d3
        tst.l   d1
        beq.s   v6_br_ue_done_bits
        move.l  d1,d4
v6_br_ue_suffix:
        bsr     v6_br_bit
        tst.l   v6_br_error
        bne.s   v6_br_ue_fail
        add.l   d3,d3
        or.l    d0,d3
        subq.l  #1,d4
        bne.s   v6_br_ue_suffix
v6_br_ue_done_bits:
        move.l  d2,d0
        add.l   d3,d0
        bra.s   v6_br_ue_done
v6_br_ue_fail_set:
        move.l  #1,v6_br_error
v6_br_ue_fail:
        moveq   #0,d0
v6_br_ue_done:
        movem.l (sp)+,d1-d4
        rts

; Skip one signed Exp-Golomb value.
v6_br_skip_se:
        bsr     v6_br_ue
        rts

; V10P: signed Exp-Golomb value, needed to walk High-profile scaling lists.
; D0 <- se(v).  The underlying ue(v) reader owns malformed-input detection.
v10d_br_se:
        bsr     v6_br_ue
        move.l  d0,d1
        btst    #0,d1
        beq.s   v10d_br_se_even
        addq.l  #1,d0
        lsr.l   #1,d0
        rts
v10d_br_se_even:
        lsr.l   #1,d0
        neg.l   d0
        rts

; V10P: consume one seq_scaling_list() exactly as specified by H.264.
; D0 = list size (16 or 64).  Values are not needed by the decoder setup, but
; nextScale must be tracked because delta_scale is absent while nextScale == 0.
v10d_skip_scaling_list:
        movem.l d1-d4,-(sp)
        move.l  d0,d4                   ; entries remaining
        moveq   #8,d2                   ; lastScale
        moveq   #8,d3                   ; nextScale
v10d_scaling_loop:
        tst.l   d3
        beq.s   v10d_scaling_no_delta
        bsr     v10d_br_se              ; delta_scale
        tst.l   v6_br_error
        bne.s   v10d_scaling_done
        add.l   d2,d0
        and.l   #$000000FF,d0           ; (lastScale + delta + 256) mod 256
        move.l  d0,d3
v10d_scaling_no_delta:
        tst.l   d3
        beq.s   v10d_scaling_keep_last
        move.l  d3,d2
v10d_scaling_keep_last:
        subq.l  #1,d4
        bne.s   v10d_scaling_loop
v10d_scaling_done:
        movem.l (sp)+,d1-d4
        rts

v6_parse_sps_geometry:
        movem.l d1-d7/a0-a3,-(sp)
        lea     msg_v6a_parse_start,a1
        move.l  #msg_v6a_parse_start_end-msg_v6a_parse_start,d3
        bsr     print
        clr.l   v6_br_error
        clr.l   v6_crop_left
        clr.l   v6_crop_right
        clr.l   v6_crop_top
        clr.l   v6_crop_bottom
        clr.l   v10d_high_profile
        move.l  #1,v10d_chroma_format_idc ; common profiles are 4:2:0
        clr.l   v10d_bit_depth_luma_m8
        clr.l   v10d_bit_depth_chroma_m8
        clr.l   v10d_scaling_matrix_present

        ; Locate byte after Annex-B start code + NAL header.
        move.l  h264_sps_ptr,a0
        move.l  h264_sps_len,d7
        cmp.l   #8,d7
        bcs.w   v6_sps_fail
        cmp.b   #1,2(a0)
        beq.s   v6_sps_sc3
        cmp.b   #1,3(a0)
        beq.s   v6_sps_sc4
        bra.w   v6_sps_fail
v6_sps_sc3:
        addq.l  #4,a0                    ; 3-byte start + NAL header
        subq.l  #4,d7
        bra.s   v6_sps_payload
v6_sps_sc4:
        addq.l  #5,a0                    ; 4-byte start + NAL header
        subq.l  #5,d7
v6_sps_payload:
        ; Copy EBSP -> RBSP while removing 00 00 03 emulation-prevention bytes.
        lea     v6_sps_rbsp,a1
        clr.l   d6                       ; output count
        clr.l   d5                       ; consecutive raw zero count
v6_sps_unescape_loop:
        tst.l   d7
        beq.s   v6_sps_unescape_done
        moveq   #0,d0
        move.b  (a0)+,d0
        subq.l  #1,d7
        cmp.l   #2,d5
        bcs.s   v6_sps_not_epb
        cmp.b   #3,d0
        bne.s   v6_sps_not_epb
        clr.l   d5
        bra.s   v6_sps_unescape_loop
v6_sps_not_epb:
        cmp.l   #256,d6
        bcc.w   v6_sps_fail
        move.b  d0,(a1)+
        addq.l  #1,d6
        tst.b   d0
        bne.s   v6_sps_zero_reset
        addq.l  #1,d5
        bra.s   v6_sps_unescape_loop
v6_sps_zero_reset:
        clr.l   d5
        bra.s   v6_sps_unescape_loop
v6_sps_unescape_done:
        cmp.l   #4,d6
        bcs.w   v6_sps_fail
        move.l  d6,v6_sps_rbsp_len
        lea     msg_v6a_rbsp,a1
        move.l  #msg_v6a_rbsp_end-msg_v6a_rbsp,d3
        bsr     print
        move.l  v6_sps_rbsp_len,d0
        bsr     print_hex32
        bsr     newline

        lea     v6_sps_rbsp,a0
        moveq   #0,d0
        move.b  (a0),d0
        move.l  d0,v6_profile_idc
        cmp.l   #66,d0
        beq.s   v6_sps_profile_ok
        cmp.l   #77,d0
        beq.s   v6_sps_profile_ok
        cmp.l   #88,d0
        beq.s   v6_sps_profile_ok
        cmp.l   #100,d0                  ; High Profile
        bne.s   v10d_sps_profile_reject
        move.l  #1,v10d_high_profile
        bra.s   v6_sps_profile_ok
v10d_sps_profile_reject:
        lea     e_v6_profile,a1
        move.l  #e_v6_profile_end-e_v6_profile,d3
        bsr     print
        move.l  v6_profile_idc,d0
        bsr     print_hex32
        bsr     newline
        bra.w   v6_sps_fail_quiet
v6_sps_profile_ok:
        addq.l  #3,a0                    ; profile/constraints/level consumed
        move.l  a0,v6_br_ptr
        lea     v6_sps_rbsp,a1
        adda.l  d6,a1
        move.l  a1,v6_br_end
        clr.l   v6_br_bitpos

        bsr     v6_br_ue                 ; seq_parameter_set_id

        ; High Profile adds chroma/bit-depth/scaling syntax here.  V10P keeps
        ; the output path deliberately 8-bit I420, therefore High 4:2:0 8-bit
        ; is accepted while 4:2:2/4:4:4 and >8-bit streams are rejected.
        tst.l   v10d_high_profile
        beq.w   v10d_sps_after_high
        bsr     v6_br_ue                 ; chroma_format_idc
        move.l  d0,v10d_chroma_format_idc
        cmp.l   #1,d0                    ; 1 = 4:2:0
        bne.w   v10d_sps_high_format_fail
        bsr     v6_br_ue                 ; bit_depth_luma_minus8
        move.l  d0,v10d_bit_depth_luma_m8
        tst.l   d0
        bne.w   v10d_sps_high_format_fail
        bsr     v6_br_ue                 ; bit_depth_chroma_minus8
        move.l  d0,v10d_bit_depth_chroma_m8
        tst.l   d0
        bne.w   v10d_sps_high_format_fail
        bsr     v6_br_bit                ; qpprime_y_zero_transform_bypass_flag
        bsr     v6_br_bit                ; seq_scaling_matrix_present_flag
        move.l  d0,v10d_scaling_matrix_present
        tst.l   d0
        beq.s   v10d_sps_high_done
        moveq   #0,d3                    ; scaling-list index 0..7 for 4:2:0
v10d_sps_scaling_loop:
        bsr     v6_br_bit                ; seq_scaling_list_present_flag[i]
        tst.l   v6_br_error
        bne.w   v6_sps_fail
        tst.l   d0
        beq.s   v10d_sps_scaling_next
        cmp.l   #6,d3
        bcs.s   v10d_sps_scaling_16
        moveq   #64,d0
        bra.s   v10d_sps_scaling_call
v10d_sps_scaling_16:
        moveq   #16,d0
v10d_sps_scaling_call:
        bsr     v10d_skip_scaling_list
        tst.l   v6_br_error
        bne.w   v6_sps_fail
v10d_sps_scaling_next:
        addq.l  #1,d3
        cmp.l   #8,d3
        bcs.s   v10d_sps_scaling_loop
v10d_sps_high_done:
        lea     msg_v10d_high_ok,a1
        move.l  #msg_v10d_high_ok_end-msg_v10d_high_ok,d3
        bsr     print
v10d_sps_after_high:
        bsr     v6_br_ue                 ; log2_max_frame_num_minus4
        bsr     v6_br_ue                 ; pic_order_cnt_type
        move.l  d0,d4
        cmp.l   #0,d4
        bne.s   v6_sps_poc_not0
        bsr     v6_br_ue                 ; log2_max_pic_order_cnt_lsb_minus4
        bra.s   v6_sps_poc_done
v6_sps_poc_not0:
        cmp.l   #1,d4
        bne.s   v6_sps_poc_done
        bsr     v6_br_bit                ; delta_pic_order_always_zero_flag
        bsr     v6_br_skip_se            ; offset_for_non_ref_pic
        bsr     v6_br_skip_se            ; offset_for_top_to_bottom_field
        bsr     v6_br_ue                 ; num_ref_frames_in_pic_order_cnt_cycle
        move.l  d0,d3
        tst.l   d3
        beq.s   v6_sps_poc_done
v6_sps_poc_loop:
        bsr     v6_br_skip_se
        subq.l  #1,d3
        bne.s   v6_sps_poc_loop
v6_sps_poc_done:
        bsr     v6_br_ue                 ; max_num_ref_frames
        move.l  d0,v10j_max_num_ref_frames
        bsr     v6_br_bit                ; gaps_in_frame_num_value_allowed_flag
        bsr     v6_br_ue                 ; pic_width_in_mbs_minus1
        move.l  d0,d5
        bsr     v6_br_ue                 ; pic_height_in_map_units_minus1
        move.l  d0,d6
        bsr     v6_br_bit                ; frame_mbs_only_flag
        move.l  d0,v6_frame_mbs_only
        tst.l   d0
        bne.s   v6_sps_progressive
        lea     e_v6_interlaced,a1
        move.l  #e_v6_interlaced_end-e_v6_interlaced,d3
        bsr     print
        bra.w   v6_sps_fail_quiet
v6_sps_progressive:
        bsr     v6_br_bit                ; direct_8x8_inference_flag
        bsr     v6_br_bit                ; frame_cropping_flag
        tst.l   d0
        beq.s   v6_sps_crop_done
        bsr     v6_br_ue
        move.l  d0,v6_crop_left
        bsr     v6_br_ue
        move.l  d0,v6_crop_right
        bsr     v6_br_ue
        move.l  d0,v6_crop_top
        bsr     v6_br_ue
        move.l  d0,v6_crop_bottom
v6_sps_crop_done:
        jsr     v7_parse_vui_timing
        lea     msg_v6a_syntax,a1
        move.l  #msg_v6a_syntax_end-msg_v6a_syntax,d3
        bsr     print
        tst.l   v6_br_error
        bne.w   v6_sps_fail

        ; Baseline/Main/Extended are 4:2:0. Progressive crop units are 2x2.
        addq.l  #1,d5
        lsl.l   #4,d5
        move.l  d5,v6_src_coded_w
        addq.l  #1,d6
        lsl.l   #4,d6
        move.l  d6,v6_src_coded_h

        move.l  v6_crop_left,d0
        lsl.l   #1,d0
        move.l  d0,v6_src_crop_x
        move.l  v6_crop_top,d0
        lsl.l   #1,d0
        move.l  d0,v6_src_crop_y

        move.l  v6_crop_left,d0
        add.l   v6_crop_right,d0
        lsl.l   #1,d0
        move.l  d5,d1
        sub.l   d0,d1
        move.l  d1,v6_src_visible_w
        move.l  v6_crop_top,d0
        add.l   v6_crop_bottom,d0
        lsl.l   #1,d0
        move.l  d6,d1
        sub.l   d0,d1
        move.l  d1,v6_src_visible_h

        ; MMAL host convention: stride width aligned to 32, height to 16.
        move.l  d5,d0
        add.l   #31,d0
        and.l   #$FFFFFFE0,d0
        move.l  d0,v6_src_aligned_w
        move.l  d6,d0
        add.l   #15,d0
        and.l   #$FFFFFFF0,d0
        move.l  d0,v6_src_aligned_h

        move.l  v6_src_visible_w,d0
        cmp.l   #16,d0
        bcs.w   v6_sps_range_fail
        cmp.l   #V6_MAX_SRC_W,d0
        bhi.w   v6_sps_range_fail
        btst    #0,d0
        bne.w   v6_sps_range_fail
        move.l  v6_src_visible_h,d0
        cmp.l   #16,d0
        bcs.w   v6_sps_range_fail
        cmp.l   #V6_MAX_SRC_H,d0
        bhi.w   v6_sps_range_fail
        btst    #0,d0
        bne.w   v6_sps_range_fail

        lea     msg_v6_geom,a1
        move.l  #msg_v6_geom_end-msg_v6_geom,d3
        bsr     print
        move.l  v6_src_visible_w,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  v6_src_visible_h,d0
        bsr     print_hex32
        lea     msg_v6_coded,a1
        move.l  #msg_v6_coded_end-msg_v6_coded,d3
        bsr     print
        move.l  v6_src_aligned_w,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  v6_src_aligned_h,d0
        bsr     print_hex32
        bsr     newline
        moveq   #0,d0
        bra.w   v6_sps_done

v10d_sps_high_format_fail:
        lea     e_v10d_high_format,a1
        move.l  #e_v10d_high_format_end-e_v10d_high_format,d3
        bsr     print
        move.l  v10d_chroma_format_idc,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  v10d_bit_depth_luma_m8,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  v10d_bit_depth_chroma_m8,d0
        bsr     print_hex32
        bsr     newline
        bra.w   v6_sps_fail_quiet

v6_sps_range_fail:
        lea     e_v6_range,a1
        move.l  #e_v6_range_end-e_v6_range,d3
        bsr     print
        move.l  v6_src_visible_w,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  v6_src_visible_h,d0
        bsr     print_hex32
        bsr     newline
        bra.s   v6_sps_fail_quiet
v6_sps_fail:
        lea     e_v6_sps,a1
        move.l  #e_v6_sps_end-e_v6_sps,d3
        bsr     print
v6_sps_fail_quiet:
        moveq   #1,d0
v6_sps_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Prepare scale maps from actual MMAL output crop geometry.
v6_scale_prepare:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  output_width_saved,d0
        tst.l   d0
        beq.w   v6_scale_prepare_fail
        cmp.l   #V6_MAX_SRC_W,d0
        bhi.w   v6_scale_prepare_fail
        move.l  output_height_saved,d0
        tst.l   d0
        beq.w   v6_scale_prepare_fail
        ; V12D: a visible 1080-line frame is MMAL-aligned to 1088 lines.
        cmp.l   #V12_MAX_ALIGNED_H,d0
        bhi.w   v6_scale_prepare_fail
        move.l  output_crop_w_saved,d5
        move.l  output_crop_h_saved,d6
        tst.l   d5
        beq.w   v6_scale_prepare_fail
        tst.l   d6
        beq.w   v6_scale_prepare_fail

        ; Fit whole source crop inside 192x144 while preserving aspect ratio.
        move.l  d5,d0
        mulu.w  #144,d0
        move.l  d6,d1
        mulu.w  #192,d1
        cmp.l   d1,d0
        bcs.s   v6_scale_tall
        move.l  #192,v6_dst_w
        move.l  d6,d0
        mulu.w  #192,d0
        divu.w  d5,d0
        and.l   #$0000FFFF,d0
        and.l   #$FFFFFFFE,d0
        cmp.l   #2,d0
        bcc.s   v6_scale_wide_h_ok
        moveq   #2,d0
v6_scale_wide_h_ok:
        move.l  d0,v6_dst_h
        bra.s   v6_scale_dims_done
v6_scale_tall:
        move.l  #144,v6_dst_h
        move.l  d5,d0
        mulu.w  #144,d0
        divu.w  d6,d0
        and.l   #$0000FFFF,d0
        and.l   #$FFFFFFFE,d0
        cmp.l   #2,d0
        bcc.s   v6_scale_tall_w_ok
        moveq   #2,d0
v6_scale_tall_w_ok:
        move.l  d0,v6_dst_w
v6_scale_dims_done:
        move.l  #192,d0
        sub.l   v6_dst_w,d0
        lsr.l   #1,d0
        and.l   #$FFFFFFFE,d0
        move.l  d0,v6_dst_x
        move.l  #144,d0
        sub.l   v6_dst_h,d0
        lsr.l   #1,d0
        and.l   #$FFFFFFFE,d0
        move.l  d0,v6_dst_y

        ; Y/luma X map: 0xffff denotes black bar.
        lea     v6_xmap_y,a0
        move.w  #191,d7
v6_xmap_y_clear:
        move.w  #$FFFF,(a0)+
        dbra    d7,v6_xmap_y_clear
        move.l  v6_dst_w,d7
        subq.l  #1,d7
        lea     v6_xmap_y,a0
        move.l  v6_dst_x,d0
        add.l   d0,d0
        adda.l  d0,a0
        clr.l   d4
v6_xmap_y_loop:
        move.l  d4,d0
        mulu.w  d5,d0
        move.l  v6_dst_w,d1
        divu.w  d1,d0
        and.l   #$0000FFFF,d0
        add.l   output_crop_x_saved,d0
        move.w  d0,(a0)+
        addq.l  #1,d4
        dbra    d7,v6_xmap_y_loop

        ; Chroma X map.
        lea     v6_xmap_c,a0
        move.w  #95,d7
v6_xmap_c_clear:
        move.w  #$FFFF,(a0)+
        dbra    d7,v6_xmap_c_clear
        move.l  v6_dst_w,d2
        lsr.l   #1,d2
        move.l  d5,d3
        lsr.l   #1,d3
        move.l  v6_dst_x,d0
        lsr.l   #1,d0
        lea     v6_xmap_c,a0
        add.l   d0,d0
        adda.l  d0,a0
        move.l  d2,d7
        subq.l  #1,d7
        clr.l   d4
v6_xmap_c_loop:
        move.l  d4,d0
        mulu.w  d3,d0
        divu.w  d2,d0
        and.l   #$0000FFFF,d0
        move.l  output_crop_x_saved,d1
        lsr.l   #1,d1
        add.l   d1,d0
        move.w  d0,(a0)+
        addq.l  #1,d4
        dbra    d7,v6_xmap_c_loop

        ; Luma Y map.
        lea     v6_ymap_y,a0
        move.w  #143,d7
v6_ymap_y_clear:
        move.w  #$FFFF,(a0)+
        dbra    d7,v6_ymap_y_clear
        move.l  v6_dst_y,d0
        lea     v6_ymap_y,a0
        add.l   d0,d0
        adda.l  d0,a0
        move.l  v6_dst_h,d7
        subq.l  #1,d7
        clr.l   d4
v6_ymap_y_loop:
        move.l  d4,d0
        mulu.w  d6,d0
        move.l  v6_dst_h,d1
        divu.w  d1,d0
        and.l   #$0000FFFF,d0
        add.l   output_crop_y_saved,d0
        move.w  d0,(a0)+
        addq.l  #1,d4
        dbra    d7,v6_ymap_y_loop

        ; Chroma Y map.
        lea     v6_ymap_c,a0
        move.w  #71,d7
v6_ymap_c_clear:
        move.w  #$FFFF,(a0)+
        dbra    d7,v6_ymap_c_clear
        move.l  v6_dst_h,d2
        lsr.l   #1,d2
        move.l  d6,d3
        lsr.l   #1,d3
        move.l  v6_dst_y,d0
        lsr.l   #1,d0
        lea     v6_ymap_c,a0
        add.l   d0,d0
        adda.l  d0,a0
        move.l  d2,d7
        subq.l  #1,d7
        clr.l   d4
v6_ymap_c_loop:
        move.l  d4,d0
        mulu.w  d3,d0
        divu.w  d2,d0
        and.l   #$0000FFFF,d0
        move.l  output_crop_y_saved,d1
        lsr.l   #1,d1
        add.l   d1,d0
        move.w  d0,(a0)+
        addq.l  #1,d4
        dbra    d7,v6_ymap_c_loop

        lea     msg_v6_scale,a1
        move.l  #msg_v6_scale_end-msg_v6_scale,d3
        bsr     print
        move.l  output_crop_w_saved,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  output_crop_h_saved,d0
        bsr     print_hex32
        lea     msg_v6_arrow,a1
        move.l  #msg_v6_arrow_end-msg_v6_arrow,d3
        bsr     print
        move.l  v6_dst_w,d0
        bsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        bsr     print
        move.l  v6_dst_h,d0
        bsr     print_hex32
        lea     msg_v6_offset,a1
        move.l  #msg_v6_offset_end-msg_v6_offset,d3
        bsr     print
        move.l  v6_dst_x,d0
        bsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        bsr     print
        move.l  v6_dst_y,d0
        bsr     print_hex32
        bsr     newline
        moveq   #0,d0
        bra.s   v6_scale_prepare_done
v6_scale_prepare_fail:
        lea     e_v6_scale,a1
        move.l  #e_v6_scale_end-e_v6_scale,d3
        bsr     print
        moveq   #1,d0
v6_scale_prepare_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Build one 192x144 scaled I420 image row-pair at a time and immediately
; feed the unchanged HAM6 row encoder. Input: A1 = HAM plane-0 row pointer.
v6_scale_frame_to_ham:
        movem.l d1-d7/a0/a2-a6,-(sp)
        move.l  a1,v6_ham_row_ptr
        move.l  output_data_ptr,a4         ; Y base
        move.l  output_width_saved,d0
        move.l  output_height_saved,d1
        mulu.w  d1,d0
        move.l  a4,a5
        adda.l  d0,a5                      ; U base
        move.l  output_width_saved,d2
        lsr.l   #1,d2                      ; chroma stride
        move.l  output_height_saved,d3
        lsr.l   #1,d3
        move.l  d2,d0
        mulu.w  d3,d0
        move.l  a5,a6
        adda.l  d0,a6                      ; V base

        clr.l   d7                         ; output chroma row 0..71
v6_scale_pair_loop:
        ; Luma row 0.
        lea     v6_yrow0,a1
        lea     v6_xmap_y,a2
        move.l  d7,d0
        add.l   d0,d0                      ; luma output row = pair*2
        lea     v6_ymap_y,a0
        lea     v6_ymap_y,a0
        move.l  d7,d0
        lsl.l   #2,d0
        adda.l  d0,a0
        moveq   #0,d1
        move.w  (a0),d1
        bsr     v6_fill_luma_row

        ; Luma row 1.
        lea     v6_yrow1,a1
        lea     v6_xmap_y,a2
        moveq   #0,d1
        move.w  2(a0),d1
        bsr     v6_fill_luma_row

        ; Chroma row shared by the two luma rows.
        lea     v6_urow,a1
        lea     v6_vrow,a3
        lea     v6_xmap_c,a2
        lea     v6_ymap_c,a0
        move.l  d7,d0
        add.l   d0,d0
        adda.l  d0,a0
        moveq   #0,d1
        move.w  (a0),d1
        bsr     v6_fill_chroma_row

        move.l  v6_ham_row_ptr,a1
        lea     v6_yrow0,a0
        lea     v6_urow,a2
        lea     v6_vrow,a3
        bsr     t44_convert_ham_row
        move.l  a1,v6_ham_row_ptr
        lea     v6_yrow1,a0
        lea     v6_urow,a2
        lea     v6_vrow,a3
        bsr     t44_convert_ham_row
        move.l  a1,v6_ham_row_ptr

        addq.l  #1,d7
        cmp.l   #72,d7
        bcs.w   v6_scale_pair_loop
        moveq   #0,d0
        movem.l (sp)+,d1-d7/a0/a2-a6
        rts

; A1=dest 192 bytes, A2=xmap, D1=source y row or $ffff. A4=Y base.
v6_fill_luma_row:
        movem.l d0-d7/a0/a2,-(sp)
        cmp.w   #$FFFF,d1
        bne.s   v6_fill_luma_have_y
        moveq   #0,d0
        move.w  #191,d7
v6_fill_luma_black:
        move.b  d0,(a1)+
        dbra    d7,v6_fill_luma_black
        bra.s   v6_fill_luma_done
v6_fill_luma_have_y:
        move.l  output_width_saved,d0
        mulu.w  d1,d0
        move.l  a4,a0
        adda.l  d0,a0
        move.w  #191,d7
v6_fill_luma_x:
        moveq   #0,d0
        move.w  (a2)+,d0
        cmp.w   #$FFFF,d0
        bne.s   v6_fill_luma_src
        clr.b   (a1)+
        bra.s   v6_fill_luma_next
v6_fill_luma_src:
        move.b  0(a0,d0.w),(a1)+
v6_fill_luma_next:
        dbra    d7,v6_fill_luma_x
v6_fill_luma_done:
        movem.l (sp)+,d0-d7/a0/a2
        rts

; A1=U dest 96, A3=V dest 96, A2=xmap, D1=source chroma row or ffff.
; A5=U base, A6=V base, D2=chroma stride.
v6_fill_chroma_row:
        movem.l d0-d7/a0/a2/a4,-(sp)
        cmp.w   #$FFFF,d1
        bne.s   v6_fill_chroma_have_y
        moveq   #$FFFFFF80,d0
        move.w  #95,d7
v6_fill_chroma_neutral:
        move.b  d0,(a1)+
        move.b  d0,(a3)+
        dbra    d7,v6_fill_chroma_neutral
        bra.s   v6_fill_chroma_done
v6_fill_chroma_have_y:
        move.l  d2,d0
        mulu.w  d1,d0
        move.l  a5,a0
        adda.l  d0,a0
        move.l  a6,a4
        adda.l  d0,a4
        move.w  #95,d7
v6_fill_chroma_x:
        moveq   #0,d0
        move.w  (a2)+,d0
        cmp.w   #$FFFF,d0
        bne.s   v6_fill_chroma_src
        move.b  #$80,(a1)+
        move.b  #$80,(a3)+
        bra.s   v6_fill_chroma_next
v6_fill_chroma_src:
        move.b  0(a0,d0.w),(a1)+
        move.b  0(a4,d0.w),(a3)+
v6_fill_chroma_next:
        dbra    d7,v6_fill_chroma_x
v6_fill_chroma_done:
        movem.l (sp)+,d0-d7/a0/a2/a4
        rts

