; --------------------------------------------------------------------
; H264RGB7 timing helper code is placed here so the established early
; PC-relative data layout from H264RGB6C remains within 68000 ranges.
; All entry calls are absolute JSRs.
; --------------------------------------------------------------------
        even
; D1 = bit count 1..32, D0 <- unsigned bits from RBSP.
; Uses the conservative V6C single-bit reader so the real-hardware fix stays intact.
        section code,code
v7_br_bits:
        movem.l d2-d4,-(sp)
        clr.l   d2
        move.l  d1,d4
        tst.l   d4
        beq.s   v7_br_bits_done_value
v7_br_bits_loop:
        jsr     v6_br_bit
        tst.l   v6_br_error
        bne.s   v7_br_bits_fail
        add.l   d2,d2
        or.l    d0,d2
        subq.l  #1,d4
        bne.s   v7_br_bits_loop
v7_br_bits_done_value:
        move.l  d2,d0
        bra.s   v7_br_bits_done
v7_br_bits_fail:
        moveq   #0,d0
v7_br_bits_done:
        movem.l (sp)+,d2-d4
        rts

; Parse only the VUI fields up to timing_info.  The bit reader is already
; positioned immediately after frame_cropping_flag/crop offsets.
; Geometry registers D5/D6 are deliberately untouched.
v7_parse_vui_timing:
        movem.l d1-d4,-(sp)
        clr.l   v7_vui_present
        clr.l   v7_timing_present
        clr.l   v7_fixed_frame_rate
        clr.l   v7_num_units_in_tick
        clr.l   v7_time_scale

        jsr     v6_br_bit                    ; vui_parameters_present_flag
        tst.l   v6_br_error
        bne.w   v7_vui_done
        tst.l   d0
        beq.w   v7_vui_done
        move.l  #1,v7_vui_present

        jsr     v6_br_bit                    ; aspect_ratio_info_present_flag
        tst.l   d0
        beq.s   v7_vui_no_aspect
        moveq   #8,d1
        jsr     v7_br_bits                   ; aspect_ratio_idc
        cmp.l   #255,d0
        bne.s   v7_vui_no_aspect
        moveq   #16,d1
        jsr     v7_br_bits                   ; sar_width
        moveq   #16,d1
        jsr     v7_br_bits                   ; sar_height
v7_vui_no_aspect:
        jsr     v6_br_bit                    ; overscan_info_present_flag
        tst.l   d0
        beq.s   v7_vui_no_overscan
        jsr     v6_br_bit                    ; overscan_appropriate_flag
v7_vui_no_overscan:
        jsr     v6_br_bit                    ; video_signal_type_present_flag
        tst.l   d0
        beq.s   v7_vui_no_signal
        moveq   #3,d1
        jsr     v7_br_bits                   ; video_format
        jsr     v6_br_bit                    ; video_full_range_flag
        jsr     v6_br_bit                    ; colour_description_present_flag
        tst.l   d0
        beq.s   v7_vui_no_signal
        moveq   #8,d1
        jsr     v7_br_bits                   ; colour_primaries
        moveq   #8,d1
        jsr     v7_br_bits                   ; transfer_characteristics
        moveq   #8,d1
        jsr     v7_br_bits                   ; matrix_coefficients
v7_vui_no_signal:
        jsr     v6_br_bit                    ; chroma_loc_info_present_flag
        tst.l   d0
        beq.s   v7_vui_no_chroma_loc
        jsr     v6_br_ue                     ; chroma_sample_loc_type_top_field
        jsr     v6_br_ue                     ; chroma_sample_loc_type_bottom_field
v7_vui_no_chroma_loc:
        jsr     v6_br_bit                    ; timing_info_present_flag
        tst.l   d0
        beq.s   v7_vui_done
        move.l  #1,v7_timing_present
        moveq   #32,d1
        jsr     v7_br_bits
        move.l  d0,v7_num_units_in_tick
        moveq   #32,d1
        jsr     v7_br_bits
        move.l  d0,v7_time_scale
        jsr     v6_br_bit                    ; fixed_frame_rate_flag
        move.l  d0,v7_fixed_frame_rate
v7_vui_done:
        movem.l (sp)+,d1-d4
        rts

; Convert H.264 VUI timing to an MMAL rational fps and a 50-Hz
; display-step fraction. H.264 nominal progressive frame rate is
; time_scale / (2 * num_units_in_tick).
; V9 accepts 1..50 fps; source rates >=25 fps use a fixed 25-fps RGB timeline, with higher rates rationally decimated. Common timing values fit unsigned 16-bit
; DIVU operands (e.g. 24, 25, 30, 24000/1001, 30000/1001).
v7_setup_timing:
        movem.l d1-d4,-(sp)
        clr.l   t8c_cap25_mode
        clr.l   t8c_select_step
        clr.l   t8c_select_accum
        moveq   #1,d4                       ; default error
        move.l  v7_timing_present,d0
        tst.l   d0
        bne.s   v7_timing_have
        lea     e_v7_no_timing,a1
        move.l  #e_v7_no_timing_end-e_v7_no_timing,d3
        jsr     print
        bra.w   v7_timing_done
v7_timing_have:
        move.l  v7_num_units_in_tick,d1
        tst.l   d1
        beq.w   v7_timing_bad
        cmp.l   #32767,d1
        bhi.w   v7_timing_bad
        add.l   d1,d1                       ; fps denominator
        move.l  d1,v7_fps_den
        move.l  v7_time_scale,d2
        tst.l   d2
        beq.w   v7_timing_bad
        cmp.l   #65535,d2
        bhi.w   v7_timing_bad
        move.l  d2,v7_fps_num

        ; Accept nominal progressive rates from 1 through 50 fps.
        cmp.l   d1,d2
        bcs.w   v7_timing_range
        move.l  d1,d0
        mulu.w  #50,d0
        cmp.l   d0,d2
        bhi.w   v7_timing_range

        ; Native scheduler is retained for source rates below 25 fps.
        move.l  d1,d0
        mulu.w  #50,d0
        move.l  d0,v7_sched_step_num
        move.l  d2,v7_sched_step_den
        clr.l   v7_sched_accum

        ; V9: RGB/HAM6 uses a fixed 25-fps real-time grid for sources at or
        ; above 25 fps. MMAL still decodes every frame. For a source above 25
        ; fps, a rational accumulator selects the source
        ; pictures for the 25-fps RGB timeline. The first source picture is
        ; selected by initializing accum = fps_num - 25*fps_den.
        move.l  d1,d0
        mulu.w  #25,d0                     ; d0 = 25 * fps_den
        cmp.l   d0,d2
        bcs.s   v8c_timing_mode_ready      ; <25 fps: preserve native source timing
        move.l  #1,t8c_cap25_mode
        move.l  d0,t8c_select_step
        move.l  d2,d3
        sub.l   d0,d3
        move.l  d3,t8c_select_accum
        move.l  #2,v7_sched_step_num       ; fixed 25 fps RGB = 2 PAL VBlanks
        move.l  #1,v7_sched_step_den
        clr.l   v7_sched_accum
v8c_timing_mode_ready:

        lea     msg_v7_fps,a1
        move.l  #msg_v7_fps_end-msg_v7_fps,d3
        jsr     print
        move.l  v7_fps_num,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v7_fps_den,d0
        jsr     print_hex32
        lea     msg_v7_vui_raw,a1
        move.l  #msg_v7_vui_raw_end-msg_v7_vui_raw,d3
        jsr     print
        move.l  v7_num_units_in_tick,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v7_time_scale,d0
        jsr     print_hex32
        lea     msg_v7_fixed,a1
        move.l  #msg_v7_fixed_end-msg_v7_fixed,d3
        jsr     print
        move.l  v7_fixed_frame_rate,d0
        jsr     print_hex32
        jsr     newline
        move.l  t8c_cap25_mode,d0
        tst.l   d0
        beq.s   v8c_timing_no_mode_msg
        lea     msg_v8c_cap25,a1
        move.l  #msg_v8c_cap25_end-msg_v8c_cap25,d3
        jsr     print
v8c_timing_no_mode_msg:
        moveq   #0,d4
        bra.s   v7_timing_done

v7_timing_bad:
        lea     e_v7_bad_timing,a1
        move.l  #e_v7_bad_timing_end-e_v7_bad_timing,d3
        jsr     print
        bra.s   v7_timing_done
v7_timing_range:
        lea     e_v7_fps_range,a1
        move.l  #e_v7_fps_range_end-e_v7_fps_range,d3
        jsr     print
        move.l  v7_fps_num,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v7_fps_den,d0
        jsr     print_hex32
        jsr     newline
v7_timing_done:
        move.l  d4,d0
        movem.l (sp)+,d1-d4
        rts

; D0 <- next nominal interval in PAL VBlanks, accumulator updated.
; Requires v7_sched_step_den <= 65535, guaranteed by v7_setup_timing.
v7_next_interval:
        movem.l d1-d3,-(sp)
        move.l  v7_sched_accum,d0
        add.l   v7_sched_step_num,d0
        move.l  v7_sched_step_den,d1
        divu.w  d1,d0
        move.l  d0,d2
        and.l   #$0000FFFF,d0              ; quotient = interval
        swap    d2
        and.l   #$0000FFFF,d2              ; remainder
        move.l  d2,v7_sched_accum
        tst.l   d0
        bne.s   v7_next_interval_ok
        moveq   #1,d0                      ; should only be possible for >50 fps (rejected)
v7_next_interval_ok:
        movem.l (sp)+,d1-d3
        rts


        section data,data
        even

; --------------------------------------------------------------------
; TEST61 HAM6 lookup data.
; Target record key = Y4:U4:V4, 64 bytes per key:
;   +0 R4, +1 G4, +2 B4, +3 nearest direct palette index
;   +4 direct squared RGB error (word), +6 direct packed RGB state (word)
;   +8/+24/+40: 16-byte squared-error rows for R/G/B current components.
;   +56 packed target RGB $0RGB (word), +60 targetRGB<<12 (long).
; TEST61 uses +56/+60 to avoid rebuilding target state and transition offsets per pixel.
; --------------------------------------------------------------------

; TEST61 HAM6 direct base palette (COLOR00..COLOR15).
t44_palette:
        dc.w $000,$FFF,$457,$EDD,$B75,$411,$643,$CBB
        dc.w $235,$B53,$777,$100,$711,$A31,$D74,$BA9
t44_palette_end:

t44_target_lut:
        dc.b $00,$08,$00,$08,$00,$36,$02,$35,$00,$01,$04,$09,$10,$19,$24,$31
        dc.b $40,$51,$64,$79,$90,$A9,$C4,$E1,$40,$31,$24,$19,$10,$09,$04,$01
        dc.b $00,$01,$04,$09,$10,$19,$24,$31,$00,$01,$04,$09,$10,$19,$24,$31
        dc.b $40,$51,$64,$79,$90,$A9,$C4,$E1,$00,$80,$00,$00,$00,$08,$00,$00
        dc.b $00,$08,$00,$08,$00,$36,$02,$35,$00,$01,$04,$09,$10,$19,$24,$31
        dc.b $40,$51,$64,$79,$90,$A9,$C4,$E1,$40,$31,$24,$19,$10,$09,$04,$01
        dc.b $00,$01,$04,$09,$10,$19,$24,$31,$00,$01,$04,$09,$10,$19,$24,$31
        dc.b $40,$51,$64,$79,$90,$A9,$C4,$E1,$00,$80,$00,$00,$00,$08,$00,$00
        dc.b $00,$07,$00,$08,$00,$2D,$02,$35,$00,$01,$04,$09,$10,$19,$24,$31
        dc.b $40,$51,$64,$79,$90,$A9,$C4,$E1,$31,$24,$19,$10,$09,$04,$01,$00
        dc.b $01,$04,$09,$10,$19,$24,$31,$40,$00,$01,$04,$09,$10,$19,$24,$31
        dc.b $40,$51,$64,$79,$90,$A9,$C4,$E1,$00,$70,$00,$00,$00,$07,$00,$00
        dc.b $00,$06,$00,$00,$00,$24,$00,$00,$00,$01,$04,$09,$10,$19,$24,$31
        dc.b $40,$51,$64,$79,$90,$A9,$C4,$E1,$24,$19,$10,$09,$04,$01,$00,$01
