        move.l  a3,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    #$00001000,d0
        move.l  v9d_remote_port_abs,d1
        and.l   #$00000FFF,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #304,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #MMAL_PORT_INFO_SET,d0
        jsr     store_le32
        lea     20(a3),a0
        move.l  #$9F200002,d0
        jsr     store_le32
        lea     32(a3),a0
        move.l  component_handle,d0
        jsr     store_le32
        lea     36(a3),a0
        move.l  #MMAL_PORT_INPUT,d0
        jsr     store_le32
        ; index 0 at +40 remains clear.
        lea     88(a3),a0
        move.l  port_buf_num,d0
        jsr     store_le32
        lea     92(a3),a0
        move.l  port_buf_size,d0
        jsr     store_le32
        lea     100(a3),a0
        move.l  #MMAL_INPUT_USERDATA,d0
        jsr     store_le32
        lea     108(a3),a0
        move.l  port_fmt_type,d0
        jsr     store_le32
        lea     112(a3),a0
        move.l  port_fmt_encoding,d0
        jsr     store_le32
        lea     116(a3),a0
        move.l  port_fmt_variant,d0
        jsr     store_le32
        lea     124(a3),a0
        move.l  port_fmt_bitrate,d0
        jsr     store_le32
        lea     128(a3),a0
        move.l  port_fmt_flags,d0
        jsr     store_le32
        lea     132(a3),a0
        move.l  port_fmt_extra,d0
        jsr     store_le32
        lea     140(a3),a0
        move.l  port_video_width,d0
        jsr     store_le32
        lea     144(a3),a0
        move.l  port_video_height,d0
        jsr     store_le32
        lea     148(a3),a0
        move.l  port_crop_x,d0
        jsr     store_le32
        lea     152(a3),a0
        move.l  port_crop_y,d0
        jsr     store_le32
        lea     156(a3),a0
        move.l  port_crop_width,d0
        jsr     store_le32
        lea     160(a3),a0
        move.l  port_crop_height,d0
        jsr     store_le32
        lea     164(a3),a0
        move.l  port_fps_num,d0
        jsr     store_le32
        lea     168(a3),a0
        move.l  port_fps_den,d0
        jsr     store_le32
        lea     172(a3),a0
        move.l  port_par_num,d0
        jsr     store_le32
        lea     176(a3),a0
        move.l  port_par_den,d0
        jsr     store_le32
        lea     180(a3),a0
        move.l  port_color_space,d0
        jsr     store_le32

        move.l  port_fmt_extra,d7
        tst.l   d7
        beq.s   v9f_set_extra_done
        subq.l  #1,d7
        lea     input_extradata,a0
        lea     184(a3),a1
v9f_set_extra_copy:
        move.b  (a0)+,(a1)+
        dbra    d7,v9f_set_extra_copy
v9f_set_extra_done:
        move.l  #MMAL_PORT_INFO_SET,v9f_expect_type_abs
        move.l  #$9F200002,v9f_expect_context_abs
        move.l  #40,v9f_expect_min_abs
        move.l  #312,d0
        jsr     v9f_publish_wait
        tst.l   d0
        bne.w   v9f_set_fail
        lea     32(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   v9f_set_bad_consume
        lea     36(a2),a0
        jsr     load_le32
        cmp.l   component_handle,d0
        bne.s   v9f_set_bad_consume
        lea     40(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_INPUT,d0
        bne.s   v9f_set_bad_consume
        lea     44(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   v9f_set_bad_consume
        move.l  v9f_rx_size_abs,d0
