; ------------------------------------------------------------
; COMPONENT_ENABLE for the fresh second decoder.
; ------------------------------------------------------------
v9f_component_enable:
        movem.l d1-d7/a0-a1/a3,-(sp)
        move.l  #40,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v9f_comp_enable_fail
        move.l  a2,a3
        move.l  a3,a0
        moveq   #9,d7
v9f_comp_enable_clear:
        clr.l   (a0)+
        dbra    d7,v9f_comp_enable_clear
        move.l  a3,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    #$00001000,d0
        move.l  v9d_remote_port_abs,d1
        and.l   #$00000FFF,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a3),a0
        move.l  #28,d0
        jsr     store_le32
        lea     8(a3),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a3),a0
        move.l  #MMAL_COMPONENT_ENABLE,d0
        jsr     store_le32
        lea     20(a3),a0
        move.l  #$9F400001,d0
        jsr     store_le32
        lea     32(a3),a0
        move.l  component_handle,d0
        jsr     store_le32
        move.l  #MMAL_COMPONENT_ENABLE,v9f_expect_type_abs
        move.l  #$9F400001,v9f_expect_context_abs
        move.l  #28,v9f_expect_min_abs
        move.l  #40,d0
        jsr     v9f_publish_wait
        tst.l   d0
        bne.s   v9f_comp_enable_fail
        lea     32(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.s   v9f_comp_enable_bad
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
        moveq   #0,d0
        bra.s   v9f_comp_enable_done
v9f_comp_enable_bad:
        move.l  v9f_rx_size_abs,d0
        jsr     v9_consume_rx
v9f_comp_enable_fail:
