; Print current port_* snapshot after a stage-specific prefix was already printed.
v9f_log_port_values:
        movem.l d0-d3/a1,-(sp)
        lea     msg_v9f_handle,a1
        move.l  #msg_v9f_handle_end-msg_v9f_handle,d3
        jsr     print
        move.l  port_last_handle,d0
        jsr     print_hex32
        lea     msg_v9f_enabled,a1
        move.l  #msg_v9f_enabled_end-msg_v9f_enabled,d3
        jsr     print
        move.l  port_enabled,d0
        jsr     print_hex32
        lea     msg_v9f_buf,a1
        move.l  #msg_v9f_buf_end-msg_v9f_buf,d3
        jsr     print
        move.l  port_buf_num,d0
        jsr     print_hex32
        lea     msg_v9f_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  port_buf_size,d0
        jsr     print_hex32
        lea     msg_v9f_caps,a1
        move.l  #msg_v9f_caps_end-msg_v9f_caps,d3
        jsr     print
        move.l  port_caps,d0
        jsr     print_hex32
        lea     msg_v9f_fmt,a1
        move.l  #msg_v9f_fmt_end-msg_v9f_fmt,d3
        jsr     print
        move.l  port_fmt_type,d0
        jsr     print_hex32
        lea     msg_v9f_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  port_fmt_encoding,d0
        jsr     print_hex32
        jsr     newline
        movem.l (sp)+,d0-d3/a1
        rts

; ------------------------------------------------------------
; V9F high-level isolated second-decoder setup.
; Entry from V10 component-create success: shared slot RAM DMA-owned.
; Return D0=0/1 and always restore live slot RAM to DMA ownership.
; ------------------------------------------------------------
v9f_second_configure:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  #1,v9f_stage_abs
        move.l  v9e_comp_handle_abs,d0
        move.l  d0,component_handle
        move.l  v9d_remote_port_abs,d0
        move.l  d0,mmal_remote_port
        jsr     dma_post_all

        lea     msg_v9f_begin,a1
        move.l  #msg_v9f_begin_end-msg_v9f_begin,d3
        jsr     print

        ; Initial GET of all four classes, as an isolated baseline snapshot.
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_control_get
        move.l  port_last_handle,d0
        move.l  d0,control_port_handle
        lea     msg_v9f_control_get,a1
        move.l  #msg_v9f_control_get_end-msg_v9f_control_get,d3
        jsr     print
        jsr     v9f_log_port_values

        move.l  #2,v9f_stage_abs
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_input_get
        move.l  port_last_handle,d0
        move.l  d0,input_port_handle
        lea     msg_v9f_input_get,a1
        move.l  #msg_v9f_input_get_end-msg_v9f_input_get,d3
        jsr     print
        jsr     v9f_log_port_values

        move.l  #3,v9f_stage_abs
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_output_get
        move.l  port_last_handle,d0
        move.l  d0,output_port_handle
        lea     msg_v9f_output_get,a1
        move.l  #msg_v9f_output_get_end-msg_v9f_output_get,d3
        jsr     print
        jsr     v9f_log_port_values

        move.l  #4,v9f_stage_abs
        move.l  #MMAL_PORT_CLOCK,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_clock_get
        move.l  port_last_handle,d0
        move.l  d0,clock_port_handle
        lea     msg_v9f_clock_get,a1
        move.l  #msg_v9f_clock_get_end-msg_v9f_clock_get,d3
        jsr     print
        jsr     v9f_log_port_values

        ; CONTROL ENABLE: refresh snapshot, send ENABLE, verify enabled=1.
        move.l  #5,v9f_stage_abs
        move.l  #MMAL_PORT_CONTROL,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_control_enable
        move.l  control_port_handle,d0
        move.l  #MMAL_PORT_CONTROL,d1
        jsr     v9f_port_enable
        tst.l   d0
        bne.w   v9f_fail_control_enable
        move.l  #MMAL_PORT_CONTROL,port_query_type
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_control_enable
        cmpi.l  #1,port_enabled
        bne.w   v9f_fail_control_enable
        lea     msg_v9f_control_enable_ok,a1
        move.l  #msg_v9f_control_enable_ok_end-msg_v9f_control_enable_ok,d3
        jsr     print

        ; INPUT format: refresh, replace format with dynamic parsed H264 values.
        move.l  #6,v9f_stage_abs
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_input_set
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_H264,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        tst.l   v10b_input_is_mkv
        beq.s   v10g_second_fmt_flags_done
        move.l  #MMAL_ES_FORMAT_FLAG_FRAMED,port_fmt_flags
v10g_second_fmt_flags_done:
        move.l  h264_codec_config_len,d0
        move.l  d0,port_fmt_extra
        move.l  v6_src_aligned_w,d0
        move.l  d0,port_video_width
        move.l  v6_src_aligned_h,d0
        move.l  d0,port_video_height
        move.l  v6_src_crop_x,d0
        move.l  d0,port_crop_x
        move.l  v6_src_crop_y,d0
        move.l  d0,port_crop_y
        move.l  v6_src_visible_w,d0
        move.l  d0,port_crop_width
        move.l  v6_src_visible_h,d0
        move.l  d0,port_crop_height
        move.l  v7_fps_num,d0
        move.l  d0,port_fps_num
        move.l  v7_fps_den,d0
        move.l  d0,port_fps_den
        move.l  #1,port_par_num
        move.l  #1,port_par_den
        clr.l   port_color_space
        move.l  #INPUT_POOL_COUNT,port_buf_num
        move.l  #INPUT_DATA_SIZE,port_buf_size

        lea     input_extradata,a0
        moveq   #31,d7
v9f_input_extra_clear:
        clr.l   (a0)+
        dbra    d7,v9f_input_extra_clear
        move.l  h264_codec_config_len,d7
        tst.l   d7
        beq.w   v9f_fail_input_set
        subq.l  #1,d7
        lea     h264_file_extradata,a0
        lea     input_extradata,a1
v9f_input_extra_copy:
        move.b  (a0)+,(a1)+
        dbra    d7,v9f_input_extra_copy

        jsr     v9f_port_info_set_input
        tst.l   d0
        bne.w   v9f_fail_input_set

        ; Verify the committed format before enabling INPUT.
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_input_set
        move.l  port_last_handle,d0
        cmp.l   input_port_handle,d0
        bne.w   v9f_fail_input_set
        cmpi.l  #MMAL_ES_VIDEO,port_fmt_type
        bne.w   v9f_fail_input_set
        cmpi.l  #MMAL_ENCODING_H264,port_fmt_encoding
        bne.w   v9f_fail_input_set
        move.l  port_fmt_flags,d0
        and.l   #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        tst.l   v10b_input_is_mkv
        beq.s   v10g_second_verify_unframed
        cmpi.l  #MMAL_ES_FORMAT_FLAG_FRAMED,d0
        bne.w   v9f_fail_input_set
        bra.s   v10g_second_verify_flags_ok
v10g_second_verify_unframed:
        tst.l   d0
        bne.w   v9f_fail_input_set
v10g_second_verify_flags_ok:
        move.l  port_video_width,d0
        cmp.l   v6_src_aligned_w,d0
        bne.w   v9f_fail_input_set
        move.l  port_video_height,d0
        cmp.l   v6_src_aligned_h,d0
        bne.w   v9f_fail_input_set
        move.l  port_crop_width,d0
        cmp.l   v6_src_visible_w,d0
        bne.w   v9f_fail_input_set
        move.l  port_crop_height,d0
        cmp.l   v6_src_visible_h,d0
        bne.w   v9f_fail_input_set
        cmpi.l  #1,port_par_num
        bne.w   v9f_fail_input_set
        cmpi.l  #1,port_par_den
        bne.w   v9f_fail_input_set
        move.l  port_fmt_extra,d0
        cmp.l   h264_codec_config_len,d0
        bne.w   v9f_fail_input_set
        move.l  port_buf_num,d0
        cmp.l   #INPUT_POOL_COUNT,d0
        bcs.w   v9f_fail_input_set
        move.l  port_buf_size,d0
        cmp.l   #H264_MAX_DATA_LEN,d0
        bcs.w   v9f_fail_input_set
        move.l  h264_codec_config_len,d7
        subq.l  #1,d7
        lea     input_extradata,a0
        lea     h264_file_extradata,a1
v9f_input_extra_verify:
        move.b  (a0)+,d0
        cmp.b   (a1)+,d0
        bne.w   v9f_fail_input_set
        dbra    d7,v9f_input_extra_verify
        lea     msg_v9f_input_set_ok,a1
        move.l  #msg_v9f_input_set_ok_end-msg_v9f_input_set_ok,d3
        jsr     print
        lea     msg_v9f_geom,a1
        move.l  #msg_v9f_geom_end-msg_v9f_geom,d3
        jsr     print
        move.l  port_video_width,d0
        jsr     print_hex32
        lea     msg_v9f_x,a1
        moveq   #1,d3
        jsr     print
        move.l  port_video_height,d0
        jsr     print_hex32
        lea     msg_v9f_crop,a1
        move.l  #msg_v9f_crop_end-msg_v9f_crop,d3
        jsr     print
        move.l  port_crop_width,d0
        jsr     print_hex32
        lea     msg_v9f_x,a1
        moveq   #1,d3
        jsr     print
        move.l  port_crop_height,d0
        jsr     print_hex32
        lea     msg_v9f_fps,a1
        move.l  #msg_v9f_fps_end-msg_v9f_fps,d3
        jsr     print
        move.l  port_fps_num,d0
        jsr     print_hex32
        lea     msg_v9f_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  port_fps_den,d0
        jsr     print_hex32
        lea     msg_v9f_extra,a1
        move.l  #msg_v9f_extra_end-msg_v9f_extra,d3
        jsr     print
        move.l  port_fmt_extra,d0
        jsr     print_hex32
        jsr     newline

        ; INPUT ENABLE with the freshly returned snapshot, then verify.
        move.l  #7,v9f_stage_abs
        move.l  input_port_handle,d0
        move.l  #MMAL_PORT_INPUT,d1
        jsr     v9f_port_enable
        tst.l   d0
        bne.w   v9f_fail_input_enable
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     v9f_port_info_get
        tst.l   d0
        bne.w   v9f_fail_input_enable
        cmpi.l  #1,port_enabled
        bne.w   v9f_fail_input_enable
        cmpi.l  #MMAL_ENCODING_H264,port_fmt_encoding
        bne.w   v9f_fail_input_enable
        move.l  port_buf_num,d0
        move.l  d0,input_before_buf_num
        move.l  port_buf_size,d0
        move.l  d0,input_before_buf_size
        move.l  port_fmt_extra,d0
        move.l  d0,input_before_extra
        lea     msg_v9f_input_enable_ok,a1
        move.l  #msg_v9f_input_enable_ok_end-msg_v9f_input_enable_ok,d3
        jsr     print

        ; V12F: the restart path must build the same VideoCore-only graph as
        ; first start.  Decoder OUTPUT becomes OPQV, is tunnelled into ril.isp,
        ; and only the small I420 ISP OUTPUT is exposed to the host.
        move.l  #8,v9f_stage_abs
        lea     msg_v12f_second_graph_start,a1
        move.l  #msg_v12f_second_graph_start_end-msg_v12f_second_graph_start,d3
        jsr     print
        lea     msg_v12g_slot_safe,a1
        move.l  #msg_v12g_slot_safe_end-msg_v12g_slot_safe,d3
        jsr     print
        lea     msg_v12h_get_route,a1
        move.l  #msg_v12h_get_route_end-msg_v12h_get_route,d3
        jsr     print
        jsr     v12a_setup_isp_graph
        tst.l   d0
        bne.w   v9f_fail_output_enable
        lea     msg_v12f_second_graph_ok,a1
        move.l  #msg_v12f_second_graph_ok_end-msg_v12f_second_graph_ok,d3
        jsr     print

        ; Finally enable the decoder component. No buffer headers follow.
        move.l  #9,v9f_stage_abs
        jsr     v9f_component_enable
        tst.l   d0
        bne.w   v9f_fail_component_enable
        lea     msg_v9f_component_enable_ok,a1
        move.l  #msg_v9f_component_enable_ok_end-msg_v9f_component_enable_ok,d3
        jsr     print

        jsr     dma_pre_all
        lea     msg_v9f_ready,a1
        move.l  #msg_v9f_ready_end-msg_v9f_ready,d3
        jsr     print
        moveq   #0,d0
        bra.w   v9f_config_done

v9f_fail_control_get:
        lea     msg_v9f_fail_control_get,a1
        bra.w   v9f_config_fail
v9f_fail_input_get:
        lea     msg_v9f_fail_input_get,a1
        bra.w   v9f_config_fail
v9f_fail_output_get:
        lea     msg_v9f_fail_output_get,a1
        bra.w   v9f_config_fail
v9f_fail_clock_get:
        lea     msg_v9f_fail_clock_get,a1
        bra.w   v9f_config_fail
v9f_fail_control_enable:
        lea     msg_v9f_fail_control_enable,a1
        bra.s   v9f_config_fail
v9f_fail_input_set:
        lea     msg_v9f_fail_input_set,a1
        bra.s   v9f_config_fail
v9f_fail_input_enable:
        lea     msg_v9f_fail_input_enable,a1
        bra.s   v9f_config_fail
v9f_fail_output_enable:
        lea     msg_v9f_fail_output_enable,a1
        bra.s   v9f_config_fail
v9f_fail_component_enable:
        lea     msg_v9f_fail_component_enable,a1
v9f_config_fail:
        ; Stage-specific fail string length is selected below.
        ; All stage-specific fail strings have equal fixed length? No: compute
        ; via NUL-free sentinel is unavailable, so use individual dispatch below.
        ; A1 points at a dc.b line whose first byte length is stored separately
        ; by labels; branch to printer selector.
        move.l  v9f_stage_abs,d0
        cmpi.l  #1,d0
        beq.s   v9f_pf1
        cmpi.l  #2,d0
        beq.s   v9f_pf2
        cmpi.l  #3,d0
        beq.s   v9f_pf3
        cmpi.l  #4,d0
        beq.s   v9f_pf4
        cmpi.l  #5,d0
        beq.s   v9f_pf5
        cmpi.l  #6,d0
        beq.s   v9f_pf6
        cmpi.l  #7,d0
        beq.s   v9f_pf7
        cmpi.l  #8,d0
        beq.s   v9f_pf8
        bra.s   v9f_pf9
v9f_pf1:
        lea     msg_v9f_fail_control_get,a1
        move.l  #msg_v9f_fail_control_get_end-msg_v9f_fail_control_get,d3
        bra.s   v9f_pf_print
v9f_pf2:
        lea     msg_v9f_fail_input_get,a1
        move.l  #msg_v9f_fail_input_get_end-msg_v9f_fail_input_get,d3
        bra.s   v9f_pf_print
v9f_pf3:
        lea     msg_v9f_fail_output_get,a1
        move.l  #msg_v9f_fail_output_get_end-msg_v9f_fail_output_get,d3
        bra.s   v9f_pf_print
v9f_pf4:
        lea     msg_v9f_fail_clock_get,a1
        move.l  #msg_v9f_fail_clock_get_end-msg_v9f_fail_clock_get,d3
        bra.s   v9f_pf_print
v9f_pf5:
        lea     msg_v9f_fail_control_enable,a1
        move.l  #msg_v9f_fail_control_enable_end-msg_v9f_fail_control_enable,d3
        bra.s   v9f_pf_print
v9f_pf6:
        lea     msg_v9f_fail_input_set,a1
        move.l  #msg_v9f_fail_input_set_end-msg_v9f_fail_input_set,d3
        bra.s   v9f_pf_print
v9f_pf7:
        lea     msg_v9f_fail_input_enable,a1
        move.l  #msg_v9f_fail_input_enable_end-msg_v9f_fail_input_enable,d3
        bra.s   v9f_pf_print
v9f_pf8:
        lea     msg_v9f_fail_output_enable,a1
        move.l  #msg_v9f_fail_output_enable_end-msg_v9f_fail_output_enable,d3
        bra.s   v9f_pf_print
v9f_pf9:
        lea     msg_v9f_fail_component_enable,a1
        move.l  #msg_v9f_fail_component_enable_end-msg_v9f_fail_component_enable,d3
v9f_pf_print:
        jsr     print
        ; CPU owns shared slot RAM here on every helper return.
        jsr     dma_pre_all
        moveq   #1,d0
v9f_config_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; V9F diagnostics.
        section data,data
