msg_v10_alloc_fail_end:
        even

        section bss,bss
v10_mkv_buf_ptr:          ds.l 1
v10_mkv_handle:           ds.l 1
v10_mkv_read:             ds.l 1
v10_track_count:          ds.l 1
v10_in_track:             ds.l 1
v10_cur_track_num:        ds.l 1
v10_cur_track_type:       ds.l 1
v10_cur_codec_ptr:        ds.l 1
v10_cur_codec_len:        ds.l 1
v10_cur_codecpriv_ptr:    ds.l 1
v10_cur_codecpriv_len:    ds.l 1
v10_cur_default_dur:      ds.l 1
v10_cur_width:            ds.l 1
v10_cur_height:           ds.l 1
v10_cur_channels:         ds.l 1
v10_h264_found:           ds.l 1
v10_video_track_num:      ds.l 1
v10_video_codecpriv_ptr:  ds.l 1
v10_video_codecpriv_len:  ds.l 1
v10_video_default_dur:    ds.l 1
v10_video_width:          ds.l 1
v10_video_height:         ds.l 1
v10_nal_length_size:      ds.l 1
v10_avcc_ok:              ds.l 1
v10_avcc_sps_count:       ds.l 1
v10_timecode_scale:       ds.l 1
v10_cluster_timecode:     ds.l 1
v10_first_pts_found:      ds.l 1
v10_first_pts_ticks:      ds.l 1
v10_first_rel_tc:         ds.l 1


; ====================================================================
; V10P - BOUNDED-MEMORY MATROSKA -> ANNEX-B LIVE DEMUX
; ====================================================================
; This path never allocates the movie size and never creates a temporary file.
; The source is consumed sequentially through one fixed 64-KiB Fast-RAM window.
; Only the selected V_MPEG4/ISO/AVC SimpleBlock/Block payload is converted.
; AVC NAL length prefixes can span input-window boundaries. V10P preserves each
; Matroska video block as one MMAL access unit: large encoded frames may span any
; number of <=256-KiB MMAL buffers using FRAME_START/FRAME_END. Video lacing remains
; intentionally rejected. Non-video blocks (including AAC) are skipped in-stream.
;
; File offsets/element sizes are kept in 32 bits. This comfortably covers the
; requested 1-GiB class and classic AmigaDOS Seek/Read usage; >2-GiB container
; edge cases are not the goal of this first hardware test.

        section code,code

; Reset/free only V10P's process-local 64-KiB source window. DOS file closing is
; deliberately left to the already-proven t23 close sites.
v10b_stream_reset:
        movem.l d0-d2/a0-a1/a6,-(sp)
        move.l  v10b_io_ptr,d0
        beq.s   v10b_reset_no_io
        move.l  d0,a1
        move.l  #V10P_IO_SIZE,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   v10b_io_ptr
v10b_reset_no_io:
        clr.l   v10b_io_len
        clr.l   v10b_io_pos
        clr.l   v10b_abs_pos
        clr.l   v10b_reader_eof
        clr.l   v10b_reader_error
        clr.l   v10b_stream_started
        clr.l   v10b_stream_done
        clr.l   v10b_block_remaining
        clr.l   v10b_nal_remaining
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
        clr.l   v10b_emit_config_pos
        clr.l   v10g_chunk_flags
        clr.l   v10g_frame_open
        clr.l   v10g_frame_fragment_no
        clr.l   v10g_split_frame_count
        movem.l (sp)+,d0-d2/a0-a1/a6
        rts

; Open the original MKV and allocate exactly one 64-KiB Fast-RAM input window.
; D0=0 success, 1 failure.
v10b_stream_open:
        movem.l d1-d7/a0-a2/a6,-(sp)
        tst.l   v10b_stream_started
        bne.w   v10b_open_ok
        clr.l   v10b_stream_error_stage
        clr.l   v10b_io_len
        clr.l   v10b_io_pos
        clr.l   v10b_abs_pos
        clr.l   v10b_reader_eof
        clr.l   v10b_reader_error
        clr.l   v10b_stream_done
        clr.l   v10b_block_remaining
        clr.l   v10b_nal_remaining
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
        clr.l   v10b_cluster_timecode_live
        ; V10P single-axis test: SPS/PPS are already committed as INPUT
        ; PORT_INFO_SET extradata.  Do NOT send the same Annex-B SPS/PPS again
        ; as a synthetic MMAL_BUFFER_FLAG_CONFIG input buffer.
        move.l  h264_codec_config_len,d0
        move.l  d0,v10b_emit_config_pos
        clr.l   v10g_chunk_flags
        clr.l   v10g_frame_open
        clr.l   v10g_frame_fragment_no
        clr.l   v10g_split_frame_count
        clr.l   v10b_video_block_count
        move.l  #2,v10b_nal_count          ; avcC-exported SPS + PPS are decoder config
        clr.l   v10b_last_pts_ticks
        clr.l   v10b_pts_valid
        clr.l   t23_total_read

        move.l  a4,a6
        move.l  #V10P_IO_SIZE,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   v10b_open_alloc_fail
        move.l  d0,v10b_io_ptr

        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   v10b_open_file_fail
        move.l  d0,t23_file_handle
        move.l  #1,v10b_stream_started

        lea     msg_v10b_open_ok,a1
        move.l  #msg_v10b_open_ok_end-msg_v10b_open_ok,d3
        jsr     print
v10b_open_ok:
        moveq   #0,d0
        bra.s   v10b_open_done

v10b_open_file_fail:
        move.l  #$00000002,v10b_stream_error_stage
        jsr     v10b_stream_reset
        moveq   #1,d0
        bra.s   v10b_open_done
v10b_open_alloc_fail:
        move.l  #$00000001,v10b_stream_error_stage
        moveq   #1,d0
v10b_open_done:
        movem.l (sp)+,d1-d7/a0-a2/a6
        rts

; Refill the 64-KiB source window. D0=0 data, 2 clean source EOF, 1 error.
v10b_refill:
        movem.l d1-d3/a0/a6,-(sp)
        move.l  t23_file_handle,d1
        beq.s   v10b_refill_fail
        move.l  v10b_io_ptr,d2
        beq.s   v10b_refill_fail
        move.l  #V10P_IO_SIZE,d3
        move.l  a5,a6
        jsr     Read(a6)
        tst.l   d0
        bmi.s   v10b_refill_fail
        beq.s   v10b_refill_eof
        move.l  d0,v10b_io_len
        clr.l   v10b_io_pos
        moveq   #0,d0
        bra.s   v10b_refill_done
v10b_refill_eof:
        move.l  #1,v10b_reader_eof
        clr.l   v10b_io_len
        clr.l   v10b_io_pos
        moveq   #2,d0
        bra.s   v10b_refill_done
v10b_refill_fail:
        move.l  #1,v10b_reader_error
        move.l  #$00000003,v10b_stream_error_stage
        moveq   #1,d0
v10b_refill_done:
        movem.l (sp)+,d1-d3/a0/a6
        rts

; Get one source byte. D0=status (0/1/2), D1=byte when success.
v10b_get_byte:
        movem.l d2-d4/a0,-(sp)
v10b_get_byte_retry:
        move.l  v10b_io_pos,d2
        move.l  v10b_io_len,d3
        cmp.l   d3,d2
        bcs.s   v10b_get_byte_have
        jsr     v10b_refill
        tst.l   d0
        bne.s   v10b_get_byte_done
        bra.s   v10b_get_byte_retry
v10b_get_byte_have:
        move.l  v10b_io_ptr,a0
        adda.l  d2,a0
        moveq   #0,d1
        move.b  (a0),d1
        addq.l  #1,d2
        move.l  d2,v10b_io_pos
        addq.l  #1,v10b_abs_pos
        moveq   #0,d0
v10b_get_byte_done:
        movem.l (sp)+,d2-d4/a0
        rts

; Skip exactly D0 source bytes through the bounded reader. D0=0 success/1 fail.
v10b_skip_bytes:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
v10b_skip_loop:
        tst.l   d7
        beq.s   v10b_skip_ok
        move.l  v10b_io_len,d2
        move.l  v10b_io_pos,d1
        sub.l   d1,d2                    ; available bytes
        bne.s   v10b_skip_have
        jsr     v10b_refill
        tst.l   d0
        bne.s   v10b_skip_fail
        bra.s   v10b_skip_loop
v10b_skip_have:
        move.l  d7,d3
        cmp.l   d2,d3
        bls.s   v10b_skip_n_ready
        move.l  d2,d3
v10b_skip_n_ready:
        add.l   d3,v10b_io_pos
        add.l   d3,v10b_abs_pos
        sub.l   d3,d7
        bra.s   v10b_skip_loop
v10b_skip_ok:
        moveq   #0,d0
        bra.s   v10b_skip_done
v10b_skip_fail:
        move.l  #$00000004,v10b_stream_error_stage
        moveq   #1,d0
v10b_skip_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Copy exactly D0 source bytes into the current MMAL output chunk and advance
; both reader and output state. Caller guarantees D0 <= v10b_out_space.
v10b_copy_source_out:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  d0,d7
v10b_copy_src_loop:
        tst.l   d7
        beq.w   v10b_copy_src_ok
        move.l  v10b_io_len,d2
        move.l  v10b_io_pos,d1
        sub.l   d1,d2
        bne.s   v10b_copy_src_have
        jsr     v10b_refill
        tst.l   d0
        bne.w   v10b_copy_src_fail
        bra.s   v10b_copy_src_loop
v10b_copy_src_have:
        move.l  d7,d5
        cmp.l   d2,d5
        bls.s   v10b_copy_src_n_ready
        move.l  d2,d5
v10b_copy_src_n_ready:
        move.l  v10b_io_ptr,a1
        adda.l  v10b_io_pos,a1
        move.l  v10b_out_ptr,a2

        move.l  d5,d6
        lsr.l   #2,d6
        beq.s   v10b_copy_src_bytes
        subq.l  #1,d6
v10b_copy_src_long_loop:
        move.l  (a1)+,(a2)+
        dbra    d6,v10b_copy_src_long_loop
v10b_copy_src_bytes:
        move.l  d5,d6
        andi.l  #3,d6
        beq.s   v10b_copy_src_update
        subq.l  #1,d6
v10b_copy_src_byte_loop:
        move.b  (a1)+,(a2)+
        dbra    d6,v10b_copy_src_byte_loop
v10b_copy_src_update:
        add.l   d5,v10b_io_pos
        add.l   d5,v10b_abs_pos
        add.l   d5,v10b_out_ptr
        add.l   d5,v10b_out_count
        sub.l   d5,v10b_out_space
        sub.l   d5,d7
        bra.w   v10b_copy_src_loop
v10b_copy_src_ok:
        moveq   #0,d0
        bra.s   v10b_copy_src_done
v10b_copy_src_fail:
        move.l  #$00000005,v10b_stream_error_stage
        moveq   #1,d0
v10b_copy_src_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Emit D0 bytes from A0 into the current output chunk. D0=0 success/1 fail.
v10b_emit_mem:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7
        move.l  v10b_out_space,d1
        cmp.l   d7,d1
        bcs.s   v10b_emit_mem_fail
        move.l  v10b_out_ptr,a1
        move.l  d7,d6
        beq.s   v10b_emit_mem_ok
        subq.l  #1,d6
v10b_emit_mem_loop:
        move.b  (a0)+,(a1)+
        dbra    d6,v10b_emit_mem_loop
        add.l   d7,v10b_out_ptr
        add.l   d7,v10b_out_count
        sub.l   d7,v10b_out_space
v10b_emit_mem_ok:
        moveq   #0,d0
        bra.s   v10b_emit_mem_done
v10b_emit_mem_fail:
        move.l  #$00000006,v10b_stream_error_stage
        moveq   #1,d0
v10b_emit_mem_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Streaming EBML ID: D0=status, D1=ID (marker retained), D2=encoded bytes.
v10b_read_id:
        movem.l d3-d7/a0,-(sp)
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_read_id_done
        move.l  d1,d3
        moveq   #1,d4
        btst    #7,d3
        bne.s   v10b_id_len_ready
        moveq   #2,d4
        btst    #6,d3
        bne.s   v10b_id_len_ready
        moveq   #3,d4
        btst    #5,d3
        bne.s   v10b_id_len_ready
        moveq   #4,d4
        btst    #4,d3
        bne.s   v10b_id_len_ready
        move.l  #$00000007,v10b_stream_error_stage
        moveq   #1,d0
        bra.s   v10b_read_id_done
v10b_id_len_ready:
        move.l  d3,d5
        move.l  d4,d6
        subq.l  #1,d6
        beq.s   v10b_id_success
v10b_id_more:
        jsr     v10b_get_byte
        tst.l   d0
        beq.s   v10b_id_more_have
        move.l  #$00000008,v10b_stream_error_stage
        moveq   #1,d0
        bra.s   v10b_read_id_done
v10b_id_more_have:
        lsl.l   #8,d5
        or.l    d1,d5
        subq.l  #1,d6
        bne.s   v10b_id_more
v10b_id_success:
        move.l  d5,d1
        move.l  d4,d2
        moveq   #0,d0
v10b_read_id_done:
        movem.l (sp)+,d3-d7/a0
        rts

; Streaming EBML VINT size/value: D0=status, D1=value (FFFFFFFF=unknown), D2=len.
; Values larger than 32 bits are rejected unless their high bytes are zero.
v10b_read_size:
        movem.l d3-d7/a0-a3,-(sp)
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_size_done
        lea     v10b_vint_tmp,a2
        move.b  d1,(a2)
        move.l  d1,d3                    ; raw first byte
        move.l  #$00000080,d4            ; marker bit
        moveq   #1,d5                    ; encoded length
v10b_size_find_marker:
        move.l  d3,d6
        and.l   d4,d6
        bne.s   v10b_size_marker_found
        lsr.l   #1,d4
        addq.l  #1,d5
        cmpi.l  #9,d5
        bcs.s   v10b_size_find_marker
        move.l  #$00000009,v10b_stream_error_stage
        moveq   #1,d0
        bra.w   v10b_size_done
v10b_size_marker_found:
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   v10b_size_all_read
        lea     1(a2),a3
v10b_size_read_more:
        jsr     v10b_get_byte
        tst.l   d0
        beq.s   v10b_size_store_more
        move.l  #$0000000A,v10b_stream_error_stage
        moveq   #1,d0
        bra.w   v10b_size_done
v10b_size_store_more:
        move.b  d1,(a3)+
        subq.l  #1,d7
        bne.s   v10b_size_read_more
v10b_size_all_read:
        ; Unknown-size test: first stripped value equals marker-1 and every
        ; following encoded byte is FF. This also handles 8-byte 01 FF..FF.
        move.l  d4,d6
        subq.l  #1,d6                    ; first-byte value mask
        moveq   #0,d3
        move.b  (a2),d3
        and.l   d6,d3                    ; first stripped value
        cmp.l   d6,d3
        bne.s   v10b_size_not_unknown
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   v10b_size_unknown
        lea     1(a2),a3
v10b_size_unknown_loop:
        cmpi.b  #$FF,(a3)+
        bne.s   v10b_size_not_unknown
        subq.l  #1,d7
        bne.s   v10b_size_unknown_loop
v10b_size_unknown:
        move.l  #$FFFFFFFF,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.w   v10b_size_done

v10b_size_not_unknown:
        cmpi.l  #4,d5
        bls.s   v10b_size_build_short
        ; For 5..8-byte VINTs, all bytes above the low 32 bits must be zero.
        tst.l   d3                       ; stripped first high byte/value bits
        bne.w   v10b_size_too_large
        move.l  d5,d7
        sub.l   #4,d7                    ; number of high encoded bytes
        subq.l  #1,d7                    ; first byte already checked
        ble.s   v10b_size_build_last4
        lea     1(a2),a3
v10b_size_high_zero_loop:
        tst.b   (a3)+
        bne.w   v10b_size_too_large
        subq.l  #1,d7
        bne.s   v10b_size_high_zero_loop
v10b_size_build_last4:
        move.l  d5,d7
        sub.l   #4,d7
        lea     (a2,d7.l),a3
        moveq   #0,d6
        moveq   #3,d7
v10b_size_last4_loop:
        lsl.l   #8,d6
        moveq   #0,d3
        move.b  (a3)+,d3
        or.l    d3,d6
        dbra    d7,v10b_size_last4_loop
        move.l  d6,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.s   v10b_size_done

v10b_size_build_short:
        move.l  d3,d6
        move.l  d5,d7
        subq.l  #1,d7
        beq.s   v10b_size_short_done
        lea     1(a2),a3
v10b_size_short_loop:
        lsl.l   #8,d6
        moveq   #0,d3
        move.b  (a3)+,d3
        or.l    d3,d6
        subq.l  #1,d7
        bne.s   v10b_size_short_loop
v10b_size_short_done:
        move.l  d6,d1
        move.l  d5,d2
        moveq   #0,d0
        bra.s   v10b_size_done
v10b_size_too_large:
        move.l  #$0000000B,v10b_stream_error_stage
        moveq   #1,d0
v10b_size_done:
        movem.l (sp)+,d3-d7/a0-a3
        rts

; Read unsigned EBML integer payload of D0 bytes (up to 4 significant bytes;
; longer encodings are accepted only when their high bytes are zero).
; D0=status, D1=value.
v10b_read_uint:
        movem.l d2-d7,-(sp)
        move.l  d0,d7
        moveq   #0,d6
        tst.l   d7
        beq.s   v10b_uint_ok
        cmpi.l  #8,d7
        bhi.s   v10b_uint_fail
        move.l  d7,d5
        sub.l   #4,d5
        ble.s   v10b_uint_low_part
v10b_uint_high_loop:
        jsr     v10b_get_byte
        tst.l   d0
        bne.s   v10b_uint_fail
        tst.l   d1
        bne.s   v10b_uint_fail
        subq.l  #1,d5
        bne.s   v10b_uint_high_loop
v10b_uint_low_part:
        move.l  d7,d5
        cmpi.l  #4,d5
        bls.s   v10b_uint_low_count_ok
        moveq   #4,d5
v10b_uint_low_count_ok:
        tst.l   d5
        beq.s   v10b_uint_ok
v10b_uint_low_loop:
        jsr     v10b_get_byte
        tst.l   d0
        bne.s   v10b_uint_fail
        lsl.l   #8,d6
        or.l    d1,d6
        subq.l  #1,d5
        bne.s   v10b_uint_low_loop
v10b_uint_ok:
        move.l  d6,d1
        moveq   #0,d0
        bra.s   v10b_uint_done
v10b_uint_fail:
        move.l  #$0000000C,v10b_stream_error_stage
        moveq   #1,d0
v10b_uint_done:
        movem.l (sp)+,d2-d7
        rts

; Parse one SimpleBlock/Block payload of D0 bytes. Returns:
; D0=0 selected video block ready; D0=3 non-video block skipped; D0=1 failure.
v10b_begin_block:
        movem.l d1-d7/a0-a2,-(sp)
        move.l  d0,d7                    ; complete element payload bytes
        cmpi.l  #4,d7
        bcs.w   v10b_block_fail

        jsr     v10b_read_size           ; TrackNumber VINT uses same stripped value
        tst.l   d0
        bne.w   v10b_block_fail
        move.l  d1,d6                    ; track number
        move.l  d2,d5                    ; VINT bytes consumed
        move.l  d5,d4
        addq.l  #3,d4
        cmp.l   d7,d4
        bhi.w   v10b_block_fail

        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_block_fail
        move.l  d1,d3
        lsl.w   #8,d3
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_block_fail
        or.w    d1,d3
        ext.l   d3                       ; signed block-relative timecode
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_block_fail
        move.l  d1,d2                    ; flags

        sub.l   d4,d7                    ; AVC/audio payload remaining after block hdr
        cmp.l   v10_video_track_num,d6
        beq.s   v10b_block_selected
        move.l  d7,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.s   v10b_block_fail
        moveq   #3,d0
        bra.w   v10b_block_done

v10b_block_selected:
        move.l  d2,d1
        andi.l  #$00000006,d1            ; Matroska lacing bits
        beq.s   v10b_block_unlaced
        move.l  #1,v10b_laced_video_seen
        move.l  d7,d0
        jsr     v10b_skip_bytes
        move.l  #$0000000D,v10b_stream_error_stage
        moveq   #1,d0
        bra.s   v10b_block_done
v10b_block_unlaced:
        tst.l   d7
        beq.s   v10b_block_fail
        move.l  d7,v10b_block_remaining
        move.l  d7,v10h_current_frame_payload
        clr.l   v10b_nal_remaining
        addq.l  #1,v10b_video_block_count
        move.l  v10b_cluster_timecode_live,d1
        add.l   d3,d1
        move.l  d1,v10b_last_pts_ticks
        move.l  #1,v10b_pts_valid
        moveq   #0,d0
        bra.s   v10b_block_done
v10b_block_fail:
        move.l  #$0000000E,v10b_stream_error_stage
        moveq   #1,d0
v10b_block_done:
        movem.l (sp)+,d1-d7/a0-a2
        rts

; Find the next selected AVC block while walking the original Matroska file
; sequentially. D0=0 block ready, 2 clean file EOF, 1 malformed/unsupported.
v10b_find_video_block:
        movem.l d1-d7/a0-a3,-(sp)
v10b_find_loop:
        ; Close finite BlockGroup/Cluster scopes when their payload end is reached.
        move.l  v10b_blockgroup_end,d1
        beq.s   v10b_find_check_cluster
        cmpi.l  #$FFFFFFFF,d1
        beq.s   v10b_find_check_cluster
        move.l  v10b_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   v10b_find_check_cluster
        clr.l   v10b_blockgroup_end
v10b_find_check_cluster:
        move.l  v10b_cluster_end,d1
        beq.s   v10b_find_header
        cmpi.l  #$FFFFFFFF,d1
        beq.s   v10b_find_header
        move.l  v10b_abs_pos,d2
        cmp.l   d1,d2
        bcs.s   v10b_find_header
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end

v10b_find_header:
        jsr     v10b_read_id
        cmpi.l  #2,d0
        beq.w   v10b_find_eof
        tst.l   d0
        bne.w   v10b_find_fail
        move.l  d1,d5                    ; ID
        jsr     v10b_read_size
        tst.l   d0
        bne.w   v10b_find_fail
        move.l  d1,d6                    ; payload size / FFFFFFFF unknown

        move.l  #$FFFFFFFF,d7            ; payload end default for unknown size
        cmpi.l  #$FFFFFFFF,d6
        beq.s   v10b_find_end_ready
        move.l  v10b_abs_pos,d7
        add.l   d6,d7
        bcs.w   v10b_find_fail
v10b_find_end_ready:

        ; EBML header can be skipped wholesale; Segment and Cluster are masters
        ; we enter. Other metadata masters are skipped because V10F already parsed them.
        cmpi.l  #$1A45DFA3,d5            ; EBML
        beq.w   v10b_find_skip
        cmpi.l  #$18538067,d5            ; Segment
        beq.w   v10b_find_segment
        cmpi.l  #$1F43B675,d5            ; Cluster
        beq.w   v10b_find_cluster

        ; If a Segment-level master appears after an unknown-size Cluster, it
        ; implicitly ends that cluster for our flat streaming state machine.
        cmpi.l  #$114D9B74,d5            ; SeekHead
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1549A966,d5            ; Info
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1654AE6B,d5            ; Tracks
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1C53BB6B,d5            ; Cues
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1254C367,d5            ; Tags
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1941A469,d5            ; Attachments
        beq.s   v10b_find_segment_meta
        cmpi.l  #$1043A770,d5            ; Chapters
        beq.s   v10b_find_segment_meta
        bra.s   v10b_find_cluster_children
v10b_find_segment_meta:
        move.l  v10b_cluster_end,d1
        cmpi.l  #$FFFFFFFF,d1
        bne.w   v10b_find_skip
        clr.l   v10b_cluster_active
        clr.l   v10b_cluster_end
        clr.l   v10b_blockgroup_end
        bra.w   v10b_find_skip

v10b_find_cluster_children:
        tst.l   v10b_cluster_active
        beq.w   v10b_find_skip
        cmpi.l  #$000000E7,d5            ; Cluster Timecode
        beq.w   v10b_find_timecode
        cmpi.l  #$000000A0,d5            ; BlockGroup master
        beq.w   v10b_find_blockgroup
        cmpi.l  #$000000A3,d5            ; SimpleBlock
        beq.w   v10b_find_block
        cmpi.l  #$000000A1,d5            ; Block within BlockGroup
        bne.w   v10b_find_skip
        tst.l   v10b_blockgroup_end
        beq.w   v10b_find_skip
        bra.w   v10b_find_block

v10b_find_segment:
        move.l  d7,v10b_segment_end
        bra.w   v10b_find_loop
v10b_find_cluster:
        move.l  #1,v10b_cluster_active
        move.l  d7,v10b_cluster_end
        clr.l   v10b_blockgroup_end
        clr.l   v10b_cluster_timecode_live
        bra.w   v10b_find_loop
v10b_find_blockgroup:
        move.l  d7,v10b_blockgroup_end
        bra.w   v10b_find_loop
v10b_find_timecode:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   v10b_find_fail
        move.l  d6,d0
        jsr     v10b_read_uint
        tst.l   d0
        bne.w   v10b_find_fail
        move.l  d1,v10b_cluster_timecode_live
        bra.w   v10b_find_loop
v10b_find_block:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   v10b_find_fail
        move.l  d6,d0
        jsr     v10b_begin_block
        tst.l   d0
        beq.s   v10b_find_found
        cmpi.l  #3,d0
        beq.w   v10b_find_loop
        bra.w   v10b_find_fail
v10b_find_skip:
        cmpi.l  #$FFFFFFFF,d6
        beq.w   v10b_find_fail
        move.l  d6,d0
        jsr     v10b_skip_bytes
        tst.l   d0
        bne.w   v10b_find_fail
        bra.w   v10b_find_loop
v10b_find_found:
        moveq   #0,d0
        bra.s   v10b_find_done
v10b_find_eof:
        moveq   #2,d0
        bra.s   v10b_find_done
v10b_find_fail:
        tst.l   v10b_stream_error_stage
        bne.s   v10b_find_fail_stage_set
        move.l  #$0000000F,v10b_stream_error_stage
v10b_find_fail_stage_set:
        moveq   #1,d0
v10b_find_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Produce one <=256-KiB Annex-B fragment directly into bulk_data_ptr.
; D0=0 chunk ready, 2 clean end of selected MKV video, 1 failure.
;
; V10P difference: Matroska gives us access-unit boundaries.  Preserve those
; boundaries for MMAL.  A small access unit is one buffer with START|END; a large
; one is START|END; only access units above 256 KiB are split START/middle/END.  No fragment ever contains
; bytes from two different video blocks.  avcC-derived SPS/PPS stay exclusively in INPUT PORT_INFO_SET extradata.
; V10P deliberately emits no synthetic CONFIG input buffer before frame 0.
v10b_next_annexb_chunk:
        movem.l d1-d7/a0-a3,-(sp)
        jsr     v10b_stream_open
        tst.l   d0
        bne.w   v10b_chunk_fail
        tst.l   v10b_stream_done
        bne.w   v10b_chunk_eof

        move.l  bulk_data_ptr,d0
        move.l  d0,v10b_out_ptr
        clr.l   v10b_out_count
        move.l  #V10P_MKV_CHUNK,v10b_out_space
        clr.l   v10g_chunk_flags
        clr.l   v10h_chunk_fragment_no
        move.l  v10g_frame_open,d0
        beq.s   v10g_chunk_no_continuation
        addq.l  #1,v10g_frame_fragment_no
        move.l  v10g_frame_fragment_no,v10h_chunk_fragment_no
v10g_chunk_no_continuation:

        ; First MMAL input buffer is codec config only.  It is deliberately
        ; separate from frame 0 so FRAME_START really points at frame payload.
        move.l  h264_codec_config_len,d6
        move.l  v10b_emit_config_pos,d5
        cmp.l   d6,d5
        bcc.s   v10g_chunk_main
        sub.l   d5,d6
        move.l  #V10P_MKV_CHUNK,d7
        cmp.l   d7,d6
        bls.s   v10g_config_n_ready
        move.l  d7,d6
v10g_config_n_ready:
        lea     h264_file_extradata,a0
        adda.l  d5,a0
        move.l  d6,d0
        jsr     v10b_emit_mem
        tst.l   d0
        bne.w   v10b_chunk_fail
        add.l   d6,v10b_emit_config_pos
        move.l  #MMAL_BUFFER_FLAG_CONFIG,v10g_chunk_flags
        bra.w   v10b_chunk_ready

v10g_chunk_main:
        move.l  v10b_out_space,d7
        beq.w   v10b_chunk_ready

        ; Continue an AVC NAL payload that spans one or more MMAL fragments.
        move.l  v10b_nal_remaining,d6
        beq.s   v10g_chunk_need_nal_or_block
        move.l  d7,d5
        cmp.l   d6,d5
        bls.s   v10g_payload_n_ready
        move.l  d6,d5
v10g_payload_n_ready:
        move.l  d5,d0
        jsr     v10b_copy_source_out
        tst.l   d0
        bne.w   v10b_chunk_fail
        sub.l   d5,v10b_nal_remaining
        sub.l   d5,v10b_block_remaining

        ; End of this Matroska video block == end of this access unit.  Return
        ; immediately even if buffer space remains, so the next frame can never
        ; share this MMAL buffer.
        move.l  v10b_block_remaining,d0
        bne.w   v10g_chunk_main
        move.l  v10g_chunk_flags,d0
        or.l    #MMAL_BUFFER_FLAG_FRAME_END,d0
        move.l  d0,v10g_chunk_flags
        move.l  v10g_frame_fragment_no,d0
        cmpi.l  #1,d0
        bls.s   v10g_frame_not_split
        addq.l  #1,v10g_split_frame_count
v10g_frame_not_split:
        clr.l   v10g_frame_open
        clr.l   v10g_frame_fragment_no
        bra.w   v10b_chunk_ready

v10g_chunk_need_nal_or_block:
        move.l  v10b_block_remaining,d6
        beq.w   v10g_chunk_find_block

        ; Never split the synthetic 00 00 00 01 prefix across MMAL fragments.
        cmpi.l  #4,d7
        bcs.w   v10b_chunk_ready
        move.l  v10_nal_length_size,d5
        cmpi.l  #1,d5
        bcs.w   v10b_chunk_bad_avc
        cmpi.l  #4,d5
        bhi.w   v10b_chunk_bad_avc
        cmp.l   d5,d6
        bcs.w   v10b_chunk_bad_avc

        moveq   #0,d4                    ; AVC NAL payload length
        move.l  d5,d3
v10g_nal_len_loop:
        jsr     v10b_get_byte
        tst.l   d0
        bne.w   v10b_chunk_fail
        lsl.l   #8,d4
        or.l    d1,d4
        subq.l  #1,d3
        bne.s   v10g_nal_len_loop
        sub.l   d5,v10b_block_remaining
        tst.l   d4
        beq.w   v10b_chunk_bad_avc
        move.l  v10b_block_remaining,d6
        cmp.l   d6,d4
        bhi.w   v10b_chunk_bad_avc
        move.l  d4,v10b_nal_remaining
        addq.l  #1,v10b_nal_count
        lea     v10b_startcode,a0
        moveq   #4,d0
        jsr     v10b_emit_mem
        tst.l   d0
        bne.w   v10b_chunk_fail
        bra.w   v10g_chunk_main

v10g_chunk_find_block:
        ; If a frame is already open, reaching block_remaining=0 would have
        ; returned above.  Therefore a successful find here always starts a new
        ; access unit and this MMAL fragment gets FRAME_START.
        jsr     v10b_find_video_block
        tst.l   d0
        beq.s   v10g_chunk_new_frame
        cmpi.l  #2,d0
        bne.w   v10b_chunk_fail
        move.l  #1,v10b_stream_done
        move.l  v10b_out_count,d1
        bne.w   v10b_chunk_ready
        bra.w   v10b_chunk_eof
v10g_chunk_new_frame:
        move.l  #1,v10g_frame_open
        move.l  #1,v10g_frame_fragment_no
        move.l  #1,v10h_chunk_fragment_no
        move.l  #MMAL_BUFFER_FLAG_FRAME_START,v10g_chunk_flags
        bra.w   v10g_chunk_main

v10b_chunk_bad_avc:
        move.l  #$00000010,v10b_stream_error_stage
v10b_chunk_fail:
        moveq   #1,d0
        bra.s   v10b_chunk_done
v10b_chunk_eof:
        moveq   #2,d0
        bra.s   v10b_chunk_done
v10b_chunk_ready:
        move.l  v10b_out_count,d1
        beq.s   v10b_chunk_eof

        move.l  d1,v10b_chunk_len
        moveq   #0,d0
v10b_chunk_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

        section data,data
v10b_startcode:
        dc.l $00000001
msg_v10p_unsupported:
        dc.b "FEHLER: Video wird nicht unterstuetzt.",10
msg_v10p_unsupported_end:

msg_v10b_stream_ready:
        dc.b "[V10P] MKV-Metadaten/avcC OK; starte bounded-memory Live-Demux direkt zum MMAL-H264-Input.",10
        dc.b "[V10P] Diagnose: erster MMAL ERRO wird mit Status + letztem MKV-Input-Kontext geloggt und stoppt sofort.",10
msg_v10b_stream_ready_end:
msg_v10b_prepare_fail:
        dc.b "[V10P] FEHLER: MKV enthaelt im Probe-Fenster keine nutzbare H264/AVC-Spur mit avcC.",10
msg_v10b_prepare_fail_end:
msg_v10b_open_ok:
        dc.b "[V10P] MKV-Live-Stream: 64-KiB Dateifenster, 256-KiB MMAL-Input; Frames <=256 KiB als EIN START|END-Buffer; kein doppelter CONFIG-Buffer.",10
msg_v10b_open_ok_end:
msg_v10b_stream_eof:
        dc.b "[V10P] MKV-Quelle bis EOF gestreamt; an MMAL gelieferte Annex-B-Bytes: 0x"
msg_v10b_stream_eof_end:
msg_v10b_stream_stats:
        dc.b "[V10P] Video-Bloecke=0x"
msg_v10b_stream_stats_end:
msg_v10b_stream_nals:
        dc.b "  Annex-B-NALs=0x"
msg_v10b_stream_nals_end:
msg_v10g_stream_split:
        dc.b "  >64KiB/mehrteilige Video-Frames=0x"
msg_v10g_stream_split_end:
msg_v10b_stream_fail:
        dc.b "[V10P] FEHLER im MKV-Live-Demux. Stage=0x"
msg_v10b_stream_fail_end:
msg_v10b_stream_pos:
        dc.b "  MKV-Position=0x"
msg_v10b_stream_pos_end:
        even

        section bss,bss
v10b_input_is_mkv:          ds.l 1
v10b_io_ptr:                ds.l 1
v10b_io_len:                ds.l 1
v10b_io_pos:                ds.l 1
v10b_abs_pos:               ds.l 1
v10b_reader_eof:            ds.l 1
v10b_reader_error:          ds.l 1
v10b_stream_started:        ds.l 1
v10b_stream_done:           ds.l 1
v10b_stream_error_stage:    ds.l 1
v10b_chunk_len:             ds.l 1
v10b_out_ptr:               ds.l 1
v10b_out_count:             ds.l 1
v10b_out_space:             ds.l 1
v10b_emit_config_pos:       ds.l 1
v10b_segment_end:           ds.l 1
v10b_cluster_active:        ds.l 1
v10b_cluster_end:           ds.l 1
v10b_blockgroup_end:        ds.l 1
v10b_cluster_timecode_live: ds.l 1
v10b_block_remaining:       ds.l 1
v10b_nal_remaining:         ds.l 1
v10b_video_block_count:     ds.l 1
v10b_nal_count:             ds.l 1
v10b_laced_video_seen:      ds.l 1
v10b_last_pts_ticks:        ds.l 1
v10b_pts_valid:             ds.l 1
v10g_chunk_flags:           ds.l 1
v10g_frame_open:            ds.l 1
v10g_frame_fragment_no:     ds.l 1
v10g_split_frame_count:     ds.l 1
v10b_vint_tmp:              ds.b 8
        even


; ====================================================================
; V12D - VIDECORE ISP DOWNSCALE EXPERIMENT
; Shared first/restart graph. Stable V11 remains the reference branch.
; ====================================================================
        section bss,bss
v12a_decoder_handle:       ds.l 1
v12a_decoder_output:       ds.l 1
v12a_isp_handle:           ds.l 1
v12a_isp_input:            ds.l 1
v12a_isp_output:           ds.l 1
v12a_dec_buf_num:          ds.l 1
v12a_dec_buf_size:         ds.l 1
v12a_dec_w:                ds.l 1
v12a_dec_h:                ds.l 1
v12a_dec_crop_x:           ds.l 1
v12a_dec_crop_y:           ds.l 1
v12a_dec_crop_w:           ds.l 1
v12a_dec_crop_h:           ds.l 1
v12a_dec_fps_num:          ds.l 1
v12a_dec_fps_den:          ds.l 1
v12a_dec_par_num:          ds.l 1
v12a_dec_par_den:          ds.l 1
v12a_dec_colorspace:       ds.l 1
v12c_dec_variant:         ds.l 1
v12c_local_set_active:    ds.l 1
v12a_target_w:             ds.l 1
v12a_target_h:             ds.l 1
v12a_target_aw:            ds.l 1
v12a_target_ah:            ds.l 1
v12a_create_size:          ds.l 1
v12a_create_status:        ds.l 1
v12a_create_hstatus:       ds.l 1
v12a_create_type:          ds.l 1
v12a_create_context_rx:    ds.l 1
v12a_connect_status:       ds.l 1
v12a_connect_rx_size:      ds.l 1
v12a_req_status:           ds.l 1
v12a_req_rx_size:          ds.l 1
v12a_saved_input_handle:   ds.l 1
v12f_local_port:           ds.l 1    ; 0 first MMAL service, 1 restart service
v12f_local_bits:           ds.l 1    ; 0 or $00001000 in VCHIQ source field

        section code,code

; --------------------------------------------------------------------
; V12A - slot-safe synchronous RX helper.
; The V10P setup stayed inside MASTER slot 2. The extra ISP replies can
; cross the 4-KiB boundary, where VideoCore inserts a PADDING record and
; continues in MASTER_QUEUE[(rx_pos>>12)&63]. Keep the already proven
; TEST26C/TEST33 mapping and recycle semantics for these setup replies.
; --------------------------------------------------------------------
v12a_rx_advance_stride:
        movem.l d1-d3,-(sp)
        move.l  port_rx_pos,d1
        move.l  d1,d2
        add.l   d0,d2
        move.l  d2,port_rx_pos
        move.l  d1,d3
        and.l   #$fffff000,d3
        and.l   #$fffff000,d2
        cmp.l   d3,d2
        beq.s   v12a_rx_advance_ok
        move.l  d1,d0
        bsr     h31s_recycle_rx_slot
        tst.l   d0
        bne.s   v12a_rx_advance_fail
v12a_rx_advance_ok:
        moveq   #0,d0
        movem.l (sp)+,d1-d3
        rts
v12a_rx_advance_fail:
        moveq   #1,d0
        movem.l (sp)+,d1-d3
        rts

v12a_rx_consume_payload:
        add.l   #15,d0
        and.l   #$fffffff8,d0
        bra.w   v12a_rx_advance_stride

; Return A2 at the next non-PADDING MASTER record. D0=0 OK, 1 failure.
v12a_rx_map_data:
        movem.l d1-d4/a0-a1,-(sp)
v12a_rx_map_again:
        bsr     h26a_map_rx_current
        tst.l   d0
        bne.s   v12a_rx_map_fail
        move.l  a2,a0
        bsr     load_le32
        tst.l   d0
        bne.s   v12a_rx_map_ok
        ; PADDING must consume exactly the remainder of this 4-KiB slot.
        lea     4(a2),a0
        bsr     load_le32
        add.l   #15,d0
        and.l   #$fffffff8,d0
        move.l  d0,d4
        move.l  port_rx_pos,d1
        and.l   #$00000fff,d1
        move.l  #SLOT_SIZE,d2
        sub.l   d1,d2
        cmp.l   d2,d4
        bne.s   v12a_rx_map_fail
        move.l  d4,d0
        bsr     v12a_rx_advance_stride
        tst.l   d0
        bne.s   v12a_rx_map_fail
        bra.s   v12a_rx_map_again
v12a_rx_map_ok:
        moveq   #0,d0
        movem.l (sp)+,d1-d4/a0-a1
        rts
v12a_rx_map_fail:
        moveq   #1,d0
        movem.l (sp)+,d1-d4/a0-a1
        rts

; Create ril.isp on the already open local-0 MMAL service.
; Entry/exit shared slot RAM CPU-owned. D0=0 success, 1 failure.
v12a_create_isp:
        movem.l d1-d7/a0-a3,-(sp)
        ; request is 168-byte VCHIQ stride
        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_ispcreate_tx_legacy
        move.l  #168,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v12a_create_fail
        bra.s   v12g_ispcreate_tx_ready
v12g_ispcreate_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_ispcreate_tx_ready:

        move.l  a2,a0
        moveq   #41,d7
v12a_create_clear:
        clr.l   (a0)+
        dbra    d7,v12a_create_clear

        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #160,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_COMPONENT_CREATE,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$12A00001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  #$12A1A1A1,d0
        jsr     store_le32
        lea     36(a2),a0
        lea     v12a_isp_name,a1
        moveq   #7,d7
v12a_create_name:
        move.b  (a1)+,(a0)+
        dbra    d7,v12a_create_name

        add.l   #168,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   v12a_create_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v12a_create_wait_setup:
        move.l  #POLL_COUNT,d7
v12a_create_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v12a_create_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v12a_create_wait
        jsr     dma_post_all
        bra.w   v12a_create_fail
v12a_create_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   v12a_create_fail
        move.l  a2,a0
        jsr     load_le32
        move.l  d0,d5
        and.l   #$ff000000,d5
        cmp.l   #VCHIQ_MSG_DATA,d5
        bne.w   v12a_create_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_size
        cmp.l   #44,d0
        bcs.w   v12a_create_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v12a_create_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_type
        cmp.l   #MMAL_COMPONENT_CREATE,d0
        bne.w   v12a_create_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_context_rx
        cmp.l   #$12A00001,d0
        bne.w   v12a_create_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_hstatus
        tst.l   d0
        bne.w   v12a_create_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,v12a_create_status
        tst.l   d0
        bne.w   v12a_create_fail_consume
        lea     36(a2),a0
        jsr     load_le32
        move.l  d0,v12a_isp_handle
        tst.l   d0
        beq.w   v12a_create_fail_consume

        move.l  v12a_create_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   v12a_create_fail
        lea     msg_v12a_isp_created,a1
        move.l  #msg_v12a_isp_created_end-msg_v12a_isp_created,d3
        jsr     print
        move.l  v12a_isp_handle,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   v12a_create_done
v12a_create_fail_consume:
        move.l  v12a_create_size,d0
        jsr     v12a_rx_consume_payload
v12a_create_fail:
        lea     msg_v12a_isp_create_fail,a1
        move.l  #msg_v12a_isp_create_fail_end-msg_v12a_isp_create_fail,d3
        jsr     print
        move.l  v12a_create_status,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
v12a_create_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Connect decoder output -> ISP input using worker PORT_ACTION CONNECT.
v12a_connect_ports:
        movem.l d1-d7/a0-a3,-(sp)
        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_connect_tx_legacy
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v12a_connect_fail
        bra.s   v12g_connect_tx_ready
v12g_connect_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_connect_tx_ready:
        move.l  a2,a0
        moveq   #27,d7
v12a_connect_clear:
        clr.l   (a0)+
        dbra    d7,v12a_connect_clear
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        jsr     store_le32
        lea     4(a2),a0
        move.l  #100,d0
        jsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        jsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        jsr     store_le32
        lea     20(a2),a0
        move.l  #$12C00001,d0
        jsr     store_le32
        lea     32(a2),a0
        move.l  v12a_decoder_handle,d0
        jsr     store_le32
        lea     36(a2),a0
        move.l  v12a_decoder_output,d0
        jsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_CONNECT,d0
        jsr     store_le32
        lea     44(a2),a0
        move.l  v12a_isp_handle,d0
        jsr     store_le32
        lea     48(a2),a0
        move.l  v12a_isp_input,d0
        jsr     store_le32

        add.l   #112,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        jsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        jsr     load_le32
        move.l  d0,d6
        jsr     dma_pre_all
        tst.l   d6
        beq.s   v12a_connect_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v12a_connect_wait_setup:
        move.l  #POLL_COUNT,d7
v12a_connect_wait:
        jsr     short_delay
        jsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        jsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v12a_connect_have
        jsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v12a_connect_wait
        jsr     dma_post_all
        bra.w   v12a_connect_fail
v12a_connect_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   v12a_connect_fail
        lea     4(a2),a0
        jsr     load_le32
        move.l  d0,v12a_connect_rx_size
        cmp.l   #28,d0
        bcs.w   v12a_connect_fail
        lea     8(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v12a_connect_fail_consume
        lea     12(a2),a0
        jsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   v12a_connect_fail_consume
        lea     20(a2),a0
        jsr     load_le32
        cmp.l   #$12C00001,d0
        bne.w   v12a_connect_fail_consume
        lea     24(a2),a0
        jsr     load_le32
        tst.l   d0
        bne.w   v12a_connect_fail_consume
        lea     32(a2),a0
        jsr     load_le32
        move.l  d0,v12a_connect_status
        tst.l   d0
        bne.w   v12a_connect_fail_consume
        move.l  v12a_connect_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   v12a_connect_fail
        lea     msg_v12a_connected,a1
        move.l  #msg_v12a_connected_end-msg_v12a_connected,d3
        jsr     print
        moveq   #0,d0
        bra.s   v12a_connect_done
v12a_connect_fail_consume:
        move.l  v12a_connect_rx_size,d0
        jsr     v12a_rx_consume_payload
v12a_connect_fail:
        lea     msg_v12a_connect_fail,a1
        move.l  #msg_v12a_connect_fail_end-msg_v12a_connect_fail,d3
        jsr     print
        move.l  v12a_connect_status,d0
        jsr     print_hex32
        jsr     newline
        moveq   #1,d0
v12a_connect_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Apply buffer requirements to the connected ISP input. This mirrors
; mmal_vc_port_enable(): a connected output first sends
; MMAL_WORKER_PORT_ACTION_SET_REQUIREMENTS to the peer input, then enables
; the output. Current port_* globals must describe ISP INPUT 0.
v12a_set_isp_requirements:
        movem.l d1-d7/a0-a3,-(sp)
        ; 100-byte MMAL payload + 8-byte VCHIQ header -> 112-byte stride.
        ; V12G restart: map absolute TX position through SLAVE_QUEUE.
        tst.l   v12f_local_port
        beq.s   v12g_req_tx_legacy
        move.l  #112,d0
        jsr     h26a_reserve_tx
        tst.l   d0
        bne.w   v12a_req_fail
        bra.s   v12g_req_tx_ready
v12g_req_tx_legacy:
        move.l  slot_ptr,a0
        move.l  #34,d0
        lsl.l   #8,d0
        lsl.l   #4,d0
        adda.l  d0,a0
        move.l  port_tx_pos,d0
        adda.l  d0,a0
        move.l  a0,a2
v12g_req_tx_ready:
        move.l  a2,a0
        moveq   #27,d7
v12a_req_clear:
        clr.l   (a0)+
        dbra    d7,v12a_req_clear
        move.l  a2,a0
        move.l  #VCHIQ_MSG_DATA,d0
        or.l    v12f_local_bits,d0
        move.l  mmal_remote_port,d1
        and.l   #$00000fff,d1
        or.l    d1,d0
        bsr     store_le32
        lea     4(a2),a0
        move.l  #100,d0
        bsr     store_le32
        lea     8(a2),a0
        move.l  #MMAL_MAGIC,d0
        bsr     store_le32
        lea     12(a2),a0
        move.l  #MMAL_PORT_ACTION,d0
        bsr     store_le32
        lea     20(a2),a0
        move.l  #$12A60001,d0
        bsr     store_le32
        lea     32(a2),a0
        move.l  v12a_isp_handle,d0
        bsr     store_le32
        lea     36(a2),a0
        move.l  v12a_isp_input,d0
        bsr     store_le32
        lea     40(a2),a0
        move.l  #MMAL_PORT_ACTION_SET_REQUIREMENTS,d0
        bsr     store_le32
        ; struct mmal_port starts at offset 44.
        lea     52(a2),a0
        move.l  #MMAL_PORT_INPUT,d0
        bsr     store_le32
        lea     60(a2),a0
        move.l  port_enabled,d0
        bsr     store_le32
        lea     68(a2),a0
        move.l  port_buf_num_min,d0
        bsr     store_le32
        lea     72(a2),a0
        move.l  port_buf_size_min,d0
        bsr     store_le32
        lea     76(a2),a0
        move.l  port_buf_align,d0
        bsr     store_le32
        lea     80(a2),a0
        move.l  port_buf_num_rec,d0
        bsr     store_le32
        lea     84(a2),a0
        move.l  port_buf_size_rec,d0
        bsr     store_le32
        lea     88(a2),a0
        move.l  port_buf_num,d0
        bsr     store_le32
        lea     92(a2),a0
        move.l  port_buf_size,d0
        bsr     store_le32
        lea     100(a2),a0
        move.l  #$12A60001,d0
        bsr     store_le32
        lea     104(a2),a0
        move.l  port_caps,d0
        bsr     store_le32

        add.l   #112,port_tx_pos
        move.l  slot_ptr,a0
        lea     SLAVE_TXPOS(a0),a0
        move.l  port_tx_pos,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_FIR(a0),a0
        moveq   #1,d0
        bsr     store_le32
        move.l  slot_ptr,a0
        lea     MASTER_TRIG_ARM(a0),a0
        bsr     load_le32
        move.l  d0,d6
        bsr     dma_pre_all
        tst.l   d6
        beq.s   v12a_req_wait_setup
        moveq   #0,d0
        move.l  d0,VCHIQ_BELL2
v12a_req_wait_setup:
        move.l  #POLL_COUNT,d7
v12a_req_wait:
        bsr     short_delay
        bsr     dma_post_all
        move.l  slot_ptr,a0
        lea     MASTER_TXPOS(a0),a0
        bsr     load_le32
        cmp.l   port_rx_pos,d0
        bhi.s   v12a_req_have
        bsr     dma_pre_all
        subq.l  #1,d7
        bne.s   v12a_req_wait
        bsr     dma_post_all
        bra.w   v12a_req_fail
v12a_req_have:
        jsr     v12a_rx_map_data
        tst.l   d0
        bne.w   v12a_req_fail
        lea     4(a2),a0
        bsr     load_le32
        move.l  d0,v12a_req_rx_size
        cmp.l   #28,d0
        bcs.w   v12a_req_fail
        lea     8(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_MAGIC,d0
        bne.w   v12a_req_fail_consume
        lea     12(a2),a0
        bsr     load_le32
        cmp.l   #MMAL_PORT_ACTION,d0
        bne.w   v12a_req_fail_consume
        lea     20(a2),a0
        bsr     load_le32
        cmp.l   #$12A60001,d0
        bne.w   v12a_req_fail_consume
        lea     24(a2),a0
        bsr     load_le32
        tst.l   d0
        bne.w   v12a_req_fail_consume
        lea     32(a2),a0
        bsr     load_le32
        move.l  d0,v12a_req_status
        move.l  v12a_req_rx_size,d0
        jsr     v12a_rx_consume_payload
        tst.l   d0
        bne.w   v12a_req_fail
        move.l  v12a_req_status,d0
        tst.l   d0
        bne.w   v12a_req_fail
        lea     msg_v12a_requirements_ok,a1
        move.l  #msg_v12a_requirements_ok_end-msg_v12a_requirements_ok,d3
        bsr     print
        moveq   #0,d0
        bra.s   v12a_req_done
v12a_req_fail_consume:
        move.l  v12a_req_rx_size,d0
        jsr     v12a_rx_consume_payload
v12a_req_fail:
        lea     msg_v12a_requirements_fail,a1
        move.l  #msg_v12a_requirements_fail_end-msg_v12a_requirements_fail,d3
        bsr     print
        move.l  v12a_req_status,d0
        bsr     print_hex32
        bsr     newline
        moveq   #1,d0
v12a_req_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Main graph setup. Returns with decoder in component_handle and ISP output in
; output_port_handle/output_component_handle. Host output geometry is small.
v12a_setup_isp_graph:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  component_handle,v12a_decoder_handle
        move.l  input_port_handle,v12a_saved_input_handle
        move.l  output_port_handle,v12a_decoder_output

        ; Snapshot decoder output, deliberately WITHOUT the old 640x480 DMA cap.
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_type,d0
        cmp.l   #MMAL_ES_VIDEO,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_I420,d0
        bne.w   v12a_setup_fail
        move.l  port_buf_num,v12a_dec_buf_num
        move.l  port_buf_size,v12a_dec_buf_size
        move.l  port_video_width,v12a_dec_w
        move.l  port_video_height,v12a_dec_h
        move.l  port_crop_x,v12a_dec_crop_x
        move.l  port_crop_y,v12a_dec_crop_y
        move.l  port_crop_width,v12a_dec_crop_w
        move.l  port_crop_height,v12a_dec_crop_h
        move.l  port_fps_num,v12a_dec_fps_num
        move.l  port_fps_den,v12a_dec_fps_den
        move.l  port_par_num,v12a_dec_par_num
        move.l  port_par_den,v12a_dec_par_den
        move.l  port_color_space,v12a_dec_colorspace

        ; Reuse the already proven aspect calculation to choose the ISP crop size.
        move.l  port_buf_size,output_buf_size_saved
        move.l  port_video_width,output_width_saved
        move.l  port_video_height,output_height_saved
        move.l  port_crop_x,output_crop_x_saved
        move.l  port_crop_y,output_crop_y_saved
        move.l  port_crop_width,output_crop_w_saved
        move.l  port_crop_height,output_crop_h_saved
        jsr     v6_scale_prepare
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  v6_dst_w,v12a_target_w
        move.l  v6_dst_h,v12a_target_h
        move.l  v6_dst_w,d0
        add.l   #31,d0
        and.l   #$ffffffe0,d0
        move.l  d0,v12a_target_aw
        move.l  v6_dst_h,d0
        add.l   #15,d0
        and.l   #$fffffff0,d0
        move.l  d0,v12a_target_ah

        lea     msg_v12a_target,a1
        move.l  #msg_v12a_target_end-msg_v12a_target,d3
        jsr     print
        move.l  v12a_dec_crop_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_dec_crop_h,d0
        jsr     print_hex32
        lea     msg_v12a_arrow,a1
        move.l  #msg_v12a_arrow_end-msg_v12a_arrow,d3
        jsr     print
        move.l  v12a_target_w,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_target_h,d0
        jsr     print_hex32
        jsr     newline

        ; V12D: keep the full 1080p frame inside VideoCore.  The V12A
        ; I420 tunnel still described each connected buffer as a 0x2FD000-byte
        ; 1080p surface.  With only 32 MiB VC memory this can exhaust the
        ; firmware heap as soon as the decoder allocates its reference frames.
        ; The MMAL decoder supports OPQV output, and ril.isp supports OPQV input.
        ; Commit OPQV first, re-read its small buffer requirements, then commit
        ; the firmware MINIMUM header count before making the tunnel.
        move.l  v12a_decoder_handle,component_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_extra
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v12b_dec_opaque_first_num_ok
        moveq   #2,d0
v12b_dec_opaque_first_num_ok:
        move.l  d0,port_buf_num
        ; First format commit may still carry the old I420 buffer_size.  No
        ; buffers are allocated yet; the following GET reveals OPQV minima.
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail

        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_decoder_output,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v12a_setup_fail

        ; V12D: use the decoder's MINIMUM opaque header count, not the
        ; recommended count.  This firmware reports min=3, recommended=10 at
        ; 1080p.  The official MMAL decoder example likewise uses buffer_num_min.
        ; Keeping ten OPQV surfaces is a prime ENOSPC suspect with only 32 MiB
        ; VideoCore memory.  Never go below the firmware-declared minimum.
        move.l  port_buf_num_min,d0
        cmpi.l  #2,d0
        bcc.s   v12b_dec_num_two_ok
        moveq   #2,d0
v12b_dec_num_two_ok:
        move.l  d0,port_buf_num

        move.l  port_buf_size_min,d0
        cmp.l   port_buf_size_rec,d0
        bcc.s   v12b_dec_size_rec_ok
        move.l  port_buf_size_rec,d0
v12b_dec_size_rec_ok:
        tst.l   d0
        bne.s   v12b_dec_size_nonzero
        move.l  #128,d0
v12b_dec_size_nonzero:
        move.l  d0,port_buf_size
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail

        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v12a_setup_fail
        ; V12D: OPQV carries the underlying pixel format in variant.
        ; Hardware returned I420 ($30323449) here; ISP input must receive
        ; the same variant instead of zero or it rejects PORT_INFO_SET/EINVAL.
        move.l  port_fmt_variant,v12c_dec_variant
        move.l  port_buf_num,v12a_dec_buf_num
        move.l  port_buf_size,v12a_dec_buf_size
        lea     msg_v12b_decoder_opaque,a1
        move.l  #msg_v12b_decoder_opaque_end-msg_v12b_decoder_opaque,d3
        jsr     print
        move.l  v12a_dec_buf_num,d0
        jsr     print_hex32
        lea     msg_slash,a1
        moveq   #1,d3
        jsr     print
        move.l  v12a_dec_buf_size,d0
        jsr     print_hex32
        jsr     newline

        bsr     v12a_create_isp
        tst.l   d0
        bne.w   v12a_setup_fail

        ; ISP INPUT 0 = decoder full-size OPQV (opaque VideoCore frame handle).
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,v12a_isp_input
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_OPAQUE,port_fmt_encoding
        move.l  v12c_dec_variant,port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_dec_w,port_video_width
        move.l  v12a_dec_h,port_video_height
        move.l  v12a_dec_crop_x,port_crop_x
        move.l  v12a_dec_crop_y,port_crop_y
        move.l  v12a_dec_crop_w,port_crop_width
        move.l  v12a_dec_crop_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        move.l  v12a_dec_par_num,port_par_num
        move.l  v12a_dec_par_den,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        move.l  v12a_dec_buf_size,port_buf_size
        move.l  v12a_dec_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v12a_in_num_ok
        moveq   #2,d0
v12a_in_num_ok:
        move.l  d0,port_buf_num
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_OPAQUE,d0
        bne.w   v12a_setup_fail

        ; ISP OUTPUT 0 = small aspect-correct I420.
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,v12a_isp_output
        move.l  #MMAL_ES_VIDEO,port_fmt_type
        move.l  #MMAL_ENCODING_I420,port_fmt_encoding
        clr.l   port_fmt_variant
        clr.l   port_fmt_bitrate
        clr.l   port_fmt_flags
        clr.l   port_fmt_extra
        move.l  v12a_target_aw,port_video_width
        move.l  v12a_target_ah,port_video_height
        clr.l   port_crop_x
        clr.l   port_crop_y
        move.l  v12a_target_w,port_crop_width
        move.l  v12a_target_h,port_crop_height
        move.l  v12a_dec_fps_num,port_fps_num
        move.l  v12a_dec_fps_den,port_fps_den
        moveq   #1,d0
        move.l  d0,port_par_num
        move.l  d0,port_par_den
        move.l  v12a_dec_colorspace,port_color_space
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  v12a_target_aw,d0
        move.l  v12a_target_ah,d1
        mulu.w  d1,d0
        move.l  d0,d1
        lsr.l   #1,d1
        add.l   d1,d0
        move.l  d0,port_buf_size
        move.l  #1,v12c_local_set_active
        jsr     port_info_set_input
        clr.l   v12c_local_set_active
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_output,d0
        bne.w   v12a_setup_fail
        move.l  port_fmt_encoding,d0
        cmp.l   #MMAL_ENCODING_I420,d0
        bne.w   v12a_setup_fail

        ; Tunnel inside VideoCore.
        bsr     v12a_connect_ports
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Official MMAL VC client applies the peer input buffer requirements
        ; before enabling a connected output. Without this ril.isp can reject
        ; its input definition or never become enabled.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_last_handle,d0
        cmp.l   v12a_isp_input,d0
        bne.w   v12a_setup_fail
        bsr     v12a_set_isp_requirements
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Enable decoder OUTPUT; connected ISP INPUT should be enabled automatically.
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_decoder_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_buf_num,d0
        cmpi.l  #2,d0
        bcc.s   v12a_dec_out_num_ok
        moveq   #2,d0
v12a_dec_out_num_ok:
        move.l  d0,port_buf_num
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Verify ISP input came up through the tunnel.
        move.l  v12a_isp_handle,component_handle
        move.l  #MMAL_PORT_INPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_enabled,d0
        cmpi.l  #1,d0
        bne.w   v12a_setup_fail

        ; Enable host-facing ISP output with exactly two small buffers.
        move.l  v12a_isp_output,output_port_handle
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        moveq   #2,d0
        move.l  d0,port_buf_num
        move.l  d0,v10j_output_req_count
        jsr     port_enable_output_current
        tst.l   d0
        bne.w   v12a_setup_fail
        move.l  #MMAL_PORT_OUTPUT,port_query_type
        clr.l   port_query_index
        jsr     port_info_get
        move.l  port_enabled,d0
        cmpi.l  #1,d0
        bne.w   v12a_setup_fail

        ; ISP is a real component and must be enabled too.
        jsr     component_enable_worker
        tst.l   d0
        bne.w   v12a_setup_fail

        ; Save only the SMALL ISP output for existing host/HAM6 code.
        move.l  v12a_isp_handle,output_component_handle
        move.l  v12a_isp_output,output_port_handle
        move.l  port_buf_size,output_buf_size_saved
        move.l  port_video_width,output_width_saved
        move.l  port_video_height,output_height_saved
        move.l  port_crop_x,output_crop_x_saved
        move.l  port_crop_y,output_crop_y_saved
        move.l  port_crop_width,output_crop_w_saved
        move.l  port_crop_height,output_crop_h_saved
        move.l  output_width_saved,d0
        move.l  output_height_saved,d1
        mulu.w  d1,d0
        move.l  d0,d1
        lsr.l   #1,d1
        add.l   d1,d0
        move.l  d0,output_frame_bytes_expected
        cmp.l   output_buf_size_saved,d0
        bhi.w   v12a_setup_fail

        ; Restore decoder as the input-side component for H264/EOS messages.
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle

        lea     msg_v12a_graph_ok,a1
        move.l  #msg_v12a_graph_ok_end-msg_v12a_graph_ok,d3
        jsr     print
        move.l  output_width_saved,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  output_height_saved,d0
        jsr     print_hex32
        lea     msg_crop,a1
        move.l  #msg_crop_end-msg_crop,d3
        jsr     print
        move.l  output_crop_w_saved,d0
        jsr     print_hex32
        lea     msg_x,a1
        moveq   #1,d3
        jsr     print
        move.l  output_crop_h_saved,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   v12a_setup_done
v12a_setup_fail:
        move.l  v12a_decoder_handle,component_handle
        move.l  v12a_saved_input_handle,input_port_handle
        lea     msg_v12a_graph_fail,a1
        move.l  #msg_v12a_graph_fail_end-msg_v12a_graph_fail,d3
        jsr     print
        moveq   #1,d0
v12a_setup_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts


; ====================================================================
; V12E - bounded-memory MP4 demux for the V12D VideoCore ISP path.
; Only the moov atom (max 8 MiB) is retained in Fast RAM. Movie samples
; are read directly from disk and converted avcC length-prefix -> Annex-B.
; Decoder input stays UNFRAMED, so sample fragments may span MMAL buffers.
; ====================================================================
        section code,code

; D0=1 for .mp4 (case-insensitive), else 0.
v12e_is_mp4:
        movem.l d1-d3/a0-a1,-(sp)
        lea     t23_file_name,a0
        move.l  a0,a1
        clr.l   d1
v12e_ext_len:
        tst.b   (a1)
        beq.s   v12e_ext_len_done
        addq.l  #1,a1
        addq.l  #1,d1
        bra.s   v12e_ext_len
v12e_ext_len_done:
        cmpi.l  #4,d1
        bcs.s   v12e_ext_no
        subq.l  #4,a1
        cmpi.b  #$2E,(a1)
        bne.s   v12e_ext_no
        moveq   #0,d2
        move.b  1(a1),d2
        ori.b   #$20,d2
        cmpi.b  #$6D,d2
        bne.s   v12e_ext_no
        moveq   #0,d2
        move.b  2(a1),d2
        ori.b   #$20,d2
        cmpi.b  #$70,d2
        bne.s   v12e_ext_no
        moveq   #0,d2
        move.b  3(a1),d2
        ori.b   #$20,d2
        cmpi.b  #$34,d2
        bne.s   v12e_ext_no
        moveq   #1,d0
        bra.s   v12e_ext_done
v12e_ext_no:
        moveq   #0,d0
v12e_ext_done:
        movem.l (sp)+,d1-d3/a0-a1
        rts

; big-endian 32-bit load, A0 unchanged.
v12e_be32:
        moveq   #0,d0
        move.b  (a0),d0
        lsl.l   #8,d0
        move.b  1(a0),d0
        lsl.l   #8,d0
        move.b  2(a0),d0
        lsl.l   #8,d0
        move.b  3(a0),d0
        rts

; Read exactly D3 bytes from t23_file_handle to D2 address. D0=0/1.
v12e_read_exact:
        movem.l d1-d3/a6,-(sp)
        move.l  t23_file_handle,d1
        tst.l   d1
        beq.s   v12e_read_exact_fail
        move.l  a5,a6
        jsr     Read(a6)
        cmp.l   d3,d0
        bne.s   v12e_read_exact_fail
        moveq   #0,d0
        bra.s   v12e_read_exact_done
v12e_read_exact_fail:
        moveq   #1,d0
v12e_read_exact_done:
        movem.l (sp)+,d1-d3/a6
        rts

; Seek absolute D0. D0=0 success/1 failure.
v12e_seek_abs:
        movem.l d1-d3/a6,-(sp)
        move.l  d0,d2
        move.l  t23_file_handle,d1
        move.l  #OFFSET_BEGINNING,d3
        move.l  a5,a6
        jsr     Seek(a6)
        cmpi.l  #-1,d0
        beq.s   v12e_seek_fail
        moveq   #0,d0
        bra.s   v12e_seek_done
v12e_seek_fail:
        moveq   #1,d0
v12e_seek_done:
        movem.l (sp)+,d1-d3/a6
        rts

; Skip D0 bytes from current file position.
v12e_seek_cur:
        movem.l d1-d3/a6,-(sp)
        move.l  d0,d2
        move.l  t23_file_handle,d1
        move.l  #OFFSET_CURRENT,d3
        move.l  a5,a6
        jsr     Seek(a6)
        cmpi.l  #-1,d0
        beq.s   v12e_seekc_fail
        moveq   #0,d0
        bra.s   v12e_seekc_done
v12e_seekc_fail:
        moveq   #1,d0
v12e_seekc_done:
        movem.l (sp)+,d1-d3/a6
        rts

; Parse a memory atom header. A0=atom, A1=container end.
; success D1=0, D0=type, A2=payload, A3=end. failure D1=1.
v12e_mem_atom:
        movem.l d2-d5,-(sp)
        moveq   #1,d1
        move.l  a1,d0
        sub.l   a0,d0
        cmpi.l  #8,d0
        bcs.w   v12e_mem_atom_done
        move.l  a0,d2                  ; original atom start
        bsr     v12e_be32
        move.l  d0,d3                  ; size low
        lea     4(a0),a0
        bsr     v12e_be32
        move.l  d0,d4                  ; type
        move.l  d2,a0
        moveq   #8,d5                  ; header bytes
        cmpi.l  #1,d3
        bne.s   v12e_mem_normal
        move.l  a1,d0
        sub.l   d2,d0
        cmpi.l  #16,d0
        bcs.s   v12e_mem_atom_done
        move.l  d2,a0
        lea     8(a0),a0
        bsr     v12e_be32
        tst.l   d0
        bne.s   v12e_mem_atom_done     ; nested atom >4 GiB unsupported
        move.l  d2,a0
        lea     12(a0),a0
        bsr     v12e_be32
        move.l  d0,d3
        moveq   #16,d5
v12e_mem_normal:
        move.l  d2,a0
        tst.l   d3
        bne.s   v12e_mem_have_size
        move.l  a1,d3
        sub.l   d2,d3                  ; size 0 = rest of parent
v12e_mem_have_size:
        cmp.l   d5,d3
        bcs.s   v12e_mem_atom_done
        move.l  d2,a3
        adda.l  d3,a3
        cmpa.l  a1,a3
        bhi.s   v12e_mem_atom_done
        move.l  d2,a2
        adda.l  d5,a2
        move.l  d4,d0
        move.l  d2,a0                  ; leave A0 at atom start for callers
        moveq   #0,d1
v12e_mem_atom_done:
        movem.l (sp)+,d2-d5
        rts

; Parse avc1/avc3 stsd and locate avcC.
; A0=stsd payload, A1=end.
v12e_parse_stsd:
        movem.l d0-d7/a0-a3,-(sp)
        move.l  a1,d7
        move.l  d7,d0
        sub.l   a0,d0
        cmpi.l  #16,d0
        bcs.w   v12e_stsd_done
        lea     4(a0),a2
        move.l  a2,a0
        bsr     v12e_be32
        move.l  d0,d6                  ; entry count
        lea     4(a2),a2               ; first entry (payload+8)
v12e_stsd_entry_loop:
        tst.l   d6
        beq.w   v12e_stsd_done
        move.l  a2,a0
        move.l  d7,a1
        bsr     v12e_mem_atom
        tst.l   d1
        bne.w   v12e_stsd_done
        move.l  d0,d5
        move.l  a3,d4                  ; preserve next entry across child parsing
        cmpi.l  #$61766331,d5          ; avc1
        beq.s   v12e_stsd_avc
        cmpi.l  #$61766333,d5          ; avc3
        bne.s   v12e_stsd_next
v12e_stsd_avc:
        move.l  #1,v12e_track_avc
        ; VisualSampleEntry fixed header is 86 bytes including size/type.
        move.l  a0,a0                  ; atom start restored by mem_atom
        lea     86(a0),a0
        cmpa.l  a3,a0
        bcc.s   v12e_stsd_next
v12e_stsd_child:
        move.l  a3,a1
        bsr     v12e_mem_atom
        tst.l   d1
        bne.s   v12e_stsd_next
        cmpi.l  #$61766343,d0          ; avcC
        bne.s   v12e_stsd_child_next
        move.l  a2,v10_video_codecpriv_ptr
        move.l  a3,d0
        sub.l   a2,d0
        move.l  d0,v10_video_codecpriv_len
        clr.l   v10_avcc_ok
        jsr     v10_parse_avcc
        bra.s   v12e_stsd_next
v12e_stsd_child_next:
        move.l  a3,a0
        cmpa.l  a1,a0
        bcs.s   v12e_stsd_child
v12e_stsd_next:
        move.l  d4,a2
        subq.l  #1,d6
        bra.w   v12e_stsd_entry_loop
v12e_stsd_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; Recursive walker inside one trak. A0=start, A1=end.
v12e_walk_track:
        movem.l d0-d7/a0-a3,-(sp)
        move.l  a0,a2
        move.l  a1,d7
v12e_walk_loop:
        cmp.l   d7,a2
        bcc.w   v12e_walk_done
        move.l  a2,a0
        move.l  d7,a1
        bsr     v12e_mem_atom
        tst.l   d1
        bne.w   v12e_walk_done
        move.l  d0,d6                  ; type
        move.l  a3,d5                  ; atom end
        cmpi.l  #$68646C72,d6          ; hdlr
        bne.s   v12e_walk_not_hdlr
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #12,d0
        bcs.w   v12e_walk_advance
        lea     8(a2),a0
        bsr     v12e_be32
        cmpi.l  #$76696465,d0          ; vide
        bne.w   v12e_walk_advance
        move.l  #1,v12e_track_video
        bra.w   v12e_walk_advance
v12e_walk_not_hdlr:
        cmpi.l  #$73747364,d6          ; stsd
        bne.s   v12e_walk_not_stsd
        move.l  a2,a0
        move.l  a3,a1
        jsr     v12e_parse_stsd
        bra.w   v12e_walk_advance
v12e_walk_not_stsd:
        cmpi.l  #$73747363,d6          ; stsc
        bne.s   v12e_walk_not_stsc
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #8,d0
        bcs.w   v12e_walk_advance
        lea     4(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_stsc_count
        lea     8(a2),a0
        move.l  a0,v12e_stsc_ptr
        bra.w   v12e_walk_advance
v12e_walk_not_stsc:
        cmpi.l  #$7374737A,d6          ; stsz
        bne.s   v12e_walk_not_stsz
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #12,d0
        bcs.w   v12e_walk_advance
        lea     4(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_default_sample_size
        lea     8(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_sample_count
        lea     12(a2),a0
        move.l  a0,v12e_stsz_ptr
        bra.w   v12e_walk_advance
v12e_walk_not_stsz:
        cmpi.l  #$7374636F,d6          ; stco
        bne.s   v12e_walk_not_stco
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #8,d0
        bcs.w   v12e_walk_advance
        lea     4(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_chunk_count
        lea     8(a2),a0
        move.l  a0,v12e_chunk_ptr
        clr.l   v12e_chunk_is_co64
        bra.w   v12e_walk_advance
v12e_walk_not_stco:
        cmpi.l  #$636F3634,d6          ; co64
        bne.s   v12e_walk_not_table
        move.l  a3,d0
        sub.l   a2,d0
        cmpi.l  #8,d0
        bcs.w   v12e_walk_advance
        lea     4(a2),a0
        bsr     v12e_be32
        move.l  d0,v12e_chunk_count
        lea     8(a2),a0
        move.l  a0,v12e_chunk_ptr
        move.l  #1,v12e_chunk_is_co64
        bra.w   v12e_walk_advance
v12e_walk_not_table:
        ; recurse only through known container atoms in a trak
        cmpi.l  #$6D646961,d6          ; mdia
        beq.s   v12e_walk_recurse
        cmpi.l  #$6D696E66,d6          ; minf
        beq.s   v12e_walk_recurse
        cmpi.l  #$7374626C,d6          ; stbl
        bne.w   v12e_walk_advance
v12e_walk_recurse:
        move.l  a2,a0
        move.l  a3,a1
        jsr     v12e_walk_track
v12e_walk_advance:
        move.l  d5,a2
        bra.w   v12e_walk_loop
v12e_walk_done:
        movem.l (sp)+,d0-d7/a0-a3
        rts

; A0=trak payload, A1=end. D0=0 selected usable video track, 1 otherwise.
v12e_parse_trak:
        movem.l d1-d7/a0-a3,-(sp)
        clr.l   v12e_track_video
        clr.l   v12e_track_avc
        clr.l   v12e_stsc_ptr
        clr.l   v12e_stsc_count
        clr.l   v12e_stsz_ptr
        clr.l   v12e_sample_count
        clr.l   v12e_default_sample_size
        clr.l   v12e_chunk_ptr
        clr.l   v12e_chunk_count
        clr.l   v12e_chunk_is_co64
        clr.l   v10_avcc_ok
        jsr     v12e_walk_track
        tst.l   v12e_track_video
        beq.s   v12e_trak_fail
        tst.l   v12e_track_avc
        beq.s   v12e_trak_fail
        tst.l   v10_avcc_ok
        beq.s   v12e_trak_fail
        cmpi.l  #4,v10_nal_length_size
        bne.s   v12e_trak_fail
        tst.l   v12e_stsc_ptr
        beq.s   v12e_trak_fail
        tst.l   v12e_stsc_count
        beq.s   v12e_trak_fail
        tst.l   v12e_sample_count
        beq.s   v12e_trak_fail
        tst.l   v12e_chunk_ptr
        beq.s   v12e_trak_fail
        tst.l   v12e_chunk_count
        beq.s   v12e_trak_fail
        moveq   #0,d0
        bra.s   v12e_trak_done
v12e_trak_fail:
        moveq   #1,d0
v12e_trak_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Scan moov for first usable H264 video trak. D0=0 success/1 fail.
v12e_parse_moov:
        movem.l d1-d7/a0-a3,-(sp)
        move.l  v12e_moov_ptr,a2
        move.l  a2,a1
        adda.l  v12e_moov_bytes,a1
        move.l  a1,d7
v12e_moov_loop:
        cmp.l   d7,a2
        bcc.s   v12e_moov_fail
        move.l  a2,a0
        move.l  d7,a1
        bsr     v12e_mem_atom
        tst.l   d1
        bne.s   v12e_moov_fail
        move.l  a3,d6
        cmpi.l  #$7472616B,d0          ; trak
        bne.s   v12e_moov_next
        move.l  a2,a0
        move.l  a3,a1
        jsr     v12e_parse_trak
        tst.l   d0
        beq.s   v12e_moov_ok
v12e_moov_next:
        move.l  d6,a2
        bra.s   v12e_moov_loop
v12e_moov_ok:
        moveq   #0,d0
        bra.s   v12e_moov_done
v12e_moov_fail:
        moveq   #1,d0
v12e_moov_done:
        movem.l (sp)+,d1-d7/a0-a3
        rts

; Reset sample/chunk traversal after successful probe. D0=0/1.
v12e_stream_init:
        movem.l d1-d4/a0,-(sp)
        clr.l   v12e_sample_index
        move.l  #1,v12e_chunk_index
        clr.l   v12e_sample_in_chunk
        clr.l   v12e_sample_remaining
        clr.l   v12e_nal_remaining
        clr.l   v12e_samples_done
        clr.l   v12e_nal_count
        clr.l   v12e_error_stage
        clr.l   t23_total_read
        clr.l   v12e_stsc_index
        move.l  v12e_stsc_ptr,a0
        bsr     v12e_be32
        cmpi.l  #1,d0
        bne.s   v12e_stream_init_fail
        lea     4(a0),a0
        bsr     v12e_be32
        tst.l   d0
        beq.s   v12e_stream_init_fail
        move.l  d0,v12e_samples_per_chunk
        cmpi.l  #1,v12e_stsc_count
        bls.s   v12e_stream_no_next
        move.l  v12e_stsc_ptr,a0
        lea     12(a0),a0
        bsr     v12e_be32
        move.l  d0,v12e_next_stsc_chunk
        bra.s   v12e_stream_init_ok
v12e_stream_no_next:
        move.l  #$FFFFFFFF,v12e_next_stsc_chunk
v12e_stream_init_ok:
        moveq   #0,d0
        bra.s   v12e_stream_init_done
v12e_stream_init_fail:
        moveq   #1,d0
v12e_stream_init_done:
        movem.l (sp)+,d1-d4/a0
        rts

; Get sample size for current v12e_sample_index. D0=size, D1=0/1.
v12e_get_sample_size:
        movem.l d2/a0,-(sp)
        moveq   #1,d1
        move.l  v12e_sample_index,d2
        cmp.l   v12e_sample_count,d2
        bcc.s   v12e_gss_done
        move.l  v12e_default_sample_size,d0
        tst.l   d0
        bne.s   v12e_gss_ok
        move.l  v12e_stsz_ptr,a0
        move.l  d2,d0
        lsl.l   #2,d0
        adda.l  d0,a0
        bsr     v12e_be32
v12e_gss_ok:
        tst.l   d0
        beq.s   v12e_gss_done
        moveq   #0,d1
v12e_gss_done:
        movem.l (sp)+,d2/a0
        rts

; Get current 1-based chunk offset. D0=offset (<2GiB), D1=0/1.
v12e_get_chunk_offset:
        movem.l d2-d3/a0,-(sp)
        moveq   #1,d1
        move.l  v12e_chunk_index,d2
        tst.l   d2
        beq.s   v12e_gco_done
        cmp.l   v12e_chunk_count,d2
        bhi.s   v12e_gco_done
        subq.l  #1,d2
        move.l  v12e_chunk_ptr,a0
        tst.l   v12e_chunk_is_co64
        beq.s   v12e_gco_32
        move.l  d2,d3
        lsl.l   #3,d3
        adda.l  d3,a0
        bsr     v12e_be32
        tst.l   d0
        bne.s   v12e_gco_done
        lea     4(a0),a0
        bsr     v12e_be32
        bra.s   v12e_gco_check
v12e_gco_32:
        lsl.l   #2,d2
        adda.l  d2,a0
        bsr     v12e_be32
v12e_gco_check:
        btst    #31,d0
        bne.s   v12e_gco_done
        moveq   #0,d1
v12e_gco_done:
        movem.l (sp)+,d2-d3/a0
        rts

; Advance stsc mapping when entering a new chunk. D0=0/1.
v12e_update_stsc:
        movem.l d1-d4/a0,-(sp)
        move.l  v12e_chunk_index,d0
        cmp.l   v12e_next_stsc_chunk,d0
        bne.s   v12e_stsc_ok
        addq.l  #1,v12e_stsc_index
        move.l  v12e_stsc_index,d1
        cmp.l   v12e_stsc_count,d1
        bcc.s   v12e_stsc_fail
        move.l  v12e_stsc_ptr,a0
        move.l  d1,d2
        mulu.w  #12,d2
        adda.l  d2,a0
        lea     4(a0),a0
        bsr     v12e_be32
        tst.l   d0
        beq.s   v12e_stsc_fail
        move.l  d0,v12e_samples_per_chunk
        addq.l  #1,d1
        cmp.l   v12e_stsc_count,d1
        bcc.s   v12e_stsc_last
        move.l  v12e_stsc_ptr,a0
        move.l  d1,d2
        mulu.w  #12,d2
        adda.l  d2,a0
        bsr     v12e_be32
        move.l  d0,v12e_next_stsc_chunk
        bra.s   v12e_stsc_ok
v12e_stsc_last:
        move.l  #$FFFFFFFF,v12e_next_stsc_chunk
v12e_stsc_ok:
        moveq   #0,d0
        bra.s   v12e_stsc_done
v12e_stsc_fail:
        moveq   #1,d0
v12e_stsc_done:
        movem.l (sp)+,d1-d4/a0
        rts

; Prepare next sample and position DOS file at it. D0=0 data,2 EOF,1 fail.
v12e_prepare_sample:
        movem.l d1-d5/a0,-(sp)
        move.l  v12e_sample_index,d0
        cmp.l   v12e_sample_count,d0
        bcs.s   v12e_prep_have
        moveq   #2,d0
        bra.w   v12e_prep_done
v12e_prep_have:
        tst.l   v12e_sample_in_chunk
        bne.s   v12e_prep_same_chunk
        jsr     v12e_update_stsc
        tst.l   d0
        bne.s   v12e_prep_fail
        jsr     v12e_get_chunk_offset
        tst.l   d1
        bne.s   v12e_prep_fail
        move.l  d0,v12e_chunk_pos
        jsr     v12e_seek_abs
        tst.l   d0
        bne.s   v12e_prep_fail
v12e_prep_same_chunk:
        jsr     v12e_get_sample_size
        tst.l   d1
        bne.s   v12e_prep_fail
        move.l  d0,v12e_sample_remaining
        move.l  d0,v12e_sample_total
        clr.l   v12e_nal_remaining
        move.l  v12e_chunk_pos,d1
        add.l   d0,d1
        move.l  d1,v12e_chunk_pos
        addq.l  #1,v12e_sample_index
        moveq   #0,d0
        bra.s   v12e_prep_done
v12e_prep_fail:
        move.l  #$00000031,v12e_error_stage
        moveq   #1,d0
v12e_prep_done:
        movem.l (sp)+,d1-d5/a0
        rts

; Finish current sample and advance chunk/sample counters.
v12e_finish_sample:
        addq.l  #1,v12e_samples_done
        addq.l  #1,v12e_sample_in_chunk
        move.l  v12e_sample_in_chunk,d0
        cmp.l   v12e_samples_per_chunk,d0
        bcs.s   v12e_finish_done
        clr.l   v12e_sample_in_chunk
        addq.l  #1,v12e_chunk_index
v12e_finish_done:
        rts

; Return one <=64KiB Annex-B chunk in bulk_data_ptr.
; D0=0 data, 2 EOF, 1 failure. Flags stay zero (UNFRAMED decoder input).
v12e_next_annexb_chunk:
        movem.l d1-d7/a0-a3/a6,-(sp)
        clr.l   v12e_chunk_len
        move.l  v12e_sample_remaining,d0
        bne.s   v12e_chunk_have_sample
        jsr     v12e_prepare_sample
        cmpi.l  #2,d0
        beq.w   v12e_chunk_eof
        tst.l   d0
        bne.w   v12e_chunk_fail
v12e_chunk_have_sample:
        move.l  bulk_data_ptr,a2
        move.l  #H264_STREAM_CHUNK,d7
v12e_chunk_loop:
        move.l  v12e_sample_remaining,d0
        bne.s   v12e_chunk_not_sample_end
        tst.l   v12e_nal_remaining
        bne.w   v12e_chunk_fail_bad
        jsr     v12e_finish_sample
        bra.w   v12e_chunk_ready         ; one MP4 sample per logical output chunk
v12e_chunk_not_sample_end:
        tst.l   d7
        beq.w   v12e_chunk_ready
        move.l  v12e_nal_remaining,d0
        bne.s   v12e_chunk_copy_body
        cmpi.l  #4,v12e_sample_remaining
        bcs.w   v12e_chunk_fail_bad
        cmpi.l  #4,d7
        bcs.w   v12e_chunk_ready
        ; Read four-byte AVC NAL length directly into output then replace with startcode.
        move.l  a2,d2
        moveq   #4,d3
        jsr     v12e_read_exact
        tst.l   d0
        bne.w   v12e_chunk_fail_read
        move.l  a2,a0
        bsr     v12e_be32
        tst.l   d0
        beq.w   v12e_chunk_fail_bad
        move.l  v12e_sample_remaining,d1
        subq.l  #4,d1
        cmp.l   d1,d0
        bhi.w   v12e_chunk_fail_bad
        move.l  d0,v12e_nal_remaining
        clr.b   (a2)
        clr.b   1(a2)
        clr.b   2(a2)
        move.b  #1,3(a2)
        addq.l  #4,a2
        subq.l  #4,d7
        subq.l  #4,v12e_sample_remaining
        addq.l  #4,v12e_chunk_len
        addq.l  #1,v12e_nal_count
        bra.w   v12e_chunk_loop
v12e_chunk_copy_body:
        move.l  v12e_nal_remaining,d4
        cmp.l   v12e_sample_remaining,d4
        bls.s   v12e_body_sample_ok
        move.l  v12e_sample_remaining,d4
v12e_body_sample_ok:
        cmp.l   d7,d4
        bls.s   v12e_body_cap_ok
        move.l  d7,d4
v12e_body_cap_ok:
        tst.l   d4
        beq.w   v12e_chunk_ready
        move.l  a2,d2
        move.l  d4,d3
        jsr     v12e_read_exact
        tst.l   d0
        bne.w   v12e_chunk_fail_read
        adda.l  d4,a2
        sub.l   d4,d7
        sub.l   d4,v12e_sample_remaining
        sub.l   d4,v12e_nal_remaining
        add.l   d4,v12e_chunk_len
        bra.w   v12e_chunk_loop
v12e_chunk_ready:
        move.l  v12e_chunk_len,d0
        tst.l   d0
        beq.s   v12e_chunk_fail_bad
        moveq   #0,d0
        bra.s   v12e_chunk_done
v12e_chunk_eof:
        moveq   #2,d0
        bra.s   v12e_chunk_done
v12e_chunk_fail_read:
        move.l  #$00000033,v12e_error_stage
        bra.s   v12e_chunk_fail
v12e_chunk_fail_bad:
        move.l  #$00000034,v12e_error_stage
v12e_chunk_fail:
        moveq   #1,d0
v12e_chunk_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

; Free only the bounded MP4 moov allocation. File handle is owned by close_prog.
v12e_free_mp4:
        movem.l d0-d1/a1/a6,-(sp)
        move.l  v12e_moov_ptr,d0
        beq.s   v12e_free_done
        move.l  d0,a1
        move.l  v12e_moov_alloc,d0
        move.l  a4,a6
        jsr     FreeMem(a6)
        clr.l   v12e_moov_ptr
        clr.l   v12e_moov_alloc
        clr.l   v12e_moov_bytes
v12e_free_done:
        movem.l (sp)+,d0-d1/a1/a6
        rts

; Open MP4, locate/load moov, select H264 video track and init sample traversal.
; D0=0 success, 1 unsupported/error.
v12e_mp4_probe:
        movem.l d1-d7/a0-a3/a6,-(sp)
        jsr     v12e_free_mp4
        clr.l   t23_file_handle
        clr.l   h264_codec_config_len
        clr.l   h264_sps_len
        clr.l   h264_pps_len
        clr.l   v10_avcc_ok
        lea     msg_v12e_mp4_probe,a1
        move.l  #msg_v12e_mp4_probe_end-msg_v12e_mp4_probe,d3
        jsr     print
        move.l  a5,a6
        lea     t23_file_name,a0
        move.l  a0,d1
        move.l  #MODE_OLDFILE,d2
        jsr     Open(a6)
        tst.l   d0
        beq.w   v12e_probe_fail
        move.l  d0,t23_file_handle
v12e_probe_top_loop:
        move.l  t23_file_handle,d1
        lea     v12e_atom_hdr,a0
        move.l  a0,d2
        moveq   #8,d3
        move.l  a5,a6
        jsr     Read(a6)
        cmpi.l  #8,d0
        bne.w   v12e_probe_fail
        lea     v12e_atom_hdr,a0
        bsr     v12e_be32
        move.l  d0,d6                  ; atom size
        lea     v12e_atom_hdr+4,a0
        bsr     v12e_be32
        move.l  d0,d7                  ; type
        moveq   #8,d5                  ; header bytes
        cmpi.l  #1,d6
        bne.s   v12e_probe_size32
        move.l  t23_file_handle,d1
        lea     v12e_atom_hdr+8,a0
        move.l  a0,d2
        moveq   #8,d3
        move.l  a5,a6
        jsr     Read(a6)
        cmpi.l  #8,d0
        bne.w   v12e_probe_fail
        lea     v12e_atom_hdr+8,a0
        bsr     v12e_be32
        tst.l   d0
        bne.w   v12e_probe_fail
        lea     v12e_atom_hdr+12,a0
        bsr     v12e_be32
        move.l  d0,d6
        moveq   #16,d5
v12e_probe_size32:
        tst.l   d6
        beq.w   v12e_probe_fail
        cmp.l   d5,d6
        bcs.w   v12e_probe_fail
        move.l  d6,d4
        sub.l   d5,d4                  ; payload bytes
        cmpi.l  #$6D6F6F76,d7          ; moov
        beq.s   v12e_probe_found_moov
        move.l  d4,d0
        jsr     v12e_seek_cur
        tst.l   d0
        bne.w   v12e_probe_fail
        bra.w   v12e_probe_top_loop
v12e_probe_found_moov:
        tst.l   d4
        beq.w   v12e_probe_fail
        cmpi.l  #V12E_MAX_MOOV,d4
        bhi.w   v12e_probe_fail
        move.l  a4,a6
        move.l  d4,d0
        move.l  #MEMF_FAST,d1
        jsr     AllocMem(a6)
        tst.l   d0
        beq.w   v12e_probe_fail
        move.l  d0,v12e_moov_ptr
        move.l  d4,v12e_moov_alloc
        move.l  d4,v12e_moov_bytes
        move.l  d0,d2
        move.l  d4,d3
        jsr     v12e_read_exact
        tst.l   d0
        bne.w   v12e_probe_fail
        jsr     v12e_parse_moov
        tst.l   d0
        bne.w   v12e_probe_fail
        jsr     v12e_stream_init
        tst.l   d0
        bne.w   v12e_probe_fail
        lea     msg_v12e_mp4_tables,a1
        move.l  #msg_v12e_mp4_tables_end-msg_v12e_mp4_tables,d3
        jsr     print
        move.l  v12e_sample_count,d0
        jsr     print_hex32
        lea     msg_v12e_mp4_chunks,a1
        move.l  #msg_v12e_mp4_chunks_end-msg_v12e_mp4_chunks,d3
        jsr     print
        move.l  v12e_chunk_count,d0
        jsr     print_hex32
        jsr     newline
        moveq   #0,d0
        bra.s   v12e_probe_done
v12e_probe_fail:
        moveq   #1,d0
v12e_probe_done:
        movem.l (sp)+,d1-d7/a0-a3/a6
        rts

        section data,data
msg_v12e_mp4_probe:
        dc.b "h264rgb V13Fix - MP4/H264 + VideoCore ISP Downscale",10
        dc.b "[V13] Suche moov + H264 avc1/avc3; nur moov wird begrenzt in Fast-RAM geladen.",10
msg_v12e_mp4_probe_end:
msg_v12e_mp4_tables:
        dc.b "[V13] MP4 H264/avcC/Sample-Tabellen OK. Samples=0x"
msg_v12e_mp4_tables_end:
msg_v12e_mp4_chunks:
        dc.b "  Chunks=0x"
msg_v12e_mp4_chunks_end:
msg_v12e_mp4_ready:
        dc.b "[V13] MP4 bereit; Video-Samples -> Annex-B UNFRAMED -> VideoCore Decoder -> ISP.",10
msg_v12e_mp4_ready_end:
msg_v12e_mp4_unsupported:
        dc.b "[V13] FEHLER: Video wird nicht unterstuetzt. MP4 braucht avc1/avc3 + avcC (4-Byte NAL) + stsc/stsz/stco oder co64.",10
msg_v12e_mp4_unsupported_end:
msg_v12e_mp4_eof:
        dc.b "[V13] MP4-Video-Samples bis EOF gestreamt; Annex-B-Bytes: 0x"
msg_v12e_mp4_eof_end:
msg_v12e_mp4_stats:
        dc.b "[V13] Video-Samples=0x"
msg_v12e_mp4_stats_end:
msg_v12e_mp4_nals:
        dc.b "  Annex-B-NALs=0x"
msg_v12e_mp4_nals_end:
msg_v12e_mp4_stream_fail:
        dc.b "[V13] FEHLER im MP4-Live-Demux. Stage=0x"
msg_v12e_mp4_stream_fail_end:
        even

        section data,data
v12a_isp_name:
        dc.b "ril.isp",0
        even
msg_v12a_graph_start:
        dc.b 10,"[V13] VideoCore-Downscale: Decoder -> ril.isp -> kleines I420 -> HAM6.",10
msg_v12a_graph_start_end:
msg_v12a_isp_created:
        dc.b "[V13] ril.isp COMPONENT_CREATE OK, handle=0x"
msg_v12a_isp_created_end:
msg_v12b_decoder_opaque:
        dc.b "[V13] Decoder OUTPUT auf OPQV/zero-copy; Buffer n/s=0x"
msg_v12b_decoder_opaque_end:
msg_v12a_isp_create_fail:
        dc.b "[V13] FEHLER: ril.isp konnte nicht erzeugt werden. status=0x"
msg_v12a_isp_create_fail_end:
msg_v12a_target:
        dc.b "[V13] VC-Resize sichtbare Quelle 0x"
msg_v12a_target_end:
msg_v12a_arrow:
        dc.b " -> Ziel 0x"
msg_v12a_arrow_end:
msg_v12a_connected:
        dc.b "[V13] VideoCore-OPQV-Tunnel decoder.output -> isp.input: OK",10
msg_v12a_connected_end:
msg_v12a_requirements_ok:
        dc.b "[V13] ISP INPUT SET_REQUIREMENTS vor Decoder-OUTPUT ENABLE: OK",10
msg_v12a_requirements_ok_end:
msg_v12a_requirements_fail:
        dc.b "[V13] FEHLER: ISP INPUT SET_REQUIREMENTS status=0x"
msg_v12a_requirements_fail_end:
msg_v12a_connect_fail:
        dc.b "[V13] FEHLER: PORT_ACTION CONNECT status=0x"
msg_v12a_connect_fail_end:
msg_v12a_graph_ok:
        dc.b "[V13] ISP-Graph aktiv. Host sieht nur I420 0x"
msg_v12a_graph_ok_end:
msg_v12a_graph_fail:
        dc.b "[V13] FEHLER: ISP-Graph konnte nicht vollstaendig aufgebaut werden. Bitte Log schicken.",10
msg_v12a_graph_fail_end:
        even


        section bss,bss
v12e_input_is_mp4:          ds.l 1
v12e_moov_ptr:              ds.l 1
v12e_moov_alloc:            ds.l 1
v12e_moov_bytes:            ds.l 1
v12e_track_video:           ds.l 1
v12e_track_avc:             ds.l 1
v12e_stsc_ptr:              ds.l 1
v12e_stsc_count:            ds.l 1
v12e_stsz_ptr:              ds.l 1
v12e_sample_count:          ds.l 1
v12e_default_sample_size:   ds.l 1
v12e_chunk_ptr:             ds.l 1
v12e_chunk_count:           ds.l 1
v12e_chunk_is_co64:         ds.l 1
v12e_sample_index:          ds.l 1
v12e_chunk_index:           ds.l 1
v12e_sample_in_chunk:       ds.l 1
v12e_samples_per_chunk:     ds.l 1
v12e_stsc_index:            ds.l 1
v12e_next_stsc_chunk:       ds.l 1
v12e_chunk_pos:             ds.l 1
v12e_sample_remaining:      ds.l 1
v12e_sample_total:          ds.l 1
v12e_nal_remaining:         ds.l 1
v12e_chunk_len:             ds.l 1
v12e_samples_done:          ds.l 1
v12e_nal_count:             ds.l 1
v12e_error_stage:           ds.l 1
v12e_atom_hdr:              ds.b 16
        even
